'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';

export default function ForgotPasswordPage() {
  const router = useRouter();
  const [identifier, setIdentifier] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await fetch('/api/v1/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ identifier })
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.message || 'Failed to process request');
      }

      setSuccess(true);
      router.push(`/reset-password?email=${encodeURIComponent(data.email)}`);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', alignItems: 'center', justifyContent: 'center', background: 'var(--color-bg-base)', padding: '1rem' }}>
      <div className="glass-panel" style={{ width: '100%', maxWidth: '440px', padding: '2.5rem' }}>

        <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' }}>
            <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: 'var(--color-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 800, fontSize: '1.25rem' }}>T</div>
            <span style={{ fontSize: '1.5rem', fontWeight: 800, fontFamily: 'var(--font-display)', letterSpacing: '-0.02em', color: 'var(--color-text-primary)' }}>Talora</span>
          </div>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: '0.5rem' }}>Forgot Password</h1>
          <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem' }}>Enter your Student Number or Email</p>
        </div>

        {error && (
          <div style={{ marginBottom: '1.5rem', padding: '0.875rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem', border: '1px solid rgba(239, 68, 68, 0.2)' }}>
            {error}
          </div>
        )}

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div>
              <label className="label" style={{ display: 'block', fontSize: '0.875rem', fontWeight: 500, marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>Student Number or Email</label>
              <input 
                type="text" 
                className="input" 
                placeholder="e.g. 2100700123"
                value={identifier} 
                onChange={e => setIdentifier(e.target.value)} 
                required 
              />
            </div>

            <button 
              type="submit" 
              className="btn-primary" 
              style={{ width: '100%', marginTop: '0.5rem', padding: '0.75rem', fontSize: '0.9375rem' }}
              disabled={loading}
            >
              {loading ? 'Sending Request...' : 'Request Password Reset'}
            </button>

            <div style={{ textAlign: 'center', marginTop: '1rem' }}>
              <Link href="/login" style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem', textDecoration: 'none' }}>
                Back to Login
              </Link>
            </div>
          </form>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';

export default function LoginPage() {
  const [email, setEmail]               = useState('');
  const [password, setPassword]         = useState('');
  const [error, setError]               = useState('');
  const [loading, setLoading]           = useState(false);
  const [rememberMe, setRememberMe]     = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const res  = await fetch('/api/v1/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, rememberMe }),
      });
      const data = await res.json();
      if (!res.ok) {
        if (data.requiresVerification) {
          window.location.href = `/verify?email=${encodeURIComponent(email)}`;
          return;
        }
        throw new Error(data.message || 'Login failed');
      }
      window.location.href = '/';
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  /* ΓöÇΓöÇΓöÇ shared input style ΓöÇΓöÇΓöÇ */
  const lineInput: React.CSSProperties = {
    width: '100%',
    background: 'transparent',
    border: 'none',
    borderBottom: '1.5px solid var(--border-strong)',
    color: 'var(--color-text-primary)',
    padding: '0.5rem 0',
    fontSize: '1rem',
    outline: 'none',
    fontFamily: 'var(--font-sans)',
    transition: 'border-color 0.2s',
  };

  return (
    <div style={{ display: 'flex', minHeight: '100dvh', fontFamily: 'var(--font-sans)' }}>

      {/* ΓöÇΓöÇ Left ΓÇö Editorial Poster ΓöÇΓöÇ */}
      <div className="auth-poster" style={{
        flex: '0 0 45%',
        background: '#080809',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        overflow: 'hidden',
      }}>
        {/* Huge ambient glow */}
        <div style={{
          position: 'absolute', inset: 0,
          background: 'radial-gradient(ellipse at 30% 60%, rgba(255,75,51,0.18) 0%, transparent 65%)',
          pointerEvents: 'none',
        }} />

        {/* Horizontal rule lines ΓÇö like ledger paper */}
        {Array.from({ length: 18 }).map((_, i) => (
          <div key={i} style={{
            position: 'absolute',
            left: 0, right: 0,
            top: `${(i + 1) * 5.5}%`,
            height: '1px',
            background: 'rgba(244, 242, 237, 0.04)',
          }} />
        ))}

        {/* The wordmark ΓÇö fills the space */}
        <div style={{ position: 'relative', zIndex: 2, textAlign: 'center', padding: '2rem' }}>
          <div style={{
            fontFamily: 'var(--font-display)',
            fontStyle: 'italic',
            fontWeight: 800,
            fontSize: 'clamp(5rem, 14vw, 10rem)',
            color: 'var(--color-text-primary)',
            lineHeight: 0.9,
            letterSpacing: '-0.04em',
          }}>
            Talora
          </div>

          <div style={{
            marginTop: '1.5rem',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '0.75rem',
          }}>
            <div style={{ height: '1px', width: '40px', background: 'var(--border-strong)' }} />
            <span style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.6rem',
              letterSpacing: '0.2em',
              textTransform: 'uppercase',
              color: 'var(--color-text-muted)',
            }}>
              Class & Group Coordination
            </span>
            <div style={{ height: '1px', width: '40px', background: 'var(--border-strong)' }} />
          </div>

          {/* Orange stamp dot */}
          <div style={{
            width: '10px',
            height: '10px',
            borderRadius: '50%',
            background: 'var(--color-primary)',
            margin: '2rem auto 0',
            boxShadow: '0 0 24px rgba(255,75,51,0.6)',
          }} />
        </div>
      </div>

      {/* ΓöÇΓöÇ Right ΓÇö Sign-in form ΓöÇΓöÇ */}
      <div style={{
        flex: 1,
        background: 'var(--color-bg-base)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '3rem 2rem',
      }}>
        <div style={{ width: '100%', maxWidth: '360px' }}>

          {/* Header */}
          <div style={{ marginBottom: '3rem' }}>
            <div style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.6875rem',
              letterSpacing: '0.12em',
              textTransform: 'uppercase',
              color: 'var(--color-primary)',
              marginBottom: '0.75rem',
            }}>
              Sign in
            </div>
            <h1 style={{
              fontFamily: 'var(--font-display)',
              fontStyle: 'italic',
              fontSize: '1.875rem',
              fontWeight: 700,
              letterSpacing: '-0.03em',
              color: 'var(--color-text-primary)',
              lineHeight: 1.1,
              margin: 0,
            }}>
              Welcome back.
            </h1>
          </div>

          {/* Error */}
          {error && (
            <div style={{
              padding: '0.75rem 1rem',
              marginBottom: '1.5rem',
              background: 'var(--color-danger-bg)',
              color: 'var(--color-danger)',
              borderRadius: '6px',
              fontSize: '0.875rem',
              borderLeft: '3px solid var(--color-danger)',
            }}>
              {error}
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleLogin} style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>

            <div>
              <label style={{ fontFamily: 'var(--font-mono)', fontSize: '0.625rem', letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--color-text-muted)', display: 'block', marginBottom: '0.5rem' }}>
                Email address
              </label>
              <input
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder="name@example.com"
                style={lineInput}
                onFocus={e  => (e.target.style.borderBottomColor = 'var(--color-primary)')}
                onBlur={e   => (e.target.style.borderBottomColor = 'var(--border-strong)')}
                required
              />
            </div>

            <div>
              <label style={{ fontFamily: 'var(--font-mono)', fontSize: '0.625rem', letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--color-text-muted)', display: 'block', marginBottom: '0.5rem' }}>
                Password
              </label>
              <div style={{ position: 'relative' }}>
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                  style={{ ...lineInput, paddingRight: '2rem' }}
                  onFocus={e  => (e.target.style.borderBottomColor = 'var(--color-primary)')}
                  onBlur={e   => (e.target.style.borderBottomColor = 'var(--border-strong)')}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ position: 'absolute', right: 0, top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)', padding: 0, cursor: 'pointer', background: 'none', border: 'none', display: 'flex', alignItems: 'center' }}
                >
                  {showPassword ? (
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24M1 1l22 22"/></svg>
                  ) : (
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                  )}
                </button>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', fontSize: '0.8125rem', color: 'var(--color-text-secondary)' }}>
                <input
                  type="checkbox"
                  style={{ accentColor: 'var(--color-primary)', width: '14px', height: '14px' }}
                  checked={rememberMe}
                  onChange={e => setRememberMe(e.target.checked)}
                />
                Remember me
              </label>
              <Link href="/forgot-password" style={{ fontSize: '0.8125rem', color: 'var(--color-primary)', fontWeight: 500 }}>
                Forgot password?
              </Link>
            </div>

            <button
              type="submit"
              className="btn-primary"
              disabled={loading}
              style={{ width: '100%', padding: '0.875rem', fontSize: '0.9375rem', marginTop: '0.5rem', letterSpacing: '-0.01em' }}
            >
              {loading ? (
                <span style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', justifyContent: 'center' }}>
                  <span style={{ width: '14px', height: '14px', borderRadius: '50%', border: '2px solid rgba(255,255,255,0.3)', borderTopColor: 'white', animation: 'spin 0.7s linear infinite', display: 'inline-block' }} />
                  Signing inΓÇª
                </span>
              ) : 'Sign In ΓåÆ'}
            </button>
          </form>

          {/* Footer */}
          <div style={{ marginTop: '2.5rem', paddingTop: '1.5rem', borderTop: '1px solid var(--border-rule)', fontSize: '0.8125rem', color: 'var(--color-text-muted)', textAlign: 'center', lineHeight: 1.7 }}>
            No account?{' '}
            <Link href="/register" style={{ color: 'var(--color-text-primary)', fontWeight: 500 }}>
              Sign up
            </Link>
            {' '}or contact your administrator.
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import PhoneInput from 'react-phone-number-input';
import 'react-phone-number-input/style.css';
import { auth } from '@/lib/firebase';
import { RecaptchaVerifier, signInWithPhoneNumber, ConfirmationResult } from 'firebase/auth';

export default function RegisterPage() {
  const router = useRouter();
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    studentNumber: '',
    registrationNumber: '',
    password: '',
    phoneNumber: ''
  });
  
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  
  const [otpSent, setOtpSent] = useState(false);
  const [otpCode, setOtpCode] = useState('');
  const [confirmationResult, setConfirmationResult] = useState<ConfirmationResult | null>(null);

  useEffect(() => {
    // If a verifier from a previous mount is left on the window, clear it out.
    // This prevents the "reCAPTCHA client element has been removed" error
    // when navigating away and coming back.
    if ((window as any).recaptchaVerifier) {
      try {
        (window as any).recaptchaVerifier.clear();
      } catch (e) {}
      (window as any).recaptchaVerifier = undefined;
    }

    (window as any).recaptchaVerifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
      size: 'invisible'
    });

    // Cleanup on unmount
    return () => {
      if ((window as any).recaptchaVerifier) {
        try {
          (window as any).recaptchaVerifier.clear();
        } catch (e) {}
        (window as any).recaptchaVerifier = undefined;
      }
    };
  }, []);

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.phoneNumber) {
      setError('Please provide a valid phone number.');
      return;
    }
    if (!acceptedTerms) {
      setError('You must accept the Terms and Conditions to continue.');
      return;
    }
    
    setLoading(true);
    setError('');

    try {
      const appVerifier = (window as any).recaptchaVerifier;
      const result = await signInWithPhoneNumber(auth, formData.phoneNumber, appVerifier);
      setConfirmationResult(result);
      setOtpSent(true);
    } catch (err: any) {
      setError(err.message || 'Failed to send verification code. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!otpCode || !confirmationResult) return;

    setLoading(true);
    setError('');

    try {
      // 1. Verify Phone Token
      const result = await confirmationResult.confirm(otpCode);
      const firebaseIdToken = await result.user.getIdToken();

      // 2. Register User
      const payload = {
        ...formData,
        acceptedTerms,
        firebaseIdToken
      };

      const res = await fetch('/api/v1/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.error || data.message || 'Registration failed');
      }

      // Navigate to login
      router.push('/login?registered=true');
    } catch (err: any) {
      setError(err.message || 'Invalid verification code.');
    } finally {
      setLoading(false);
    }
  };

  const lineInput: React.CSSProperties = {
    width: '100%',
    background: 'transparent',
    border: 'none',
    borderBottom: '1.5px solid var(--border-strong)',
    color: 'var(--color-text-primary)',
    padding: '0.5rem 0',
    fontSize: '0.9375rem',
    outline: 'none',
    fontFamily: 'var(--font-sans)',
    transition: 'border-color 0.2s',
  };

  const mono6: React.CSSProperties = {
    fontFamily: 'var(--font-mono)',
    fontSize: '0.625rem',
    letterSpacing: '0.12em',
    textTransform: 'uppercase' as const,
    color: 'var(--color-text-muted)',
    display: 'block',
    marginBottom: '0.5rem',
  };

  return (
    <div style={{ display: 'flex', minHeight: '100dvh' }}>
      <div id="recaptcha-container" style={{ position: 'fixed', bottom: 0, right: 0, zIndex: 9999 }} />

      {/* ΓöÇΓöÇ Left ΓÇö Editorial Poster ΓöÇΓöÇ */}
      <div className="auth-poster" style={{
        flex: '0 0 40%',
        background: '#080809',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        overflow: 'hidden',
      }}>
        <div style={{
          position: 'absolute', inset: 0,
          background: 'radial-gradient(ellipse at 60% 40%, rgba(255,75,51,0.15) 0%, transparent 65%)',
          pointerEvents: 'none',
        }} />
        {Array.from({ length: 18 }).map((_, i) => (
          <div key={i} style={{ position: 'absolute', left: 0, right: 0, top: `${(i + 1) * 5.5}%`, height: '1px', background: 'rgba(244,242,237,0.04)' }} />
        ))}
        <div style={{ position: 'relative', zIndex: 2, textAlign: 'center', padding: '2rem' }}>
          <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontWeight: 800, fontSize: 'clamp(4rem, 12vw, 8rem)', color: 'var(--color-text-primary)', lineHeight: 0.9, letterSpacing: '-0.04em' }}>
            Talora
          </div>
          <div style={{ marginTop: '1.5rem', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.75rem' }}>
            <div style={{ height: '1px', width: '32px', background: 'var(--border-strong)' }} />
            <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.55rem', letterSpacing: '0.2em', textTransform: 'uppercase', color: 'var(--color-text-muted)' }}>
              Student Registration
            </span>
            <div style={{ height: '1px', width: '32px', background: 'var(--border-strong)' }} />
          </div>
          <div style={{ width: '10px', height: '10px', borderRadius: '50%', background: 'var(--color-primary)', margin: '2rem auto 0', boxShadow: '0 0 20px rgba(255,75,51,0.5)' }} />
        </div>
      </div>

      {/* ΓöÇΓöÇ Right ΓÇö Registration form ΓöÇΓöÇ */}
      <div style={{
        flex: 1,
        background: 'var(--color-bg-base)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '2.5rem 2rem',
        overflowY: 'auto',
      }}>
        <div style={{ width: '100%', maxWidth: '380px' }}>

          <div style={{ marginBottom: '2.5rem' }}>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--color-primary)', marginBottom: '0.75rem' }}>
              {otpSent ? 'Verify your number' : 'Create account'}
            </div>
            <h1 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.625rem', fontWeight: 700, letterSpacing: '-0.03em', color: 'var(--color-text-primary)', lineHeight: 1.1, margin: 0 }}>
              {otpSent ? 'Check your phone.' : 'Join the register.'}
            </h1>
          </div>

          {error && (
            <div style={{ padding: '0.75rem 1rem', marginBottom: '1.5rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: '6px', fontSize: '0.875rem', borderLeft: '3px solid var(--color-danger)' }}>
              {error}
            </div>
          )}

          {!otpSent ? (
            <form onSubmit={handleSendOtp} style={{ display: 'flex', flexDirection: 'column', gap: '1.75rem' }}>
              <div>
                <label style={mono6}>Full name</label>
                <input type="text" style={lineInput} placeholder="e.g. Nakato Amina" value={formData.fullName} onChange={e => setFormData({...formData, fullName: e.target.value})} onFocus={e => (e.target.style.borderBottomColor = 'var(--color-primary)')} onBlur={e => (e.target.style.borderBottomColor = 'var(--border-strong)')} required />
              </div>
              <div>
                <label style={mono6}>Email address</label>
                <input type="email" style={lineInput} placeholder="name@example.com" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} onFocus={e => (e.target.style.borderBottomColor = 'var(--color-primary)')} onBlur={e => (e.target.style.borderBottomColor = 'var(--border-strong)')} required />
              </div>
              <div style={{ display: 'flex', gap: '1.25rem' }}>
                <div style={{ flex: 1 }}>
                  <label style={mono6}>Student number</label>
                  <input type="text" style={lineInput} placeholder="21007ΓÇª" value={formData.studentNumber} onChange={e => setFormData({...formData, studentNumber: e.target.value})} onFocus={e => (e.target.style.borderBottomColor = 'var(--color-primary)')} onBlur={e => (e.target.style.borderBottomColor = 'var(--border-strong)')} required />
                </div>
                <div style={{ flex: 1 }}>
                  <label style={mono6}>Reg. number</label>
                  <input type="text" style={lineInput} placeholder="21/U/ΓÇª" value={formData.registrationNumber} onChange={e => setFormData({...formData, registrationNumber: e.target.value})} onFocus={e => (e.target.style.borderBottomColor = 'var(--color-primary)')} onBlur={e => (e.target.style.borderBottomColor = 'var(--border-strong)')} required />
                </div>
              </div>
              <div>
                <label style={mono6}>Phone number</label>
                <PhoneInput
                  international
                  defaultCountry="UG"
                  className="input phone-input"
                  value={formData.phoneNumber}
                  onChange={(value) => setFormData({...formData, phoneNumber: value || ''})}
                  style={{ '--PhoneInputCountryFlag-height': '14px', '--PhoneInput-color--focus': 'var(--color-primary)' } as any}
                />
              </div>
              <div>
                <label style={mono6}>Password</label>
                <div style={{ position: 'relative' }}>
                  <input type={showPassword ? 'text' : 'password'} style={{ ...lineInput, paddingRight: '2rem' }} placeholder="Create a strong password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} onFocus={e => (e.target.style.borderBottomColor = 'var(--color-primary)')} onBlur={e => (e.target.style.borderBottomColor = 'var(--border-strong)')} required minLength={8} />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} style={{ position: 'absolute', right: 0, top: '50%', transform: 'translateY(-50%)', color: 'var(--color-text-muted)', padding: 0, cursor: 'pointer', background: 'none', border: 'none', display: 'flex', alignItems: 'center' }}>
                    {showPassword ? <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24M1 1l22 22"/></svg> : <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>}
                  </button>
