                  onBlur={e  => (e.target.style.borderBottomColor = 'var(--border-strong)')}
                />
              </div>
              <button type="submit" className="btn-primary" style={{ width: '100%', padding: '0.875rem', fontSize: '0.9375rem' }} disabled={loading}>
                {loading ? 'VerifyingΓÇª' : 'Verify & create account ΓåÆ'}
              </button>
              <button type="button" onClick={() => setOtpSent(false)} className="btn-secondary" style={{ width: '100%', padding: '0.75rem' }} disabled={loading}>
                ΓåÉ Back
              </button>
            </form>
          )}

          <div style={{ marginTop: '2rem', paddingTop: '1.5rem', borderTop: '1px solid var(--border-rule)', fontSize: '0.8125rem', color: 'var(--color-text-muted)', textAlign: 'center', lineHeight: 1.7 }}>
            Already have an account?{' '}
            <Link href="/login" style={{ color: 'var(--color-text-primary)', fontWeight: 500 }}>Sign in</Link>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';

function ResetPasswordForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const emailQuery = searchParams.get('email') || '';

  const [formData, setFormData] = useState({
    email: emailQuery,
    code: '',
    newPassword: '',
    confirmPassword: ''
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  useEffect(() => {
    if (emailQuery) {
      setFormData(prev => ({ ...prev, email: emailQuery }));
    }
  }, [emailQuery]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (formData.newPassword !== formData.confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }

    try {
      const res = await fetch('/api/v1/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          email: formData.email,
          token: formData.code,
          newPassword: formData.newPassword
        })
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Failed to reset password');
      }

      setSuccess(true);
      setTimeout(() => {
        router.push('/login');
      }, 3000);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', alignItems: 'center', justifyContent: 'center', background: 'var(--color-bg-base)', padding: '1rem' }}>
      <div className="glass-panel" style={{ width: '100%', maxWidth: '440px', padding: '2.5rem' }}>

        <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' }}>
            <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: 'var(--color-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 800, fontSize: '1.25rem' }}>T</div>
            <span style={{ fontSize: '1.5rem', fontWeight: 800, fontFamily: 'var(--font-display)', letterSpacing: '-0.02em', color: 'var(--color-text-primary)' }}>Talora</span>
          </div>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: '0.5rem' }}>Reset Password</h1>
          <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem' }}>Enter the 6-digit code sent to your email</p>
        </div>

        {error && (
          <div style={{ marginBottom: '1.5rem', padding: '0.875rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem', border: '1px solid rgba(239, 68, 68, 0.2)' }}>
            {error}
          </div>
        )}

        {success ? (
          <div style={{ textAlign: 'center', padding: '1rem' }}>
            <div style={{ color: 'var(--color-success)', marginBottom: '1rem' }}>
              <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ margin: '0 auto' }}>
                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                <polyline points="22 4 12 14.01 9 11.01"></polyline>
              </svg>
            </div>
            <h3 style={{ fontSize: '1.125rem', marginBottom: '0.5rem' }}>Password Reset Successful</h3>
            <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem' }}>Redirecting you to login...</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div>
              <label className="label">Email Address</label>
              <input 
                type="email" 
                className="input" 
                value={formData.email} 
                onChange={e => setFormData({...formData, email: e.target.value})} 
                required 
                readOnly={!!emailQuery}
                style={{ opacity: emailQuery ? 0.7 : 1 }}
              />
            </div>

            <div>
              <label className="label">6-Digit Code</label>
              <input 
                type="text" 
                className="input" 
                placeholder="123456"
                value={formData.code} 
                onChange={e => setFormData({...formData, code: e.target.value})} 
                required 
                maxLength={6}
                style={{ letterSpacing: '2px', textAlign: 'center', fontSize: '1.125rem', fontWeight: 600 }}
              />
            </div>

            <div>
              <label className="label">New Password</label>
              <div style={{ position: 'relative' }}>
                <input 
                  type={showPassword ? "text" : "password"}
                  className="input" 
                  value={formData.newPassword} 
                  onChange={e => setFormData({...formData, newPassword: e.target.value})} 
                  required 
                  minLength={8}
                  style={{ width: '100%', paddingRight: '2.5rem' }}
                />
                <button 
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ position: 'absolute', right: '0.75rem', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: 'var(--color-text-muted)', cursor: 'pointer', padding: 0 }}
                >
                  {showPassword ? (
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24M1 1l22 22"/></svg>
                  ) : (
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                  )}
                </button>
              </div>
            </div>

            <div>
              <label className="label">Confirm New Password</label>
              <div style={{ position: 'relative' }}>
                <input 
                  type={showPassword ? "text" : "password"}
                  className="input" 
                  value={formData.confirmPassword} 
                  onChange={e => setFormData({...formData, confirmPassword: e.target.value})} 
                  required 
                  minLength={8}
                  style={{ width: '100%', paddingRight: '2.5rem' }}
                />
              </div>
            </div>

            <button 
              type="submit" 
              className="btn-primary" 
              style={{ width: '100%', marginTop: '0.5rem', padding: '0.75rem', fontSize: '0.9375rem' }}
              disabled={loading}
            >
              {loading ? 'Resetting...' : 'Reset Password'}
            </button>

            <div style={{ textAlign: 'center', marginTop: '1rem' }}>
              <Link href="/login" style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem', textDecoration: 'none' }}>
                Back to Login
              </Link>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

export default function ResetPasswordPage() {
  return (
    <Suspense fallback={
      <div style={{ display: 'flex', height: '100vh', alignItems: 'center', justifyContent: 'center' }}>
        Loading...
      </div>
    }>
      <ResetPasswordForm />
    </Suspense>
  );
}

'use client';

import React, { useState, useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

function VerifyForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const email = searchParams.get('email') || '';

  const [otp, setOtp] = useState('');
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [resending, setResending] = useState(false);

  useEffect(() => {
    if (!email) {
      router.push('/login');
    }
  }, [email, router]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await fetch('/api/v1/auth/verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, otp })
      });
      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || data.message || 'Verification failed');
      }

      // Successful verification returns a JWT token in an httpOnly cookie
      // and redirect to dashboard
      window.location.href = '/';
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleResend = async () => {
    if (!email) return;
    setResending(true);
    setError('');
    setSuccessMsg('');

    try {
      const res = await fetch('/api/v1/auth/resend-verification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email })
      });
      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Failed to resend code');
      }
      setSuccessMsg(data.message || 'A new verification code has been sent.');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setResending(false);
    }
  };

  return (
    <>
      <div style={{ textAlign: 'center', marginBottom: '2.5rem' }}>
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' }}>
          <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: 'var(--color-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: 800, fontSize: '1.25rem' }}>T</div>
          <span style={{ fontSize: '1.5rem', fontWeight: 800, fontFamily: 'var(--font-display)', letterSpacing: '-0.02em', color: 'var(--color-text-primary)' }}>Talora</span>
        </div>
        <h1 style={{ fontSize: '1.5rem', fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: '0.5rem' }}>Verify Email</h1>
        <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem' }}>
          We sent a 6-digit code to <strong>{email}</strong>
        </p>
      </div>

      {error && (
        <div style={{ marginBottom: '1.5rem', padding: '0.875rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem', border: '1px solid rgba(239, 68, 68, 0.2)' }}>
          {error}
        </div>
      )}

      {successMsg && (
        <div style={{ marginBottom: '1.5rem', padding: '0.875rem', background: 'rgba(16, 185, 129, 0.1)', color: 'var(--color-success)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem', border: '1px solid rgba(16, 185, 129, 0.2)' }}>
          {successMsg}
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
        <div>
          <label className="label">Verification Code</label>
          <input 
            type="text" 
            className="input" 
            placeholder="e.g. 123456"
            value={otp} 
            onChange={e => setOtp(e.target.value)} 
            required 
            maxLength={6}
            style={{ fontSize: '1.25rem', letterSpacing: '2px', textAlign: 'center' }}
          />
        </div>

        <button 
          type="submit" 
          className="btn-primary" 
          style={{ width: '100%', marginTop: '0.5rem', padding: '0.75rem', fontSize: '0.9375rem' }}
          disabled={loading || otp.length < 6}
        >
          {loading ? 'Verifying...' : 'Verify and Continue'}
        </button>

        <div style={{ textAlign: 'center', marginTop: '1rem' }}>
          <p style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)' }}>
            Didn't receive the code?{' '}
            <button 
              type="button" 
              onClick={handleResend}
              disabled={resending}
              style={{ background: 'none', border: 'none', color: 'var(--color-primary)', fontWeight: 500, cursor: resending ? 'not-allowed' : 'pointer', padding: 0 }}
            >
              {resending ? 'Sending...' : 'Resend Code'}
            </button>
          </p>
        </div>
      </form>
    </>
  );
}

export default function VerifyPage() {
  return (
    <div style={{ display: 'flex', minHeight: '100vh', alignItems: 'center', justifyContent: 'center', background: 'var(--color-bg-base)', padding: '1rem' }}>
      <div className="glass-panel" style={{ width: '100%', maxWidth: '440px', padding: '2.5rem' }}>
        <Suspense fallback={<div style={{ textAlign: 'center', padding: '2rem' }}>Loading...</div>}>
          <VerifyForm />
        </Suspense>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import PhoneInput from 'react-phone-number-input';
import 'react-phone-number-input/style.css';
import { auth } from '@/lib/firebase';
import { RecaptchaVerifier, signInWithPhoneNumber, ConfirmationResult } from 'firebase/auth';

export default function PhoneOnboardingModal({ userId }: { userId: string }) {
  const router = useRouter();
  const [phoneNumber, setPhoneNumber] = useState('');
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [otpSent, setOtpSent] = useState(false);
  const [otpCode, setOtpCode] = useState('');
  const [confirmationResult, setConfirmationResult] = useState<ConfirmationResult | null>(null);

  useEffect(() => {
    if (!(window as any).recaptchaVerifier) {
      (window as any).recaptchaVerifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
        size: 'invisible'
      });
    }
  }, []);

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!phoneNumber) {
      setError('Please provide a valid phone number.');
      return;
    }
    if (!acceptedTerms) {
      setError('You must accept the Terms and Conditions to continue.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const appVerifier = (window as any).recaptchaVerifier;
      const result = await signInWithPhoneNumber(auth, phoneNumber, appVerifier);
      setConfirmationResult(result);
      setOtpSent(true);
    } catch (err: any) {
      setError(err.message || 'Failed to send OTP. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!otpCode || !confirmationResult) return;

    setLoading(true);
    setError('');

    try {
      const result = await confirmationResult.confirm(otpCode);
      const firebaseIdToken = await result.user.getIdToken();

      const res = await fetch(`/api/v1/users/${userId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ phoneNumber, acceptedTerms, firebaseIdToken }) 
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.message || data.error || 'Failed to update profile');
      }

      window.location.reload();
    } catch (err: any) {
      setError(err.message || 'Invalid verification code.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="modal-content" style={{ background: 'var(--color-bg-surface)', padding: '2rem', borderRadius: '16px', maxWidth: '450px', width: '100%', boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)' }}>
      <div id="recaptcha-container"></div>
      <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <div style={{ width: '48px', height: '48px', background: 'var(--color-primary-transparent)', color: 'var(--color-primary)', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem auto' }}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
          </div>
          <h2 style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--color-text-primary)' }}>Action Required</h2>
          <p style={{ color: 'var(--color-text-secondary)', marginTop: '0.5rem', fontSize: '0.9375rem' }}>{otpSent ? 'Enter the verification code sent to your phone.' : 'Please complete your profile to continue using the dashboard.'}</p>
        </div>

        {error && (
          <div style={{ padding: '0.75rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: '8px', fontSize: '0.875rem', marginBottom: '1.5rem', textAlign: 'center' }}>
            {error}
          </div>
        )}

        {!otpSent ? (
          <form onSubmit={handleSendOtp} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div>
              <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)', fontWeight: 500 }}>Phone Number</label>
              <PhoneInput
                international
                defaultCountry="UG"
                className="input phone-input"
                value={phoneNumber}
                onChange={(value) => setPhoneNumber(value || '')}
                style={{ 
                  '--PhoneInputCountryFlag-height': '16px',
                  '--PhoneInput-color--focus': 'var(--color-primary)'
                } as any}
              />
            </div>

            <label style={{ display: 'flex', alignItems: 'flex-start', gap: '0.75rem', cursor: 'pointer', padding: '1rem', background: 'rgba(255,255,255,0.03)', borderRadius: '8px', border: '1px solid var(--border-subtle)' }}>
              <input 
                type="checkbox" 
                checked={acceptedTerms}
                onChange={(e) => setAcceptedTerms(e.target.checked)}
                style={{ marginTop: '0.25rem', width: '1.1rem', height: '1.1rem', accentColor: 'var(--color-primary)' }}
              />
              <span style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', lineHeight: 1.5 }}>
                I agree to the <a href="/terms" target="_blank" rel="noopener noreferrer" style={{ color: 'var(--color-primary)', textDecoration: 'underline' }}>Terms and Conditions</a> regarding data usage for academic coordination on this platform.
              </span>
            </label>

            <button type="submit" className="btn-primary" style={{ width: '100%', marginTop: '0.5rem', padding: '0.75rem' }} disabled={loading}>
              {loading ? 'Sending OTP...' : 'Send Verification Code'}
            </button>
          </form>
        ) : (
          <form onSubmit={handleVerifyOtp} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div>
              <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)', fontWeight: 500 }}>Verification Code</label>
              <input
                type="text"
                className="input"
                value={otpCode}
                onChange={(e) => setOtpCode(e.target.value)}
                placeholder="123456"
                required
                style={{ width: '100%' }}
              />
            </div>
            <button type="submit" className="btn-primary" style={{ width: '100%', marginTop: '0.5rem', padding: '0.75rem' }} disabled={loading}>
              {loading ? 'Verifying...' : 'Verify and Save'}
            </button>
            <button type="button" onClick={() => setOtpSent(false)} className="btn-secondary" style={{ width: '100%' }} disabled={loading}>
              Back
            </button>
          </form>
        )}
      </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { toast } from 'sonner';

type RoleType = 'PLATFORM_ADMIN' | 'CLASS_REPRESENTATIVE' | 'GROUP_LEADER' | 'STUDENT';

interface UserRole {
  role: RoleType;
  classId?: string | null;
  class?: { id: string; name: string; year: number } | null;
}

interface User {
  id: string;
  fullName: string;
  email: string;
  studentNumber: string | null;
  registrationNumber: string | null;
  isActive: boolean;
  createdAt: string;
  roles: UserRole[];
}

interface ClassCohort {
  id: string;
  name: string;
  year: number;
}

export default function AdminUsersPage() {
  const [users, setUsers] = useState<User[]>([]);
  const [classes, setClasses] = useState<ClassCohort[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [searchQuery, setSearchQuery] = useState('');
  const [roleFilter, setRoleFilter] = useState('ALL');

  // Edit Modal State
  const [editingUser, setEditingUser] = useState<User | null>(null);
  // editRoles: array of { role, classId }
  const [editRoles, setEditRoles] = useState<{ role: RoleType; classId?: string }[]>([]);
  const [savingRoles, setSavingRoles] = useState(false);

  const fetchUsers = async () => {
    setLoading(true);
    setError('');
    try {
      const url = new URL('/api/v1/users', window.location.origin);
      if (searchQuery) url.searchParams.append('q', searchQuery);
      if (roleFilter !== 'ALL') url.searchParams.append('role', roleFilter);
      const res = await fetch(url.toString());
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to fetch users');
      setUsers(data.data);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchClasses = async () => {
    try {
      // Use the offerings endpoint to get classes ΓÇö or fetch directly
      const res = await fetch('/api/v1/offerings');
      const data = await res.json();
      // Extract unique classes from offerings
      const seen = new Set<string>();
      const uniqueClasses: ClassCohort[] = [];
      (data.data || []).forEach((o: any) => {
        if (o.class && !seen.has(o.class.id)) {
          seen.add(o.class.id);
          uniqueClasses.push(o.class);
        }
      });
      setClasses(uniqueClasses);
    } catch {
      // Non-critical ΓÇö classes might not load
    }
  };

  useEffect(() => {
    fetchClasses();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => { fetchUsers(); }, 300);
    return () => clearTimeout(timer);
  }, [searchQuery, roleFilter]);

  const openEditModal = (user: User) => {
    setEditingUser(user);
    setEditRoles(user.roles.map(r => ({ role: r.role, classId: r.classId || undefined })));
  };

  const toggleRole = (role: RoleType, checked: boolean) => {
    if (checked) {
      setEditRoles(prev => [...prev, { role, classId: undefined }]);
    } else {
      setEditRoles(prev => prev.filter(r => r.role !== role));
    }
  };

  const setClassForRole = (role: RoleType, classId: string) => {
    setEditRoles(prev => prev.map(r => r.role === role ? { ...r, classId } : r));
  };

  const handleRoleSave = async () => {
    if (!editingUser) return;

    // Validate CLASS_REPRESENTATIVE has a classId
    const repEntry = editRoles.find(r => r.role === 'CLASS_REPRESENTATIVE');
    if (repEntry && !repEntry.classId) {
      toast.error('Please select a class for the Class Representative role.');
      return;
    }

    setSavingRoles(true);
    try {
      const res = await fetch(`/api/v1/users/${editingUser.id}/roles`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ roles: editRoles })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to save roles');

      setUsers(users.map(u => u.id === editingUser.id ? { ...u, roles: editRoles } : u));
      setEditingUser(null);
      toast.success('Roles updated successfully.');
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSavingRoles(false);
    }
  };

  const handleToggleActive = async (user: User) => {
    if (!confirm(`Are you sure you want to ${user.isActive ? 'suspend' : 'activate'} this user?`)) return;
    try {
      const res = await fetch(`/api/v1/users/${user.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: !user.isActive })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to update status');
      setUsers(users.map(u => u.id === user.id ? { ...u, isActive: !user.isActive } : u));
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const handleDeleteAccount = async (user: User) => {
    if (!confirm(`Are you absolutely sure you want to permanently DELETE ${user.fullName}'s account? This action cannot be undone.`)) return;
    try {
      const res = await fetch(`/api/v1/users/${user.id}`, { method: 'DELETE' });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to delete account');
      setUsers(users.filter(u => u.id !== user.id));
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const roleOptions: RoleType[] = ['PLATFORM_ADMIN', 'CLASS_REPRESENTATIVE', 'GROUP_LEADER', 'STUDENT'];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', position: 'relative' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <h1 style={{ fontSize: '1.875rem', marginBottom: '0.25rem', color: 'var(--color-text-primary)' }}>User Directory &amp; Roles</h1>
          <p style={{ color: 'var(--color-text-secondary)', margin: 0, fontSize: '0.875rem' }}>
            Manage platform users, their global role assignments, and account access.
          </p>
        </div>
      </header>

      <div className="glass-panel" style={{ padding: '1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', gap: '1rem', alignItems: 'center', flex: 1, maxWidth: '600px' }}>
          <input
            type="text"
            placeholder="Search by name, email or ID..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ flex: 1, padding: '0.625rem 1rem', borderRadius: '8px', background: 'var(--color-bg-base)', border: '1px solid var(--border-subtle)', color: 'var(--color-text-primary)', outline: 'none', fontSize: '0.875rem' }}
          />
          <select
            value={roleFilter}
            onChange={(e) => setRoleFilter(e.target.value)}
            style={{ padding: '0.625rem 1rem', borderRadius: '8px', background: 'var(--color-bg-base)', border: '1px solid var(--border-subtle)', color: 'var(--color-text-primary)', outline: 'none', fontSize: '0.875rem' }}
          >
            <option value="ALL">All Roles</option>
            <option value="PLATFORM_ADMIN">Platform Admin</option>
            <option value="CLASS_REPRESENTATIVE">Class Rep</option>
            <option value="GROUP_LEADER">Group Leader</option>
            <option value="STUDENT">Student</option>
          </select>
        </div>
      </div>

      {error && (
        <div style={{ padding: '1rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: '8px' }}>
          {error}
        </div>
      )}

      <div className="glass-panel" style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.875rem' }}>
          <thead>
            <tr style={{ background: 'var(--color-bg-base)', borderBottom: '1px solid var(--border-subtle)' }}>
              <th style={{ padding: '1rem 1.5rem', fontWeight: 600, color: 'var(--color-text-secondary)' }}>Name</th>
              <th style={{ padding: '1rem 1.5rem', fontWeight: 600, color: 'var(--color-text-secondary)' }}>Email</th>
              <th style={{ padding: '1rem 1.5rem', fontWeight: 600, color: 'var(--color-text-secondary)' }}>Roles</th>
              <th style={{ padding: '1rem 1.5rem', fontWeight: 600, color: 'var(--color-text-secondary)' }}>Status</th>
              <th style={{ padding: '1rem 1.5rem', fontWeight: 600, color: 'var(--color-text-secondary)', textAlign: 'right' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={5} style={{ textAlign: 'center', padding: '2rem' }}>Loading users...</td></tr>
            ) : users.length === 0 ? (
              <tr><td colSpan={5} style={{ textAlign: 'center', padding: '2rem' }}>No users found.</td></tr>
            ) : (
              users.map((user) => (
                <tr key={user.id} style={{ borderBottom: '1px solid var(--border-subtle)', opacity: user.isActive ? 1 : 0.6 }}>
                  <td style={{ padding: '1rem 1.5rem', color: 'var(--color-text-primary)' }}>
                    <div style={{ fontWeight: 500 }}>{user.fullName}</div>
                    <div style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)' }}>{user.studentNumber || 'No ID'}</div>
                  </td>
                  <td style={{ padding: '1rem 1.5rem', color: 'var(--color-text-secondary)' }}>{user.email}</td>
                  <td style={{ padding: '1rem 1.5rem' }}>
                    <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                      {user.roles.map(r => (
                        <span key={r.role} className="badge" style={{
                          background: r.role === 'PLATFORM_ADMIN' ? 'var(--color-danger-bg)' : 'var(--color-primary-transparent)',
                          color: r.role === 'PLATFORM_ADMIN' ? 'var(--color-danger)' : 'var(--color-primary)'
                        }}>
                          {r.role}{r.role === 'CLASS_REPRESENTATIVE' && r.classId ? '' : r.role === 'CLASS_REPRESENTATIVE' ? ' ΓÜá∩╕Å' : ''}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td style={{ padding: '1rem 1.5rem' }}>
                    <span className="badge" style={{
                      background: user.isActive ? 'rgba(16, 185, 129, 0.1)' : 'var(--color-danger-bg)',
                      color: user.isActive ? 'var(--color-success)' : 'var(--color-danger)'
                    }}>
                      {user.isActive ? 'Active' : 'Suspended'}
                    </span>
                  </td>
                  <td style={{ padding: '1rem 1.5rem', textAlign: 'right' }}>
                    <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end' }}>
                      <button onClick={() => handleToggleActive(user)} className="btn-secondary" style={{ padding: '0.25rem 0.75rem', fontSize: '0.75rem' }}>
                        {user.isActive ? 'Suspend' : 'Activate'}
                      </button>
                      <button onClick={() => openEditModal(user)} className="btn-primary" style={{ padding: '0.25rem 0.75rem', fontSize: '0.75rem' }}>
                        Edit Roles
                      </button>
                      <button onClick={() => handleDeleteAccount(user)} className="btn-ghost" style={{ padding: '0.25rem 0.75rem', fontSize: '0.75rem', color: 'var(--color-danger)' }}>
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Edit Roles Modal */}
      {editingUser && (
        <div style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100 }}>
          <div className="glass-panel" style={{ width: '100%', maxWidth: '440px', padding: '2rem' }}>
            <h2 style={{ marginTop: 0, marginBottom: '0.25rem' }}>Edit Roles</h2>
            <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.875rem', marginBottom: '1.5rem' }}>{editingUser.fullName}</p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem', marginBottom: '2rem' }}>
              {roleOptions.map(role => {
                const isChecked = editRoles.some(r => r.role === role);
                const entry = editRoles.find(r => r.role === role);
                return (
                  <div key={role}>
                    <label style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', cursor: 'pointer' }}>
                      <input
                        type="checkbox"
                        checked={isChecked}
                        onChange={(e) => toggleRole(role, e.target.checked)}
                        style={{ width: '18px', height: '18px' }}
                      />
                      <span style={{ fontSize: '0.9375rem', color: 'var(--color-text-primary)' }}>{role.replace(/_/g, ' ')}</span>
                    </label>

                    {/* Show class selector when CLASS_REPRESENTATIVE is checked */}
                    {role === 'CLASS_REPRESENTATIVE' && isChecked && (
                      <div style={{ marginTop: '0.5rem', marginLeft: '1.75rem' }}>
                        <label style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary)', display: 'block', marginBottom: '0.25rem' }}>
                          Assign to class <span style={{ color: 'var(--color-danger)' }}>*</span>
                        </label>
                        <select
                          value={entry?.classId || ''}
                          onChange={(e) => setClassForRole(role, e.target.value)}
                          style={{ width: '100%', padding: '0.5rem 0.75rem', borderRadius: '6px', background: 'var(--color-bg-base)', border: entry?.classId ? '1px solid var(--border-subtle)' : '1px solid var(--color-danger)', color: 'var(--color-text-primary)', outline: 'none', fontSize: '0.875rem' }}
                        >
                          <option value="">ΓÇö Select a class ΓÇö</option>
                          {classes.map(c => (
                            <option key={c.id} value={c.id}>{c.name} ({c.year})</option>
                          ))}
                        </select>
                        {!entry?.classId && (
                          <p style={{ fontSize: '0.75rem', color: 'var(--color-danger)', marginTop: '0.25rem' }}>
                            Required: select the class this rep manages.
                          </p>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'flex-end' }}>
              <button className="btn-secondary" onClick={() => setEditingUser(null)}>Cancel</button>
              <button className="btn-primary" onClick={handleRoleSave} disabled={savingRoles}>
                {savingRoles ? 'Saving...' : 'Save Roles'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import EditAnnouncementModal from './EditAnnouncementModal';
import { toast } from 'sonner';

export default function AnnouncementListClient({ announcements, canEdit }: { announcements: any[], canEdit: boolean }) {
  const router = useRouter();
  const [editingAnnouncement, setEditingAnnouncement] = useState<any | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [tagFilter, setTagFilter] = useState('');

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to delete this announcement?')) return;
    
    try {
      const res = await fetch(`/api/v1/announcements/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete announcement');
      router.refresh();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const filteredAnnouncements = announcements.filter(a => {
    const matchesSearch = a.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          a.content.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesTag = tagFilter ? a.tag === tagFilter : true;
    return matchesSearch && matchesTag;
  });

  const uniqueTags = Array.from(new Set(announcements.map(a => a.tag).filter(Boolean)));

  const getTagBadgeClass = (tag: string) => {
    switch (tag) {
      case 'URGENT': return 'badge-danger';
      case 'ACADEMIC': return 'badge-primary';
      case 'EVENTS': return 'badge-warning';
      default: return 'badge-subtle';
    }
  };

  if (announcements.length === 0) {
    return (
      <div className="ledger-panel" style={{ textAlign: 'center', padding: '3rem', color: 'var(--color-text-muted)' }}>
        No announcements have been posted yet.
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      
      {/* Filters */}
      <div className="ledger-panel" style={{ padding: '1rem', display: 'flex', gap: '1rem', alignItems: 'center' }}>
        <input 
          type="text" 
          className="input" 
          placeholder="Search announcements" 
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ flex: 1 }}
        />
        <select 
          className="input" 
          value={tagFilter}
          onChange={(e) => setTagFilter(e.target.value)}
          style={{ width: '200px' }}
        >
          <option value="">All tags</option>
          {uniqueTags.map((tag: any) => (
            <option key={tag} value={tag}>{tag}</option>
          ))}
        </select>
      </div>

      {filteredAnnouncements.length === 0 ? (
        <div className="ledger-panel" style={{ textAlign: 'center', padding: '3rem', color: 'var(--color-text-muted)' }}>
          No announcements match your search.
        </div>
      ) : (
        filteredAnnouncements.map((announcement) => (
          <div key={announcement.id} className="ledger-panel" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                <h2 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontWeight: 700, fontSize: '1.125rem', color: 'var(--color-text-primary)', margin: 0 }}>{announcement.title}</h2>
                {announcement.tag && (
                  <span className={`badge ${getTagBadgeClass(announcement.tag)}`}>{announcement.tag}</span>
                )}
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                <div className="reg-number">{announcement.date}</div>
                {canEdit && (
                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button onClick={() => setEditingAnnouncement(announcement)} className="btn-ghost" style={{ padding: '0.25rem', color: 'var(--color-text-secondary)' }} title="Edit">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                    </button>
                    <button onClick={() => handleDelete(announcement.id)} className="btn-ghost" style={{ padding: '0.25rem', color: 'var(--color-danger)' }} title="Delete">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>
                    </button>
                  </div>
                )}
              </div>
            </div>
            
            <div style={{ borderTop: '1px solid var(--border-rule)', paddingTop: '1rem', color: 'var(--color-text-secondary)', fontSize: '0.9375rem', whiteSpace: 'pre-wrap', lineHeight: 1.6 }}>
              {announcement.content}
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginTop: '0.25rem' }}>
              <div style={{ width: '22px', height: '22px', borderRadius: '50%', background: 'var(--color-primary-transparent)', color: 'var(--color-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.6875rem', fontFamily: 'var(--font-mono)', fontWeight: 500 }}>
                {announcement.author.split(' ').map((n: string) => n[0]).join('').substring(0, 2).toUpperCase()}
              </div>
              <div style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary)' }}>
                Posted by <span style={{ color: 'var(--color-text-primary)' }}>{announcement.author}</span>
              </div>
            </div>
          </div>
        ))
      )}

      {editingAnnouncement && (
        <EditAnnouncementModal 
          announcement={editingAnnouncement} 
          onClose={() => setEditingAnnouncement(null)} 
        />
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';

export default function CreateAnnouncementModal({ offeringId, onClose }: { offeringId: string, onClose: () => void }) {
  const router = useRouter();
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/v1/announcements`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, content, offeringId })
      });

      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.message || 'Failed to create announcement');
      }

      router.refresh();
      onClose();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content" style={{ maxWidth: '500px' }}>
        <div className="modal-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 className="modal-title">Post announcement</h2>
          <button onClick={onClose} className="btn-ghost" style={{ padding: '0.4rem' }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body" style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
