  const [description, setDescription] = useState(assignment.description || '');

  // Format the date for the datetime-local input (YYYY-MM-DDThh:mm)
  const formatDateForInput = (dateString: string) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    // Convert to local time string that the input expects
    return new Date(date.getTime() - (date.getTimezoneOffset() * 60000))
      .toISOString()
      .slice(0, 16);
  };

  const [dueDate, setDueDate] = useState(formatDateForInput(assignment.dueDate));
  const [type, setType] = useState(assignment.type || 'HOMEWORK');
  const [loading, setLoading] = useState(false);
