          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div className="flex flex-col md:flex-row gap-4">
              <div className="flex-1">
                <label className="label">Type</label>
                <select className="select w-full" value={type} onChange={e => setType(e.target.value)} required>
                  <option value="HOMEWORK">Homework</option>
                  <option value="PROJECT">Project</option>
                  <option value="QUIZ">Quiz</option>
                  <option value="EXAM">Exam</option>
                </select>
              </div>
              <div className="flex-1">
                <label className="label">Due Date & Time</label>
                <input 
                  type="datetime-local" 
                  className="input w-full" 
                  value={dueDate}
                  onChange={e => setDueDate(e.target.value)}
                  required
                />
              </div>
            </div>

            <div>
              <label className="label">Title</label>
              <input 
                type="text" 
                className="input w-full" 
                value={title}
                onChange={e => setTitle(e.target.value)}
                placeholder="e.g. Midterm Report" 
                required
              />
            </div>
            <div>
              <label className="label">Instructions</label>
              <textarea 
                className="input w-full resize-y" 
                value={description}
                onChange={e => setDescription(e.target.value)}
                placeholder="Provide instructions or a link to the specification..." 
                rows={4}
              />
            </div>
            <div className="flex justify-end gap-3 mt-4">
              <Dialog.Close asChild>
                <button type="button" className="btn-secondary">Cancel</button>
              </Dialog.Close>
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </form>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';

interface SubmissionClientProps {
  assignmentId: string;
  initialSubmission: { id: string; fileUrl: string; submittedAt: string } | null;
}

export default function SubmissionClient({ assignmentId, initialSubmission }: SubmissionClientProps) {
  const router = useRouter();
  const [fileUrl, setFileUrl] = useState(initialSubmission?.fileUrl || '');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!fileUrl) {
      setError('Please provide a URL to your submission.');
      return;
    }
    
    // Basic URL validation
    try {
      new URL(fileUrl);
    } catch (_) {
      setError('Please enter a valid URL (e.g., https://github.com/...)');
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      const res = await fetch(`/api/v1/assignments/${assignmentId}/submissions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ fileUrl }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || 'Failed to submit assignment');
      }

      router.refresh();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="glass-panel" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderBottom: '1px solid var(--color-border)', paddingBottom: '1rem', marginBottom: '0.5rem' }}>
        <h2 style={{ fontSize: '1.25rem', fontWeight: 600 }}>Your Work</h2>
        {initialSubmission && (
          <span className="badge badge-success">
            Submitted {initialSubmission.submittedAt}
          </span>
        )}
      </div>

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
          <label htmlFor="submissionUrl" style={{ fontSize: '0.875rem', fontWeight: 500 }}>Submission Link (Google Drive, GitHub, Figma, etc.)</label>
          <input 
            type="url" 
            id="submissionUrl"
            value={fileUrl}
            onChange={(e) => setFileUrl(e.target.value)}
            placeholder="https://..."
            style={{ 
              padding: '0.75rem', 
              borderRadius: '8px', 
              border: '1px solid var(--color-border)',
              background: 'var(--color-bg-surface)',
              color: 'var(--color-text-primary)'
            }}
          />
        </div>

        {error && (
          <div style={{ padding: '0.75rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: '8px', fontSize: '0.875rem' }}>
            {error}
          </div>
        )}

        <button 
          type="submit" 
          className="btn-primary" 
          disabled={isSubmitting || (!initialSubmission && !fileUrl)}
          style={{ alignSelf: 'flex-start', marginTop: '0.5rem' }}
        >
          {isSubmitting ? 'Submitting...' : initialSubmission ? 'Update Submission' : 'Turn In'}
        </button>
      </form>
    </div>
  );
}

import React from 'react';
import { cookies } from 'next/headers';
import { db } from '@talora/database';
import { headers } from 'next/headers';
import SubmissionClient from './SubmissionClient';
import Link from 'next/link';

export default async function AssignmentDetailsPage({ params }: { params: { id: string } }) {
  const scopeHeader = headers().get('x-user-scope');
  let assignment: any = null;
  let submission: any = null;

  if (scopeHeader) {
    try {
      const payload = JSON.parse(scopeHeader);
      
      const dbAssignment = await db.assignment.findUnique({
        where: { id: params.id },
        include: { offering: { include: { unit: true, class: true } } }
      });

      if (dbAssignment) {
        assignment = {
          id: dbAssignment.id,
          title: dbAssignment.title,
          description: dbAssignment.description,
          type: dbAssignment.type,
          dueDate: new Date(dbAssignment.dueDate).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }),
          isPast: new Date(dbAssignment.dueDate) < new Date(),
          offeringName: `${dbAssignment.offering.unit.title} ┬╖ ${dbAssignment.offering.class.name}`
        };

        const dbSubmission = await db.submission.findFirst({
          where: { assignmentId: dbAssignment.id, studentId: payload.userId }
        });

        if (dbSubmission) {
          submission = {
            id: dbSubmission.id,
            fileUrl: dbSubmission.fileUrl,
            submittedAt: new Date(dbSubmission.submittedAt).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })
          };
        }
      }
    } catch (e) {
      console.error(e);
    }
  }

  if (!assignment) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', minHeight: '100%' }}>
        <header className="page-header">
          <div>
            <h1>Assignment Not Found</h1>
            <p>This assignment does not exist or you do not have permission to view it.</p>
          </div>
        </header>
        <Link href="/assignments" className="btn-secondary" style={{ width: 'fit-content', textDecoration: 'none' }}>Back to Assignments</Link>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', minHeight: '100%', maxWidth: '800px', margin: '0 auto', width: '100%' }}>
      <header className="page-header">
        <div>
          <Link href="/assignments" style={{ color: 'var(--color-primary)', textDecoration: 'none', fontSize: '0.875rem', display: 'inline-flex', alignItems: 'center', gap: '0.25rem', marginBottom: '0.5rem' }}>
            &larr; Back to Assignments
          </Link>
          <h1 style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            {assignment.title}
            <span className={`badge ${assignment.type === 'HOMEWORK' ? 'badge-primary' : assignment.type === 'PROJECT' ? 'badge-warning' : 'badge-danger'}`} style={{ fontSize: '0.75rem', fontWeight: 600 }}>
              {assignment.type}
            </span>
          </h1>
          <p>{assignment.offeringName}</p>
        </div>
      </header>

      <div className="glass-panel" style={{ padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
        <div>
          <h3 style={{ fontSize: '1rem', color: 'var(--color-text-secondary)', marginBottom: '0.5rem' }}>Description</h3>
          <div style={{ color: 'var(--color-text-primary)', whiteSpace: 'pre-wrap', lineHeight: 1.5 }}>
            {assignment.description}
          </div>
        </div>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '1rem', background: assignment.isPast ? 'var(--color-danger-bg)' : 'var(--color-bg-surface-hover)', borderRadius: '8px', color: assignment.isPast ? 'var(--color-danger)' : 'var(--color-text-primary)' }}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
          <strong>Due Date:</strong> {assignment.dueDate}
          {assignment.isPast && <span className="badge badge-danger" style={{ marginLeft: 'auto' }}>Overdue</span>}
        </div>
      </div>

      <SubmissionClient assignmentId={assignment.id} initialSubmission={submission} />
    </div>
  );
}

