    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';

export default function EnrollPage() {
  const router = useRouter();
  const [offerings, setOfferings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [enrollingId, setEnrollingId] = useState<string | null>(null);
  const [error, setError] = useState('');
  
  useEffect(() => {
    const fetchOfferings = async () => {
      try {
        const res = await fetch('/api/v1/offerings?available=true');
        const data = await res.json();
        if (res.ok) {
          setOfferings(data.data || []);
        } else {
          setError(data.error || 'Failed to fetch offerings');
        }
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    fetchOfferings();
  }, []);

  const handleEnroll = async (offeringId: string) => {
    setEnrollingId(offeringId);
    setError('');
    try {
      const res = await fetch('/api/v1/me/enrollments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ offeringId })
      });
      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.error || data.message || 'Failed to enroll');
      }

      // Automatically set this as active offering using the server endpoint
      await fetch('/api/v1/active-offering', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ offeringId })
      });
      
      // Redirect to dashboard
      router.push('/');
      router.refresh();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setEnrollingId(null);
    }
  };

  return (
    <div className="flex flex-col gap-8 max-w-4xl mx-auto pt-4 sm:pt-8">
      <header className="page-header">
        <div>
          <div className="eyebrow" style={{ marginBottom: '0.375rem' }}>Course enrollment</div>
          <h1>Choose your units</h1>
          <p className="text-text-secondary text-sm">Select the course units you intend to study this semester.</p>
        </div>
      </header>

      {error && (
        <div className="p-4 bg-danger-bg text-danger rounded-md text-sm border border-danger/20">
          {error}
        </div>
      )}

      {loading ? (
        <div className="text-center text-text-muted p-8">Loading available coursesΓÇª</div>
      ) : (
        <div className="flex flex-col gap-4">
          {offerings.map(offering => (
            <div key={offering.id} className="ledger-panel p-6 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div className="flex-1">
                <div className="text-lg font-semibold text-text-primary mb-1" style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
                  {offering.unit.code} ΓÇö {offering.unit.title}
                </div>
                <div className="text-sm text-text-secondary">
                  {offering.term.name} ΓÇó Class: {offering.class.name}
                </div>
                {offering.unit.lecturerName && (
                  <div className="reg-number mt-2">
                    Lecturer: {offering.unit.lecturerName}
                  </div>
                )}
              </div>
              <button 
                className="btn-primary w-full sm:w-auto" 
                onClick={() => handleEnroll(offering.id)}
                disabled={enrollingId !== null}
              >
                {enrollingId === offering.id ? 'EnrollingΓÇª' : 'Enroll'}
              </button>
            </div>
          ))}

          {offerings.length === 0 && (
            <div className="text-center p-12 ledger-panel text-text-muted">
              No available courses found to enroll in.
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';

export default function ClassSettingsModal({ 
  offeringId, 
  currentMin, 
  currentMax, 
  onClose 
}: { 
  offeringId: string, 
  currentMin: number, 
  currentMax: number, 
  onClose: () => void 
}) {
  const router = useRouter();
  const [minGroupSize, setMinGroupSize] = useState(currentMin);
  const [maxGroupSize, setMaxGroupSize] = useState(currentMax);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (minGroupSize > maxGroupSize) {
      setError('Minimum group size cannot be greater than maximum group size.');
      return;
    }
    if (minGroupSize < 1) {
      setError('Minimum group size must be at least 1.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/v1/offerings/${offeringId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ minGroupSize, maxGroupSize })
      });

      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.message || data.error || 'Failed to update class settings');
      }

      router.refresh();
      onClose();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100 }}>
      <div className="glass-panel" style={{ width: '400px', padding: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 className="font-display" style={{ fontSize: '1.25rem', fontWeight: 600 }}>Group size rules</h2>
          <button onClick={onClose} className="btn-ghost" style={{ padding: '0.4rem' }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        {error && (
          <div style={{ padding: '0.75rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem' }}>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          
          <div>
            <label className="label">Minimum group size</label>
            <input 
              type="number" 
              className="input" 
              value={minGroupSize} 
              onChange={(e) => setMinGroupSize(parseInt(e.target.value) || 1)}
              min={1}
              required 
            />
          </div>

          <div>
            <label className="label">Maximum group size</label>
            <input 
              type="number" 
              className="input" 
              value={maxGroupSize} 
              onChange={(e) => setMaxGroupSize(parseInt(e.target.value) || 1)}
              min={1}
              required 
            />
          </div>

          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '0.5rem' }}>
            <button type="button" onClick={onClose} className="btn-secondary" disabled={loading}>Cancel</button>
            <button type="submit" className="btn-primary" disabled={loading}>
              {loading ? 'SavingΓÇª' : 'Save rules'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

