import React from 'react';
import { resolveAuthorizedOffering } from '@/lib/getActiveOffering';
import { Card } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { db } from '@talora/database';
import { headers } from 'next/headers';
import CreateIssueButton from './CreateIssueButton';
import IssueActionButtons from './IssueActionButtons';

export default async function IssuesPage() {
  const scopeHeader = headers().get('x-user-scope');
  let issues: any[] = [];
  let offeringName = 'No Offering Selected';
  let offeringId = '';
  let isRep = false;

  if (scopeHeader) {
    try {
      const payload = JSON.parse(scopeHeader);
      isRep = payload.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE');

      const offering = await resolveAuthorizedOffering(payload);

      if (offering) {
        offeringId = offering.id;
        offeringName = `${offering.term.name} ┬╖ ${offering.unit.title} ┬╖ ${offering.class.name}`;
        
        const whereClause: any = { offeringId: offering.id };
        if (!isRep) {
          whereClause.studentId = payload.userId;
        }

        const dbIssues = await db.issue.findMany({
          where: whereClause,
          orderBy: { createdAt: 'desc' },
          include: {
            student: { select: { fullName: true } }
          }
        });

        issues = dbIssues.map(i => ({
          id: i.id,
          title: i.title,
          description: i.description,
          category: i.category,
          status: i.status,
          author: i.student.fullName,
          date: new Date(i.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
        }));
      }
    } catch (e) {
      console.error(e);
    }
  }

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
      case 'OPEN': return 'danger';
      case 'TRIAGED': return 'warning';
      case 'RESOLVED': return 'success';
      default: return 'default';
    }
  };

  return (
    <div className="flex flex-col gap-6 h-full">
      {/* Header */}
      <header className="page-header">
        <div>
          <div className="eyebrow" style={{ marginBottom: '0.375rem' }}>{isRep ? 'All issues' : 'My issues'}</div>
          <h1>{offeringName}</h1>
        </div>
        <div className="flex items-center gap-3">
          {offeringId && (
            <CreateIssueButton offeringId={offeringId} />
          )}
        </div>
      </header>

      {/* Desktop Table */}
      <div className="hidden lg:block ledger-panel overflow-x-auto flex-1">
        <table className="w-full text-left border-collapse min-w-[800px]">
          <thead>
            <tr style={{ borderBottom: '1px solid var(--border-rule)' }} className="bg-bg-surface-hover/30">
              <th className="py-4 px-6 eyebrow w-[15%]">Date</th>
              <th className="py-4 px-6 eyebrow w-1/4">Title</th>
              <th className="py-4 px-6 eyebrow w-1/4">Author</th>
              <th className="py-4 px-6 eyebrow w-[15%]">Category</th>
              <th className="py-4 px-6 eyebrow w-[10%]">Status</th>
              <th className="py-4 px-6 eyebrow text-right w-[10%]">Actions</th>
            </tr>
          </thead>
          <tbody>
            {issues.length === 0 ? (
              <tr>
