                      </span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile Cards */}
      <div className="lg:hidden flex flex-col gap-4">
        {issues.length === 0 ? (
          <div className="text-center p-8 text-text-muted ledger-panel">
            No issues found.
          </div>
        ) : (
          issues.map((issue) => (
            <Card key={issue.id} className="p-4 flex flex-col gap-3">
              <div className="flex justify-between items-start gap-4">
                <div>
                  <div className="text-base font-semibold text-text-primary mb-1" style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>{issue.title}</div>
                  <div className="text-xs text-text-muted line-clamp-2">{issue.description}</div>
                </div>
                <Badge variant={getStatusBadgeVariant(issue.status) as any}>{issue.status.charAt(0) + issue.status.slice(1).toLowerCase()}</Badge>
              </div>
              
              <div className="flex items-center gap-3 text-xs text-text-secondary mt-1">
                <span className="reg-number">{issue.date}</span>
                <span>ΓÇó</span>
                <span>{issue.author}</span>
                <span>ΓÇó</span>
                <Badge variant="default">{issue.category}</Badge>
              </div>

              <div className="mt-2 flex justify-end">
                {isRep ? (
                  <IssueActionButtons issueId={issue.id} currentStatus={issue.status} />
                ) : (
                  <span className="text-xs text-text-muted">
                    {issue.status === 'RESOLVED' ? 'Resolved' : 'Pending review'}
                  </span>
                )}
              </div>
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { cookies, headers } from 'next/headers';
import SidebarNav from './SidebarNav';
import CourseSwitcher from '../../components/CourseSwitcher';
import DashboardClientShell from './DashboardClientShell';
import PhoneOnboardingModal from './PhoneOnboardingModal';

export const metadata = {
  title: 'Talora ΓÇö Class & Group Coordination Platform',
  description: 'API-first university class coordination, group formation, and submission management platform.',
};

export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  const token = cookies().get('talora_token')?.value;
  let userInitials = 'U';
  let userName = 'Unknown User';
  let userRole = 'Student';
  let unreadCount = 0;
  let userNeedsOnboarding = false;
  let currentUserId = '';

  let availableOfferings: any[] = [];
  const activeOfferingId: string | null = cookies().get('active_offering_id')?.value || null;
  const scopeHeader = headers().get('x-user-scope');

  if (scopeHeader) {
    try {
      const payload = JSON.parse(scopeHeader);
      const { db } = await import('@talora/database');
      const user = await db.user.findUnique({ where: { id: payload.userId } });
      if (user) {
        currentUserId = user.id;
        userNeedsOnboarding = !user.phoneNumber || !user.acceptedTerms;
        userName = user.fullName;
        userInitials = user.fullName.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        
        // Prioritize showing the highest role
        const topRole = payload.roles.find((r: any) => r.role === 'PLATFORM_ADMIN') 
                     || payload.roles.find((r: any) => r.role === 'CLASS_REPRESENTATIVE') 
                     || payload.roles[0];
                     
        userRole = topRole?.role?.replace('_', ' ')?.toLowerCase() || 'Student';
        unreadCount = await db.notification.count({ where: { userId: user.id, isRead: false } });

        // Fetch available offerings for this user
        // We look at their enrollments
        const enrollments = await db.enrollment.findMany({
          where: { studentId: user.id },
          include: { offering: { include: { unit: true, class: true, term: true } } }
        });
        availableOfferings = enrollments.map(e => ({
          id: e.offering.id,
          unit: { title: e.offering.unit.title },
          class: { name: e.offering.class.name }
        }));

        if (availableOfferings.length === 0) {
          const rawOfferings = await db.courseOffering.findMany({
            include: { unit: true, class: true, term: true },
            take: 10
          });
          availableOfferings = rawOfferings.map((o: any) => ({
            id: o.id,
            unit: { title: o.unit.title, code: o.unit.code },
            class: { name: o.class.name }
          }));
        }
      }
    } catch (e) {
      console.error(e);
    }
  }

  // Build course context label for sidebar
  const activeOffering = availableOfferings.find((o: any) => o.id === activeOfferingId) || availableOfferings[0];
  const courseContext = activeOffering
    ? `${activeOffering.class?.name} ┬╖ ${activeOffering.unit?.title}`
    : '';

  const sidebarContent = (
    <SidebarNav
      userRole={userRole}
      unreadCount={unreadCount}
      userName={userName}
      userInitials={userInitials}
      courseContext={courseContext}
    />
  );

  const topbarContent = (
    <>
      <CourseSwitcher availableOfferings={availableOfferings} activeOfferingId={activeOfferingId} />
      <form action="/api/v1/auth/logout" method="POST">
        <button type="submit" style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', letterSpacing: '0.06em', textTransform: 'uppercase', padding: '0.375rem 0.75rem', borderRadius: '4px', border: '1px solid var(--border-strong)', background: 'transparent', color: 'var(--color-text-muted)', cursor: 'pointer' }}>Log out</button>
      </form>
    </>
  );

  if (userNeedsOnboarding) {
    return (
      <div className="flex h-screen bg-bg-base overflow-hidden w-full items-center justify-center">
        <PhoneOnboardingModal userId={currentUserId} />
      </div>
    );
  }

  return (
    <DashboardClientShell sidebarContent={sidebarContent} topbarContent={topbarContent}>
      {children}
    </DashboardClientShell>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';

export default function NotificationActionButtons({ notificationId }: { notificationId: string }) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const handleMarkAsRead = async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/v1/notifications/${notificationId}/read`, {
        method: 'PATCH'
      });

      if (!res.ok) {
        throw new Error('Failed to mark as read');
      }

      router.refresh();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <button 
      onClick={handleMarkAsRead} 
      disabled={loading}
      className="btn-ghost" 
      style={{ padding: '0.25rem 0.5rem', fontSize: '0.75rem', color: 'var(--color-primary)' }}
    >
      Mark read
    </button>
  );
}

import React from 'react';
import { cookies } from 'next/headers';
import { db } from '@talora/database';
import { headers } from 'next/headers';
import NotificationActionButtons from './NotificationActionButtons';

export default async function NotificationsPage() {
  const scopeHeader = headers().get('x-user-scope');
  let notifications: any[] = [];

  if (scopeHeader) {
    try {
      const payload = JSON.parse(scopeHeader);

      const dbNotifications = await db.notification.findMany({
        where: { userId: payload.userId },
        orderBy: { createdAt: 'desc' }
      });

      notifications = dbNotifications.map(n => ({
        id: n.id,
        title: n.title,
        message: n.message,
        isRead: n.isRead,
        date: new Date(n.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
      }));
    } catch (e) {
      console.error(e);
    }
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', minHeight: '100%' }}>
      {/* Header */}
      <header className="page-header">
        <div>
          <div className="eyebrow" style={{ marginBottom: '0.375rem' }}>Notifications</div>
          <h1>Stay in the loop</h1>
          <p>Group changes, assignments, and announcements land here</p>
        </div>
      </header>

      {/* Main Content Card */}
      <div className="ledger-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '1.5rem' }}>
          {notifications.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '3rem', color: 'var(--color-text-muted)' }}>
              You're all caught up ΓÇö no notifications.
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
              {notifications.map((notif) => (
                <div key={notif.id} style={{ display: 'flex', alignItems: 'flex-start', gap: '1rem', padding: '1rem', borderRadius: '8px', background: notif.isRead ? 'transparent' : 'var(--color-bg-surface-hover)', boxShadow: notif.isRead ? 'none' : 'inset 3px 0 0 var(--color-primary)' }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.25rem' }}>
                      <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontWeight: 600, color: notif.isRead ? 'var(--color-text-secondary)' : 'var(--color-text-primary)' }}>
                        {notif.title}
                      </div>
                      <div className="reg-number">
                        {notif.date}
                      </div>
                    </div>
                    <div style={{ fontSize: '0.875rem', color: notif.isRead ? 'var(--color-text-muted)' : 'var(--color-text-secondary)' }}>
                      {notif.message}
                    </div>
                  </div>
                  {!notif.isRead && (
                    <NotificationActionButtons notificationId={notif.id} />
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

