          </div>
          {myGroup ? (
            <>
              <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.375rem', fontWeight: 700, letterSpacing: '-0.02em', color: 'var(--color-text-primary)', marginBottom: '1rem' }}>
                {myGroup.name}
              </div>
