            <>
              <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.125rem', fontWeight: 600, letterSpacing: '-0.02em', color: 'var(--color-text-primary)', marginBottom: '0.5rem', lineHeight: 1.3 }}>
                {latestNotif.title}
