              {latestNotif.body && (
                <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', lineHeight: 1.6, marginBottom: '0.75rem', display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden' } as any}>
                  {latestNotif.body}
                </div>
              )}
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', color: 'var(--color-text-muted)' }}>
                {new Date(latestNotif.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
              </div>
              <a href="/notifications" className="btn-inline" style={{ marginTop: '0.75rem', display: 'inline-flex' }}>All notifications ΓåÆ</a>
            </>
          ) : (
            <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.125rem', color: 'var(--color-text-muted)' }}>
              Nothing new.
            </div>
          )}
        </div>
      </div>

      {/* ΓöÇΓöÇ Class Overview ΓÇö Reps / Admins ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {isRepOrAdmin && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          {/* Section label */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.16em', textTransform: 'uppercase', color: 'var(--color-text-muted)' }}>
              Class overview
            </div>
            <div style={{ flex: 1, height: '1px', background: 'var(--border-rule)' }} />
            <span className="badge badge-violet">Rep</span>
          </div>

          {/* KPI ledger row */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '0.75rem' }}>
            {kpis.filter(k => k.key !== 'deadlines').map(kpi => (
              <a key={kpi.key} href={kpi.link.startsWith('/') ? kpi.link : '#'} className="ledger-panel hover-border" style={{ padding: '1.125rem 1.25rem', display: 'flex', flexDirection: 'column', gap: '0.25rem', textDecoration: 'none', transition: 'border-color 0.15s ease' }}>
                <div style={{ fontFamily: 'var(--font-display)', fontSize: '2rem', fontWeight: 800, letterSpacing: '-0.04em', color: kpi.color, lineHeight: 1 }}>{kpi.value}</div>
                <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--color-text-muted)', marginTop: '0.25rem' }}>{kpi.label}</div>
                <div style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary)', lineHeight: 1.5, marginTop: '0.125rem' }}>{kpi.sub}</div>
              </a>
            ))}
          </div>

          {/* Submission progress */}
          {latestAssignment && (
            <div className="ledger-panel" style={{ padding: '1.25rem 1.5rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.875rem', flexWrap: 'wrap', gap: '0.5rem' }}>
                <div>
                  <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--color-text-muted)', marginBottom: '0.25rem' }}>Submission progress</div>
                  <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.125rem', fontWeight: 600, color: 'var(--color-text-primary)', letterSpacing: '-0.02em' }}>
                    {latestAssignment.title}
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                  <span style={{ fontFamily: 'var(--font-display)', fontSize: '2rem', fontWeight: 800, letterSpacing: '-0.04em', color: 'var(--color-accent-teal)', lineHeight: 1 }}>
                    {stats.totalEnrolled ? Math.round((stats.totalSubmissions / stats.totalEnrolled) * 100) : 0}%
                  </span>
                  <a href="/assignments" className="btn-inline">View ΓåÆ</a>
                </div>
              </div>
              <div className="progress-track" style={{ height: '5px', marginBottom: '0.75rem' }}>
                <div className="progress-fill" style={{ width: `${stats.totalEnrolled ? (stats.totalSubmissions / stats.totalEnrolled) * 100 : 0}%`, background: 'var(--color-accent-teal)' }} />
              </div>
              <div style={{ display: 'flex', gap: '1.5rem', fontSize: '0.8125rem', color: 'var(--color-text-secondary)' }}>
                <span><span style={{ color: 'var(--color-accent-teal)' }}>ΓùÅ</span> {stats.totalSubmissions} submitted</span>
                <span><span style={{ color: 'var(--color-danger)' }}>ΓùÅ</span> {stats.totalEnrolled - stats.totalSubmissions} pending</span>
                <span><span style={{ color: 'var(--color-text-muted)' }}>ΓùÅ</span> {stats.totalEnrolled} total</span>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ΓöÇΓöÇ Recent notifications (non-rep fallback) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {!isRepOrAdmin && recentActivity.length > 1 && (
        <div className="ledger-panel" style={{ overflow: 'hidden' }}>
          <div style={{ padding: '1rem 1.25rem 0.75rem', borderBottom: '1px solid var(--border-rule)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.12em', textTransform: 'uppercase', color: 'var(--color-text-muted)' }}>Notifications</div>
            <a href="/notifications" className="btn-inline" style={{ fontSize: '0.75rem' }}>All ΓåÆ</a>
          </div>
          <div>
            {recentActivity.slice(1).map((item: any) => (
              <div key={item.id} style={{ padding: '0.875rem 1.25rem', borderBottom: '1px solid var(--border-rule)', display: 'flex', alignItems: 'flex-start', gap: '0.75rem' }}>
                <span style={{ width: '6px', height: '6px', borderRadius: '50%', background: 'var(--border-strong)', flexShrink: 0, marginTop: '0.375rem' }} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: '0.875rem', color: 'var(--color-text-primary)', marginBottom: '0.125rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{item.title}</div>
                  <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', color: 'var(--color-text-muted)' }}>{new Date(item.createdAt).toLocaleDateString()}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

    </div>
  );
}

'use client';

import React, { useState } from 'react';

export default function ChangePasswordForm() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  
  const [formData, setFormData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    if (formData.newPassword !== formData.confirmPassword) {
      setError('New passwords do not match');
      setLoading(false);
      return;
    }

    try {
      const res = await fetch(`/api/v1/auth/change-password`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          currentPassword: formData.currentPassword,
          newPassword: formData.newPassword
        })
      });

      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.error || 'Failed to change password');
      }

      setSuccess('Password updated successfully');
      setFormData({ currentPassword: '', newPassword: '', confirmPassword: '' });
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="ledger-panel" style={{ padding: '1.5rem', marginTop: '1.5rem' }}>
      <div className="eyebrow" style={{ marginBottom: '1.25rem' }}>Change password</div>
      
      {error && (
        <div style={{ padding: '0.75rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem', marginBottom: '1.25rem' }}>
          {error}
        </div>
      )}

      {success && (
        <div style={{ padding: '0.75rem', background: 'var(--color-success-bg)', color: 'var(--color-success)', borderRadius: 'var(--radius-md)', fontSize: '0.875rem', marginBottom: '1.25rem' }}>
          {success}
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 500, color: 'var(--color-text-secondary)', marginBottom: '0.5rem' }}>
            Current password
          </label>
          <div style={{ position: 'relative' }}>
            <input 
              type={showPassword ? "text" : "password"}
              className="input" 
              value={formData.currentPassword}
              onChange={e => setFormData({...formData, currentPassword: e.target.value})}
              style={{ width: '100%', paddingRight: '2.5rem' }}
              required
            />
            <button 
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              style={{ position: 'absolute', right: '0.75rem', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: 'var(--color-text-muted)', cursor: 'pointer', padding: 0 }}
            >
              {showPassword ? (
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24M1 1l22 22"/></svg>
              ) : (
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              )}
            </button>
          </div>
        </div>

        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 500, color: 'var(--color-text-secondary)', marginBottom: '0.5rem' }}>
            New password
          </label>
          <div style={{ position: 'relative' }}>
            <input 
              type={showPassword ? "text" : "password"}
              className="input" 
              value={formData.newPassword}
              onChange={e => setFormData({...formData, newPassword: e.target.value})}
              required
              minLength={8}
              style={{ width: '100%', paddingRight: '2.5rem' }}
            />
          </div>
        </div>

        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', fontWeight: 500, color: 'var(--color-text-secondary)', marginBottom: '0.5rem' }}>
            Confirm new password
          </label>
          <div style={{ position: 'relative' }}>
            <input 
              type={showPassword ? "text" : "password"}
              className="input" 
              value={formData.confirmPassword}
              onChange={e => setFormData({...formData, confirmPassword: e.target.value})}
              required
              minLength={8}
              style={{ width: '100%', paddingRight: '2.5rem' }}
            />
          </div>
        </div>

        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '0.5rem' }}>
          <button type="submit" className="btn-primary" disabled={loading}>
            {loading ? 'SavingΓÇª' : 'Update password'}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import PhoneInput from 'react-phone-number-input';
import 'react-phone-number-input/style.css';

export default function ProfileForm({ user }: { user: any }) {
  const router = useRouter();
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  
  const [formData, setFormData] = useState({
    fullName: user.fullName,
    email: user.email,
    studentNumber: user.studentNumber || '',
    registrationNumber: user.registrationNumber || '',
    phoneNumber: user.phoneNumber || ''
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/v1/users/${user.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.message || data.error || 'Failed to update profile');
      }

      if (data.emailChanged) {
        // If email changed, they've been logged out. Redirect to login.
        router.push('/login');
        return;
      }

      setIsEditing(false);
      router.refresh();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (!isEditing) {
    return (
      <div className="ledger-panel" style={{ padding: '1.5rem', position: 'relative' }}>
        <button 
          onClick={() => setIsEditing(true)} 
          className="btn-ghost" 
          style={{ position: 'absolute', top: '1.5rem', right: '1.5rem', padding: '0.4rem' }}
          title="Edit profile"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
        </button>
        
        <div className="eyebrow" style={{ marginBottom: '1.25rem' }}>Personal details</div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          <div>
            <div style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)', marginBottom: '0.25rem' }}>Full name</div>
            <div style={{ fontSize: '0.9375rem', fontFamily: 'var(--font-display)', fontStyle: 'italic', color: 'var(--color-text-primary)' }}>{user.fullName}</div>
          </div>
          <div>
            <div style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)', marginBottom: '0.25rem' }}>Email address</div>
            <div style={{ fontSize: '0.9375rem', color: 'var(--color-text-primary)' }}>{user.email}</div>
          </div>
          <div>
            <div style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)', marginBottom: '0.25rem' }}>Student number</div>
            <div className="reg-number" style={{ fontSize: '0.9375rem' }}>{user.studentNumber || 'ΓÇö'}</div>
          </div>
          <div>
            <div style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)', marginBottom: '0.25rem' }}>Registration number</div>
            <div className="reg-number" style={{ fontSize: '0.9375rem' }}>{user.registrationNumber || 'ΓÇö'}</div>
          </div>
          <div>
            <div style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)', marginBottom: '0.25rem' }}>Phone number</div>
            <div className="reg-number" style={{ fontSize: '0.9375rem' }}>{user.phoneNumber || 'ΓÇö'}</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="ledger-panel" style={{ padding: '1.5rem' }}>
      <div className="eyebrow" style={{ marginBottom: '1.25rem' }}>Edit profile</div>
      
      {error && (
        <div style={{ padding: '0.75rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', borderRadius: '8px', fontSize: '0.875rem', marginBottom: '1rem' }}>
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)' }}>Full name</label>
          <input 
            type="text" 
            className="input" 
            value={formData.fullName}
            onChange={e => setFormData({...formData, fullName: e.target.value})}
            required
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)' }}>Email address</label>
          <input 
            type="email" 
            className="input" 
            value={formData.email}
            onChange={e => setFormData({...formData, email: e.target.value})}
            required
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)' }}>Student number</label>
          <input 
            type="text" 
            className="input" 
            value={formData.studentNumber}
            onChange={e => setFormData({...formData, studentNumber: e.target.value})}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)' }}>Registration number</label>
          <input 
            type="text" 
            className="input" 
            value={formData.registrationNumber}
            onChange={e => setFormData({...formData, registrationNumber: e.target.value})}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.875rem', marginBottom: '0.5rem', color: 'var(--color-text-secondary)' }}>Phone number</label>
          <PhoneInput
            international
            defaultCountry="UG"
            className="input phone-input"
            value={formData.phoneNumber}
            onChange={(value) => setFormData({...formData, phoneNumber: value || ''})}
            style={{ 
              '--PhoneInputCountryFlag-height': '16px',
              '--PhoneInput-color--focus': 'var(--color-primary)'
            } as any}
          />
        </div>
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.5rem', marginTop: '0.5rem' }}>
          <button type="button" onClick={() => setIsEditing(false)} className="btn-secondary">Cancel</button>
          <button type="submit" className="btn-primary" disabled={loading}>
            {loading ? 'SavingΓÇª' : 'Save changes'}
          </button>
        </div>
      </form>
    </div>
  );
}

import React from 'react';
import { headers } from 'next/headers';
import { db } from '@talora/database';
import ProfileForm from './ProfileForm';
import ChangePasswordForm from './ChangePasswordForm';
import DeleteAccountButton from './DeleteAccountButton';

export default async function ProfilePage() {
  const scopeHeader = headers().get('x-user-scope');
  let user: any = null;

  if (scopeHeader) {
    try {
      const scope = JSON.parse(scopeHeader);
      user = await db.user.findUnique({
        where: { id: scope.userId },
        include: {
          roles: {
            include: { class: true }
          },
          enrollments: {
            include: { offering: { include: { unit: true, class: true, term: true } } }
          }
        }
      });
    } catch (e) {
      console.error('Failed to load profile:', e);
    }
  }

  if (!user) {
    return (
      <div className="ledger-panel" style={{ padding: '2rem', textAlign: 'center' }}>
        <p style={{ color: 'var(--color-text-muted)' }}>Could not load your profile.</p>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
      <header className="page-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
          <div style={{ width: '72px', height: '72px', borderRadius: '50%', background: 'var(--color-primary-transparent)', color: 'var(--color-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.75rem', fontFamily: 'var(--font-display)', fontStyle: 'italic', fontWeight: 700, border: '2px solid var(--color-primary)' }}>
            {user.fullName.split(' ').map((n: string) => n[0]).join('').substring(0, 2).toUpperCase()}
          </div>
          <div>
            <div className="eyebrow" style={{ marginBottom: '0.375rem' }}>Profile</div>
            <h1>{user.fullName}</h1>
          </div>
        </div>
        <div className="page-header-actions" style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <form action="/api/v1/auth/logout" method="POST">
            <button type="submit" className="btn-secondary" style={{ color: 'var(--color-text-secondary)', borderColor: 'var(--border-subtle)' }}>
              Log out
            </button>
          </form>
          <DeleteAccountButton userId={user.id} />
        </div>
      </header>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '1.5rem' }}>
        {/* Personal Details */}
        <ProfileForm user={user} />
        
        {/* Password Change */}
        <ChangePasswordForm />
      </div>

      <div className="profile-grid">
        {/* Roles and Permissions */}
        <div className="ledger-panel" style={{ padding: '1.5rem' }}>
          <div className="eyebrow" style={{ marginBottom: '1.25rem' }}>Active roles</div>
          
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {user.roles.map((role: any) => (
              <div key={role.id} className="profile-card" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                <span className="roster-dot filled" />
                <div>
                  <div style={{ fontSize: '0.875rem', fontWeight: 500, color: 'var(--color-text-primary)' }}>
                    {role.role.replace(/_/g, ' ').toLowerCase().replace(/\b\w/g, (c: string) => c.toUpperCase())}
                  </div>
                  {role.class && (
                    <div className="reg-number">{role.class.name}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Enrolled Courses */}
        <div className="ledger-panel" style={{ padding: '1.5rem' }}>
          <div className="eyebrow" style={{ marginBottom: '1.25rem' }}>Enrolled courses</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            {user.enrollments.map((enrollment: any) => (
              <div key={enrollment.id} className="profile-card" style={{ fontSize: '0.875rem', color: 'var(--color-text-primary)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
                    <strong>{enrollment.offering.unit.code}</strong> ΓÇö {enrollment.offering.unit.title}
                  </div>
                  <span className="badge badge-success" style={{ flexShrink: 0, marginLeft: '0.5rem' }}>Active</span>
                </div>
                <div className="reg-number" style={{ marginTop: '0.25rem' }}>
                  {enrollment.offering.term.name} ΓÇó {enrollment.offering.class.name}
                </div>
              </div>
            ))}
            {user.enrollments.length === 0 && (
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-muted)' }}>Not enrolled in any courses yet.</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';
import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { toast } from 'sonner';
import { useRouter } from 'next/navigation';

export default function RosterImportWizard() {
  const router = useRouter();
  const [step, setStep] = useState<1 | 2 | 3 | 4 | 5>(1);
  
  // Selections
  const [importType, setImportType] = useState<'CLASS_ROSTER' | 'COURSE_ENROLLMENT' | null>(null);
  const [offeringId, setOfferingId] = useState<string>('');
  const [offerings, setOfferings] = useState<any[]>([]);
  const [file, setFile] = useState<File | null>(null);

  // Preview Data
  const [isParsing, setIsParsing] = useState(false);
  const [previewData, setPreviewData] = useState<any>(null);
  
  // Mapping State
  const [mapping, setMapping] = useState<Record<string, string>>({});

  // Execute State
  const [isExecuting, setIsExecuting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [results, setResults] = useState<any>(null);

  // Fetch Offerings (Simulating Class Rep context)
  useEffect(() => {
    fetch('/api/v1/offerings')
      .then(res => res.json())
      .then(data => {
        if (data.data) {
          setOfferings(data.data);
          if (data.data.length > 0) setOfferingId(data.data[0].id);
        }
      })
      .catch(err => console.error(err));
  }, []);

  const handleUpload = async () => {
    if (!file || !importType || !offeringId) {
      toast.error('Please complete all fields in Step 1');
      return;
    }

    setIsParsing(true);
    const formData = new FormData();
    formData.append('file', file);
    
    try {
      const res = await fetch('/api/v1/roster-import/preview', {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      
      if (!res.ok) throw new Error(data.error || 'Failed to parse file');
      
      setPreviewData(data.data);
      if (data.data.suggestedMapping) {
        setMapping(data.data.suggestedMapping);
      }
      
      // If section-based and AI worked, skip straight to review
      if (data.data.structureType === 'SECTION_BASED' && data.data.extractedSample) {
        setStep(3);
      } else {
        setStep(2); // Normal mapping step
      }
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setIsParsing(false);
    }
  };

  const handleExecute = async () => {
    setIsExecuting(true);
    setImportProgress(0);
    
    // Smooth simulated progress that slows down as it gets closer to 95%
    const progressInterval = setInterval(() => {
      setImportProgress(prev => {
        if (prev >= 95) return prev;
        return prev + Math.max(0.5, (95 - prev) * 0.05);
      });
    }, 200);

    const formData = new FormData();
    formData.append('file', file!);
    formData.append('offeringId', offeringId);
    formData.append('importType', importType!);
    formData.append('structureType', previewData.structureType);
    if (previewData.structureType === 'FLAT') {
       const backendMapping: Record<string, string> = {};
       Object.entries(mapping).forEach(([colIndex, field]) => {
         backendMapping[colIndex] = field;
       });
       formData.append('mapping', JSON.stringify(backendMapping));
    }
    formData.append('dryRun', 'true');

    try {
      const res = await fetch('/api/v1/roster-import/execute', {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      
      clearInterval(progressInterval);
      setImportProgress(100);
      
      // Wait for progress bar to hit 100% visually before switching steps
      setTimeout(() => {
        setResults(data.data);
        setStep(4);
      }, 400);
    } catch (err: any) {
      clearInterval(progressInterval);
      toast.error(err.message);
    } finally {
      setTimeout(() => setIsExecuting(false), 400);
    }
  };

  const handleApplyChanges = async () => {
    setIsExecuting(true);
    setImportProgress(0);
    
    const progressInterval = setInterval(() => {
      setImportProgress(prev => {
        if (prev >= 95) return prev;
        return prev + Math.max(0.5, (95 - prev) * 0.05);
      });
    }, 200);

    const formData = new FormData();
    formData.append('file', file!);
    formData.append('offeringId', offeringId);
    formData.append('importType', importType!);
    formData.append('structureType', previewData.structureType);
    if (previewData.structureType === 'FLAT') {
       const backendMapping: Record<string, string> = {};
       Object.entries(mapping).forEach(([colIndex, field]) => {
         backendMapping[colIndex] = field;
       });
       formData.append('mapping', JSON.stringify(backendMapping));
    }
    formData.append('dryRun', 'false');

    try {
      const res = await fetch('/api/v1/roster-import/execute', {
        method: 'POST',
        body: formData
      });
      const data = await res.json();
      
      clearInterval(progressInterval);
      setImportProgress(100);
      
      setTimeout(() => {
        setResults(data.data);
        setStep(5);
      }, 400);
    } catch (err: any) {
      clearInterval(progressInterval);
      toast.error(err.message);
    } finally {
      setTimeout(() => setIsExecuting(false), 400);
    }
  };


  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', maxWidth: '900px', margin: '0 auto' }}>
      {/* Header */}
      <header>
        <Link href="/roster" style={{ color: 'var(--color-primary)', fontSize: '0.875rem', display: 'inline-block', marginBottom: '1rem', textDecoration: 'none' }}>
          ΓåÉ Back to Roster
        </Link>
        <h1 style={{ fontSize: '1.875rem', marginBottom: '0.25rem', color: 'var(--color-text-primary)' }}>Advanced Roster Import</h1>
        <p style={{ color: 'var(--color-text-secondary)', margin: 0, fontSize: '0.875rem' }}>
          Import your class lists. Handles retakers, partial data, and unstructured groupings automatically.
        </p>
      </header>

      {/* Stepper UI */}
      <div className="glass-panel" style={{ padding: '1.5rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        {[
          { num: 1, label: 'Upload' },
          { num: 2, label: 'Map Columns' },
          { num: 3, label: 'Review' },
          { num: 4, label: 'Simulate' },
          { num: 5, label: 'Complete' }
        ].map((s, i, arr) => (
          <React.Fragment key={s.num}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', color: step >= s.num ? 'var(--color-primary)' : 'var(--color-text-secondary)' }}>
              <div style={{ width: '24px', height: '24px', borderRadius: '50%', background: step >= s.num ? 'var(--color-primary)' : 'transparent', border: step >= s.num ? 'none' : '2px solid var(--border-strong)', color: step >= s.num ? 'white' : 'inherit', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.75rem', fontWeight: 'bold' }}>{s.num}</div>
              <span style={{ fontWeight: 600, fontSize: '0.875rem' }}>{s.label}</span>
            </div>
            {i < arr.length - 1 && <div style={{ flex: 1, height: '2px', background: step > s.num ? 'var(--color-primary)' : 'var(--border-strong)', margin: '0 1rem' }}></div>}
          </React.Fragment>
        ))}
      </div>

      {/* STEP 1: UPLOAD */}
      {step === 1 && (
        <div className="glass-panel" style={{ padding: '2rem', display: 'flex', flexDirection: 'column', gap: '2rem' }}>
          
          <div>
            <h3 style={{ fontSize: '1.125rem', marginBottom: '1rem', color: 'var(--color-text-primary)' }}>1. What are you importing?</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
              <div 
                onClick={() => setImportType('CLASS_ROSTER')}
                style={{ border: `2px solid ${importType === 'CLASS_ROSTER' ? 'var(--color-primary)' : 'var(--border-subtle)'}`, padding: '1.5rem', borderRadius: '12px', cursor: 'pointer', background: importType === 'CLASS_ROSTER' ? 'var(--color-primary-transparent)' : 'var(--color-bg-surface)' }}
              >
                <div style={{ fontWeight: 600, marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>≡ƒÅ½ Class Roster</div>
                <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)' }}>The definitive list of students in this cohort. Creates accounts and adds them to the ClassCohort record. Retakers will be flagged as errors.</div>
              </div>
              <div 
                onClick={() => setImportType('COURSE_ENROLLMENT')}
                style={{ border: `2px solid ${importType === 'COURSE_ENROLLMENT' ? 'var(--color-primary)' : 'var(--border-subtle)'}`, padding: '1.5rem', borderRadius: '12px', cursor: 'pointer', background: importType === 'COURSE_ENROLLMENT' ? 'var(--color-primary-transparent)' : 'var(--color-bg-surface)' }}
              >
                <div style={{ fontWeight: 600, marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>≡ƒô¥ Course Enrollment List</div>
                <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)' }}>Registrar list for a specific course. Allows and flags retakers correctly. Only affects enrollment, not the core cohort record.</div>
              </div>
            </div>
          </div>

          <div>
             <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 600, fontSize: '0.875rem' }}>Select Course Offering</label>
              <select 
                value={offeringId} 
                onChange={e => setOfferingId(e.target.value)}
                style={{ width: '100%', padding: '0.75rem', borderRadius: '8px', border: '1px solid var(--border-subtle)', background: 'var(--color-bg-surface)', color: 'var(--color-text-primary)' }}
              >
                {offerings.length === 0 && <option value="">Loading offerings...</option>}
                {offerings.map(o => (
                  <option key={o.id} value={o.id}>{o.class?.name || o.id} - {o.unit?.code || 'Course'}</option>
                ))}
              </select>
          </div>

          <div>
            <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 600, fontSize: '0.875rem' }}>Spreadsheet File (.xlsx or .csv)</label>
            <input 
              type="file" 
              accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel"
              onChange={(e) => {
                if (e.target.files) setFile(e.target.files[0]);
              }}
              style={{ display: 'block', width: '100%', padding: '1rem', border: '2px dashed var(--border-strong)', borderRadius: '8px', background: 'var(--color-bg-surface)' }}
            />
          </div>

          <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '1rem' }}>
            <button className="btn-primary" disabled={!file || !importType || isParsing} onClick={handleUpload}>
              {isParsing ? 'Analyzing Structure...' : 'Next Step ΓåÆ'}
            </button>
          </div>
        </div>
      )}

      {/* STEP 2: MAPPING (Only for FLAT structures) */}
      {step === 2 && previewData?.structureType === 'FLAT' && (
        <div className="glass-panel" style={{ padding: '2rem' }}>
          <h3 style={{ fontSize: '1.25rem', marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>Map Columns</h3>
          <p style={{ color: 'var(--color-text-secondary)', marginBottom: '2rem', fontSize: '0.875rem' }}>
            We've auto-detected some columns based on your headers. Please verify and map the rest.
          </p>

          <div style={{ overflowX: 'auto', borderRadius: '8px', border: '1px solid var(--border-subtle)' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.875rem' }}>
              <thead style={{ background: 'var(--color-bg-surface)' }}>
                <tr>
                  {previewData.columns.map((col: string, i: number) => (
                    <th key={i} style={{ padding: '1rem', borderBottom: '1px solid var(--border-subtle)', borderRight: '1px solid var(--border-subtle)' }}>
                      <div style={{ fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: '0.5rem' }}>{col}</div>
                      <select 
                        value={mapping[i.toString()] || ''}
                        onChange={(e) => setMapping(prev => ({ ...prev, [i.toString()]: e.target.value }))}
                        style={{ width: '100%', padding: '0.5rem', borderRadius: '4px', border: '1px solid var(--border-subtle)', background: 'var(--color-bg-base)', color: 'var(--color-text-primary)', fontSize: '0.8rem' }}
                      >
                        <option value="">-- Ignore --</option>
                        <option value="fullName">Full Name (Req)</option>
                        <option value="studentNumber">Student Number (Req)</option>
                        <option value="email">Email</option>
                        <option value="registrationNumber">Reg Number</option>
                        <option value="groupName">Group Name</option>
                      </select>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {previewData.sampleRows.map((row: string[], rIdx: number) => (
                  <tr key={rIdx}>
                    {row.map((cell, cIdx) => (
                      <td key={cIdx} style={{ padding: '0.75rem 1rem', borderBottom: '1px solid var(--border-subtle)', borderRight: '1px solid var(--border-subtle)', color: 'var(--color-text-secondary)' }}>
                        {cell}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '2rem' }}>
            <button className="btn-secondary" onClick={() => setStep(1)}>ΓåÉ Back</button>
            <button className="btn-primary" onClick={() => setStep(3)}>Proceed to Review ΓåÆ</button>
          </div>
        </div>
      )}

      {/* STEP 3: REVIEW */}
      {step === 3 && (
        <div className="glass-panel" style={{ padding: '2rem' }}>
          <h3 style={{ fontSize: '1.25rem', marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>Review Extracted Data</h3>
          
          {previewData.structureType === 'SECTION_BASED' && (
             <div style={{ background: 'var(--color-primary-transparent)', color: 'var(--color-primary)', padding: '1rem', borderRadius: '8px', marginBottom: '2rem', fontSize: '0.875rem', display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
               <span style={{ fontSize: '1.5rem' }}>Γ£¿</span>
               <div>
                 <strong>AI Structure Detection Applied</strong><br/>
                 The system detected that your spreadsheet used section headers for groups rather than columns, and automatically restructured it.
               </div>
             </div>
          )}

          <div style={{ background: 'var(--color-bg-surface)', padding: '1rem', borderRadius: '8px', border: '1px solid var(--border-subtle)', marginBottom: '2rem' }}>
             We are ready to import. The backend will validate retaker status and required fields on the fly during execution.
          </div>

          {isExecuting ? (
            <div style={{ marginTop: '2rem', padding: '2rem', background: 'var(--color-bg-surface)', borderRadius: '12px', border: '1px solid var(--border-subtle)', textAlign: 'center' }}>
              <div style={{ marginBottom: '1rem', fontWeight: 600, color: 'var(--color-text-primary)' }}>
                Importing Roster... Please wait.
              </div>
              <div style={{ width: '100%', height: '8px', background: 'var(--border-subtle)', borderRadius: '4px', overflow: 'hidden' }}>
                <div style={{ 
                  height: '100%', 
                  width: `${importProgress}%`, 
                  background: 'var(--color-primary)', 
                  transition: 'width 0.2s ease-out' 
                }} />
              </div>
              <div style={{ marginTop: '0.75rem', fontSize: '0.875rem', color: 'var(--color-text-secondary)' }}>
                {Math.round(importProgress)}% Complete
              </div>
            </div>
          ) : (
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '2rem' }}>
              <button className="btn-secondary" onClick={() => setStep(previewData.structureType === 'SECTION_BASED' ? 1 : 2)}>ΓåÉ Back</button>
              <button className="btn-primary" onClick={handleExecute} disabled={isExecuting}>
                Simulate Import
              </button>
            </div>
          )}
        </div>
      )}

      {/* STEP 4: SIMULATION RESULTS */}
      {step === 4 && results && (
        <div className="glass-panel" style={{ padding: '3rem', textAlign: 'center' }}>
          <h3 style={{ fontSize: '1.5rem', marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>Simulation Complete</h3>
          <p style={{ color: 'var(--color-text-secondary)', marginBottom: '2rem' }}>Review the proposed changes below. No changes have been made to the database yet.</p>
          
          <div style={{ display: 'flex', justifyContent: 'center', gap: '2rem', marginBottom: '2rem' }}>
            <div style={{ padding: '1.5rem', background: 'var(--color-bg-surface)', borderRadius: '12px', minWidth: '120px', border: '1px solid var(--color-success)' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--color-success)' }}>{results.enrolled}</div>
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', marginTop: '0.5rem' }}>Will Enroll</div>
            </div>
            <div style={{ padding: '1.5rem', background: 'var(--color-bg-surface)', borderRadius: '12px', minWidth: '120px', border: '1px solid var(--color-info)' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--color-info)' }}>{results.updated}</div>
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', marginTop: '0.5rem' }}>Groups Will Update</div>
            </div>
            <div style={{ padding: '1.5rem', background: 'var(--color-bg-surface)', borderRadius: '12px', minWidth: '120px' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--color-text-muted)' }}>{results.unchanged}</div>
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', marginTop: '0.5rem' }}>Unchanged</div>
            </div>
            <div style={{ padding: '1.5rem', background: 'var(--color-bg-surface)', borderRadius: '12px', minWidth: '120px', border: results.errors > 0 ? '1px solid var(--color-danger)' : 'none' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--color-danger)' }}>{results.errors}</div>
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', marginTop: '0.5rem' }}>Errors</div>
            </div>
          </div>

          {results.details.length > 0 && (
            <div style={{ textAlign: 'left', marginTop: '2rem' }}>
              <h4 style={{ marginBottom: '1rem' }}>Simulation Log</h4>
              <div style={{ maxHeight: '300px', overflowY: 'auto', background: 'var(--color-bg-surface)', borderRadius: '8px', padding: '1rem', border: '1px solid var(--border-subtle)', fontSize: '0.875rem' }}>
                {results.details.map((d: any, i: number) => (
                  <div key={i} style={{ padding: '0.5rem 0', borderBottom: '1px solid var(--border-subtle)', display: 'flex', gap: '1rem' }}>
                    <span style={{ color: d.error ? 'var(--color-danger)' : 'var(--color-warning)' }}>{d.error ? 'Error' : 'Warning'}</span>
                    <span style={{ color: 'var(--color-text-secondary)' }}>{d.row.fullName || d.row.studentNumber || 'Unknown Row'}</span>
                    <span style={{ color: 'var(--color-text-primary)' }}>{d.error || d.warning}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {isExecuting ? (
            <div style={{ marginTop: '2rem', padding: '2rem', background: 'var(--color-bg-surface)', borderRadius: '12px', border: '1px solid var(--border-subtle)', textAlign: 'center' }}>
              <div style={{ marginBottom: '1rem', fontWeight: 600, color: 'var(--color-text-primary)' }}>
                Applying Changes... Please wait.
              </div>
              <div style={{ width: '100%', height: '8px', background: 'var(--border-subtle)', borderRadius: '4px', overflow: 'hidden' }}>
                <div style={{ 
                  height: '100%', 
                  width: `${importProgress}%`, 
                  background: 'var(--color-primary)', 
                  transition: 'width 0.2s ease-out' 
                }} />
              </div>
            </div>
          ) : (
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '3rem' }}>
              <button className="btn-secondary" onClick={() => setStep(3)}>ΓåÉ Discard & Go Back</button>
              <button className="btn-primary" onClick={handleApplyChanges} disabled={isExecuting}>
                Confirm & Apply Changes
              </button>
            </div>
          )}
        </div>
      )}

      {/* STEP 5: FINAL RESULTS */}
      {step === 5 && results && (
        <div className="glass-panel" style={{ padding: '3rem', textAlign: 'center' }}>
          <div style={{ fontSize: '4rem', marginBottom: '1rem' }}>≡ƒÄë</div>
          <h3 style={{ fontSize: '1.5rem', marginBottom: '1rem', color: 'var(--color-text-primary)' }}>Import Complete</h3>
          <p style={{ color: 'var(--color-text-secondary)', marginBottom: '2rem' }}>Changes have been successfully applied to the database.</p>
          
          <div style={{ display: 'flex', justifyContent: 'center', gap: '2rem', marginBottom: '2rem' }}>
            <div style={{ padding: '1.5rem', background: 'var(--color-bg-surface)', borderRadius: '12px', minWidth: '120px' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--color-success)' }}>{results.enrolled}</div>
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', marginTop: '0.5rem' }}>Enrolled</div>
            </div>
            <div style={{ padding: '1.5rem', background: 'var(--color-bg-surface)', borderRadius: '12px', minWidth: '120px' }}>
              <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--color-info)' }}>{results.updated}</div>
              <div style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)', marginTop: '0.5rem' }}>Groups Updated</div>
            </div>
          </div>

          <div style={{ marginTop: '3rem' }}>
            <Link href="/roster" className="btn-primary" style={{ textDecoration: 'none' }}>
              Return to Roster
            </Link>
          </div>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { cookies, headers } from 'next/headers';
import { db } from '@talora/database';


import RosterClient from './RosterClient';
import type { UserScope } from '@talora/auth';

const extractYY = (identifier: string | null) => {
  if (!identifier) return null;
  const match = identifier.match(/^(\d{2})/);
  return match ? parseInt(match[1]) : null;
};

export default async function RosterPage() {
  const scopeHeader = headers().get('x-user-scope');
  let students: any[] = [];
  let offeringName = 'No Offering Selected';
  let canEdit = false;
  let offering: any = null;

  if (scopeHeader) {
    try {
      const scope = JSON.parse(scopeHeader);
      canEdit = scope.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
      
      const activeOfferingId = cookies().get('active_offering_id')?.value;
      if (activeOfferingId) {
        offering = await db.courseOffering.findUnique({
          where: { id: activeOfferingId },
          include: { unit: true, term: true, class: true },
        });
      }
      
      if (!offering) {
        const firstEnrollment = await db.enrollment.findFirst({
          where: { studentId: scope.userId },
          include: { offering: { include: { unit: true, term: true, class: true } } },
        });
        if (firstEnrollment) {
          offering = firstEnrollment.offering;
        } else {
          // If not enrolled but they are a Class Rep, find an offering for their class
          const repRole = scope.roles.find((r: any) => r.role === 'CLASS_REPRESENTATIVE');
          if (repRole?.classId) {
            offering = await db.courseOffering.findFirst({
              where: { classId: repRole.classId },
              include: { unit: true, term: true, class: true },
            });
          }
        }
      }

      if (offering) {
        offeringName = `${offering.term.name} ┬╖ ${offering.unit.title} ┬╖ ${offering.class.name}`;
        
        // Find Class Representative to establish baseline YY
        const classRepRole = await db.userRole.findFirst({
          where: { role: 'CLASS_REPRESENTATIVE', classId: offering.class.id },
          include: { user: true }
        });
        
        const repYY = classRepRole ? extractYY(classRepRole.user.registrationNumber || classRepRole.user.studentNumber) : null;

        const rosterUsers = await db.user.findMany({
          where: {
            OR: [
              { enrollments: { some: { offeringId: offering.id } } },
              { memberships: { some: { offeringId: offering.id } } }
            ]
          },
          include: {
            memberships: {
              where: { offeringId: offering.id },
              include: { group: true }
            }
          },
          orderBy: { fullName: 'asc' }
        });

        students = rosterUsers.map(user => {
          const studentYY = extractYY(user.registrationNumber || user.studentNumber);
          const isRetaker = (repYY && studentYY && studentYY < repYY && !user.tookGapYear) ? true : false;

          return {
            id: user.studentNumber || user.id,
            userId: user.id,
            name: user.fullName,
            email: user.email,
            phoneNumber: user.phoneNumber,
            group: user.memberships[0]?.group?.name || 'Unassigned',
            isRetaker,
            tookGapYear: user.tookGapYear
          };
        });
      }
    } catch (e) {
      console.error(e);
    }
  }


  const retakerCount = students.filter(s => s.isRetaker).length;
  const unassignedCount = students.filter(s => s.group === 'Unassigned').length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', minHeight: '100%' }}>

      {/* ΓöÇΓöÇ Masthead ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', flexWrap: 'wrap', gap: '0.75rem', paddingBottom: '1.25rem', borderBottom: '1px solid var(--border-rule)' }}>
        <div>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.16em', textTransform: 'uppercase', color: 'var(--color-text-muted)', marginBottom: '0.375rem' }}>
            Class Roster
          </div>
          <h1 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: 'clamp(1.5rem, 3vw, 2rem)', fontWeight: 800, letterSpacing: '-0.03em', color: 'var(--color-text-primary)', lineHeight: 1.1, margin: 0 }}>
            {offeringName}
          </h1>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem', flexWrap: 'wrap' }}>
          {/* Stat chips */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', color: 'var(--color-text-muted)', paddingRight: '0.5rem', borderRight: '1px solid var(--border-subtle)' }}>
              <strong style={{ color: 'var(--color-text-primary)', fontFamily: 'var(--font-display)', fontSize: '1rem', fontWeight: 800 }}>{students.length}</strong> enrolled
            </span>
            {retakerCount > 0 && (
              <span className="badge badge-warning">{retakerCount} retakers</span>
            )}
            {unassignedCount > 0 && (
              <span className="badge badge-danger">{unassignedCount} unassigned</span>
            )}
          </div>

          {offering && (
            <a href={`/api/v1/offerings/${offering.id}/export`} className="btn-secondary" style={{ textDecoration: 'none', fontSize: '0.8125rem', padding: '0.4rem 0.875rem' }} download>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
              Export
            </a>
          )}
          {canEdit && (
            <a href="/roster/import" className="btn-primary" style={{ textDecoration: 'none', fontSize: '0.8125rem', padding: '0.4rem 0.875rem' }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
              Import
            </a>
          )}
        </div>
      </div>

      {/* ΓöÇΓöÇ Roster table card ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="ledger-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <RosterClient students={students} canEdit={canEdit} offeringId={offering?.id} />
      </div>
    </div>
  );
}

