'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import * as Dialog from '@radix-ui/react-dialog';

export default function EditContactModal({ 
  unit, 
  onClose 
}: { 
  unit: any, 
  onClose: () => void 
}) {
  const router = useRouter();
  const [title, setTitle] = useState(unit.title || '');
  const [lecturerName, setLecturerName] = useState(unit.lecturerName || '');
  const [lecturerEmail, setLecturerEmail] = useState(unit.lecturerEmail || '');
  const [lecturerPhone, setLecturerPhone] = useState(unit.lecturerPhone || '');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/v1/course-units/${unit.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          title, 
          lecturerName, 
          lecturerEmail, 
          lecturerPhone 
        })
      });

      const data = await res.json();
      
      if (!res.ok) {
        throw new Error(data.message || data.error || 'Failed to update course contact');
      }

      router.refresh();
      onClose();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog.Root open={true} onOpenChange={(open) => !open && onClose()}>
      <Dialog.Portal>
        <Dialog.Overlay className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <Dialog.Content className="fixed left-[50%] top-[50%] z-50 grid w-full max-w-md translate-x-[-50%] translate-y-[-50%] gap-4 border border-border-subtle bg-bg-surface p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-xl">
          <div className="flex justify-between items-center mb-2">
            <Dialog.Title className="text-xl font-display font-semibold text-text-primary">Edit Course Information</Dialog.Title>
            <Dialog.Close asChild>
              <button className="btn-ghost p-1.5 text-text-muted hover:text-text-primary rounded-full">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </Dialog.Close>
          </div>

          {error && (
            <div className="p-3 bg-danger/10 text-danger rounded-lg text-sm border border-danger/20">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            
            <div>
              <label className="label">Course Title</label>
              <input 
                type="text" 
                className="input w-full" 
                value={title} 
                onChange={(e) => setTitle(e.target.value)}
                required 
              />
            </div>

            <div>
              <label className="label">Lecturer Name (Optional)</label>
              <input 
                type="text" 
                className="input w-full" 
                value={lecturerName} 
                onChange={(e) => setLecturerName(e.target.value)}
              />
            </div>
            
            <div>
              <label className="label">Lecturer Email (Optional)</label>
              <input 
                type="email" 
                className="input w-full" 
                value={lecturerEmail} 
                onChange={(e) => setLecturerEmail(e.target.value)}
              />
            </div>

            <div>
              <label className="label">Lecturer Phone (Optional)</label>
              <input 
                type="text" 
                className="input w-full" 
                value={lecturerPhone} 
                onChange={(e) => setLecturerPhone(e.target.value)}
              />
            </div>

            <div className="flex justify-end gap-3 mt-4">
              <Dialog.Close asChild>
                <button type="button" className="btn-secondary" disabled={loading}>Cancel</button>
              </Dialog.Close>
              <button type="submit" className="btn-primary" disabled={loading}>
                {loading ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </form>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';

export default function TimetableGrid({ events, canEdit = false, courseUnits = [] }: any) {
  const router = useRouter();
  const [showModal, setShowModal] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [formData, setFormData] = useState({
    offeringId: courseUnits[0]?.offeringId || '', 
    title: '',
    location: '',
    dayOfWeek: 1,
    startTime: '08:00',
    endTime: '10:00'
  });

  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'];
  const hours = Array.from({ length: 10 }, (_, i) => i + 8);

  // Parse time "HH:MM"
  const parseTime = (timeStr: string) => {
    const [h, m] = timeStr.split(':').map(Number);
    return h + (m / 60);
  };

  const courseColors = [
    { bg: 'var(--color-primary-transparent)', border: 'var(--color-primary)' },
    { bg: 'var(--color-success-bg)', border: 'var(--color-success)' },
    { bg: 'var(--color-warning-bg)', border: 'var(--color-warning)' },
    { bg: 'var(--color-danger-bg)', border: 'var(--color-danger)' },
    { bg: 'rgba(232, 121, 249, 0.1)', border: 'var(--color-accent-violet)' },
    { bg: 'rgba(45, 212, 191, 0.1)', border: 'var(--color-accent-teal)' }
  ];

  const getEventColors = (offeringId: string) => {
    let hash = 0;
    for (let i = 0; i < offeringId.length; i++) {
      hash = offeringId.charCodeAt(i) + ((hash << 5) - hash);
    }
    return courseColors[Math.abs(hash) % courseColors.length];
  };

  const getEventStyle = (event: any) => {
    const startHour = parseTime(event.startTime);
    const endHour = parseTime(event.endTime);
    const duration = endHour - startHour;
    const topOffset = (startHour - 8) * 80;
    const height = duration * 80;
    
    return {
      position: 'absolute' as const,
      top: `${topOffset}px`,
      height: `${height}px`,
      left: '4px',
      right: '4px',
    };
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this event?')) return;
    try {
      await fetch(`/api/v1/timetable-events/${id}`, { method: 'DELETE' });
      router.refresh();
    } catch (e) {
      console.error(e);
    }
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const res = await fetch('/api/v1/timetable-events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });
      if (!res.ok) throw new Error('Failed to create event');
      setShowModal(false);
      router.refresh();
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Get current time line position
  const now = new Date();
  const currentDayIndex = now.getDay() - 1; // 0 = Monday
  const currentHourFloat = now.getHours() + now.getMinutes() / 60;
  const showCurrentTime = currentDayIndex >= 0 && currentDayIndex < 5 && currentHourFloat >= 8 && currentHourFloat <= 18;
  const currentTimeTop = (currentHourFloat - 8) * 80;

  const agendaDays = days.map((day, i) => {
    const dayEvents = events.filter((e: any) => e.dayOfWeek === i + 1).sort((a: any, b: any) => parseTime(a.startTime) - parseTime(b.startTime));
    return { day, events: dayEvents, isToday: currentDayIndex === i };
  }).filter(d => d.events.length > 0 || d.isToday);

  return (
    <div className="relative">
      {canEdit && (
        <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '1.25rem' }}>
          <button className="btn-primary" onClick={() => setShowModal(true)}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            Add Event
          </button>
        </div>
      )}

      {/* --- MOBILE VIEW (LIST) --- */}
      <div className="mobile-timetable-list" style={{ flexDirection: 'column', gap: '1.5rem' }}>
        {agendaDays.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '3rem', color: 'var(--color-text-muted)', fontStyle: 'italic', fontFamily: 'var(--font-display)', fontSize: '1.125rem', border: '1px solid var(--border-rule)', borderRadius: 'var(--radius-md)' }}>
            No events scheduled.
          </div>
        ) : (
          agendaDays.map(({ day, events: dayEvents, isToday }) => (
            <div key={day} style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                <h3 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.375rem', fontWeight: 700, color: isToday ? 'var(--color-primary)' : 'var(--color-text-primary)', margin: 0, letterSpacing: '-0.02em' }}>
                  {day}
                </h3>
                {isToday && <span className="stamp stamp-danger" style={{ padding: '0.125rem 0.375rem' }}>Today</span>}
                <div style={{ flex: 1, height: '1px', background: 'var(--border-rule)' }} />
              </div>
              
              {dayEvents.length === 0 ? (
                <div style={{ fontSize: '0.875rem', color: 'var(--color-text-muted)', fontStyle: 'italic', paddingLeft: '0.5rem' }}>No events</div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                  {dayEvents.map((event: any) => {
                    const colors = getEventColors(event.offeringId);
                    return (
                      <div key={event.id} style={{ position: 'relative', overflow: 'hidden', borderRadius: 'var(--radius-md)', padding: '1rem', background: 'var(--color-bg-surface)', border: '1px solid var(--border-subtle)', borderLeft: `4px solid ${colors.border}` }}>
                        <div style={{ position: 'absolute', inset: 0, opacity: 0.05, background: colors.border }} />
                        <div style={{ position: 'relative', zIndex: 10, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                          <div>
                            <div style={{ fontFamily: 'var(--font-display)', fontSize: '1.125rem', fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: '0.375rem', lineHeight: 1.2 }}>{event.title}</div>
                            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', color: 'var(--color-text-secondary)', display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.25rem' }}>
                              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                              {event.startTime} - {event.endTime}
                            </div>
                            <div style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                              {event.location}
                            </div>
                          </div>
                          {canEdit && (
                            <button 
                              onClick={() => handleDelete(event.id)}
                              style={{ background: 'none', border: 'none', padding: '0.375rem', color: 'var(--color-danger)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                            >
                              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          ))
        )}
      </div>

      {/* --- DESKTOP VIEW (GRID) --- */}
      <div className="desktop-timetable-grid table-responsive-wrapper">
        <div style={{ display: 'grid', gridTemplateColumns: '60px repeat(5, 1fr)', gap: '1px', background: 'var(--border-rule)', border: '1px solid var(--border-rule)', overflow: 'hidden', minWidth: '700px' }}>
          <div style={{ background: 'var(--color-bg-base)', padding: '1rem', textAlign: 'center', fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', textTransform: 'uppercase', letterSpacing: '0.1em', color: 'var(--color-text-muted)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Time</div>
          {days.map((day, i) => (
            <div key={day} style={{ background: 'var(--color-bg-base)', padding: '1rem', textAlign: 'center', fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.125rem', fontWeight: 600, color: i === currentDayIndex ? 'var(--color-primary)' : 'var(--color-text-primary)' }}>
              {day}
            </div>
          ))}

          <div style={{ display: 'contents' }}>
            <div style={{ background: 'var(--color-bg-base)' }}>
              {hours.map(hour => (
                <div key={hour} style={{ height: '80px', borderTop: '1px solid var(--border-rule)', display: 'flex', alignItems: 'flex-start', justifyContent: 'center', paddingTop: '0.5rem', fontFamily: 'var(--font-mono)', fontSize: '0.6875rem', color: 'var(--color-text-muted)' }}>
                  {hour.toString().padStart(2, '0')}:00
                </div>
              ))}
            </div>

            {days.map((_, dayIndex) => (
              <div key={dayIndex} style={{ background: 'var(--color-bg-surface)', position: 'relative' }}>
                {hours.map(hour => (
                  <div key={hour} style={{ height: '80px', borderTop: '1px solid var(--border-rule)' }} />
                ))}

                {/* Current Time Line */}
                {showCurrentTime && dayIndex === currentDayIndex && (
                  <div style={{ position: 'absolute', top: `${currentTimeTop}px`, left: 0, right: 0, height: '1px', background: 'var(--color-danger)', zIndex: 20 }}>
                    <div style={{ position: 'absolute', left: '-4px', top: '-4px', width: '9px', height: '9px', borderRadius: '50%', background: 'var(--color-danger)', boxShadow: '0 0 0 2px var(--color-bg-surface)' }} />
                  </div>
                )}

                {events.filter((e: any) => e.dayOfWeek === dayIndex + 1).map((event: any) => {
                  const colors = getEventColors(event.offeringId);
                  return (
                    <div 
                      key={event.id} 
                      style={{
                        ...getEventStyle(event),
                        background: colors.bg,
                        border: `1px solid ${colors.border}`,
                        borderLeft: `3px solid ${colors.border}`,
                        padding: '0.5rem 0.625rem',
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '0.25rem',
                        overflow: 'hidden',
                        zIndex: 10
                      }}
                    >
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <div style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1rem', fontWeight: 600, color: 'var(--color-text-primary)', lineHeight: 1.1, letterSpacing: '-0.01em' }}>
                          {event.title}
                        </div>
                        {canEdit && (
                          <button 
                            onClick={() => handleDelete(event.id)}
                            style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-muted)', padding: '2px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                            title="Delete event"
                          >
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                          </button>
                        )}
                      </div>
                      <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', color: 'var(--color-text-secondary)', display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                        <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                        {event.location}
                      </div>
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Add Event Modal */}
      {showModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(10, 10, 10, 0.4)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 100, padding: '1rem' }}>
          <div className="ledger-panel" style={{ width: '100%', maxWidth: '440px', padding: '2rem', display: 'flex', flexDirection: 'column', gap: '1.5rem', background: 'var(--color-bg-base)' }}>
            
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
              <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: 'var(--color-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', flexShrink: 0 }}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
              </div>
              <div>
                <h2 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: '1.375rem', fontWeight: 700, margin: 0, color: 'var(--color-text-primary)', letterSpacing: '-0.02em' }}>Add Event</h2>
                <div style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary)' }}>Schedule a new lecture or lab session</div>
              </div>
            </div>
            
            {error && <div style={{ padding: '0.75rem', background: 'var(--color-danger-bg)', color: 'var(--color-danger)', fontSize: '0.875rem', borderRadius: 'var(--radius-sm)', border: '1px solid rgba(239, 68, 68, 0.2)' }}>{error}</div>}

            <form onSubmit={handleAdd} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
              <div>
                <label className="label">Course Unit</label>
                <select className="input-line" value={formData.offeringId} onChange={(e: any) => setFormData({...formData, offeringId: e.target.value, title: e.target.options[e.target.selectedIndex].text})} required>
                  <option value="">Select a course...</option>
                  {courseUnits.map((cu: any) => (
                    <option key={cu.id} value={cu.offeringId}>{cu.code} - {cu.title}</option>
                  ))}
                </select>
              </div>

              <div style={{ display: 'flex', gap: '1.25rem' }}>
                <div style={{ flex: 1 }}>
                  <label className="label">Day of Week</label>
                  <select className="input-line" value={formData.dayOfWeek} onChange={(e: any) => setFormData({...formData, dayOfWeek: Number(e.target.value)})} required>
                    {days.map((d: any, i: any) => <option key={i+1} value={i+1}>{d}</option>)}
                  </select>
                </div>
                <div style={{ flex: 1 }}>
                  <label className="label">Location</label>
                  <input type="text" className="input-line" value={formData.location} onChange={(e: any) => setFormData({...formData, location: e.target.value})} placeholder="e.g. Room 101" required />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '1.25rem' }}>
                <div style={{ flex: 1 }}>
                  <label className="label">Start Time</label>
                  <input type="time" className="input-line" value={formData.startTime} onChange={(e: any) => setFormData({...formData, startTime: e.target.value})} required />
                </div>
                <div style={{ flex: 1 }}>
                  <label className="label">End Time</label>
                  <input type="time" className="input-line" value={formData.endTime} onChange={(e: any) => setFormData({...formData, endTime: e.target.value})} required />
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '1rem' }}>
                <button type="button" onClick={() => setShowModal(false)} className="btn-secondary">Cancel</button>
                <button type="submit" className="btn-primary" disabled={loading}>
                  {loading ? 'Adding...' : 'Add Event'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { headers, cookies } from 'next/headers';
import { db } from '@talora/database';
import TimetableGrid from './TimetableGrid';
import CourseContactsClient from './CourseContactsClient';
import PrintButton from './PrintButton';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';

export default async function TimetablePage() {
  const scopeHeader = headers().get('x-user-scope');
  let events: any[] = [];
  let courseUnits: any[] = [];
  let offeringName = 'No Offering Selected';
  let canEdit = false;

  if (scopeHeader) {
    try {
      const scope = JSON.parse(scopeHeader) as UserScope;
      canEdit = scope.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');

      
      let offering;
      const activeOfferingId = cookies().get('active_offering_id')?.value;
      if (activeOfferingId) {
        offering = await db.courseOffering.findUnique({
          where: { id: activeOfferingId },
          include: { unit: true, term: true, class: true },
        });
      }
      
      if (!offering) {
        offering = await db.courseOffering.findFirst({
          include: { unit: true, term: true, class: true },
        });
      }

      if (offering) {
        offeringName = `${offering.term.name} ┬╖ ${offering.class.name} Timetable`;
        
        // Fetch course units for this class
        const offeringsForClass = await db.courseOffering.findMany({
          where: { classId: offering.classId, termId: offering.termId },
          include: { unit: true }
        });
        
        courseUnits = offeringsForClass.map(o => ({
          ...o.unit,
          offeringId: o.id
        }));

        const dbEvents = await db.timetableEvent.findMany({
          where: { offeringId: { in: offeringsForClass.map(o => o.id) } }
        });
        events = dbEvents;
      }
    } catch (e: any) {
      offeringName = 'Error: ' + e.message;
      console.error(e);
    }
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', minHeight: '100%' }}>

      {/* ΓöÇΓöÇ Masthead ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', flexWrap: 'wrap', gap: '0.75rem', paddingBottom: '1.25rem', borderBottom: '1px solid var(--border-rule)' }}>
        <div>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.6rem', letterSpacing: '0.16em', textTransform: 'uppercase', color: 'var(--color-text-muted)', marginBottom: '0.375rem' }}>
            Class Schedule
          </div>
          <h1 style={{ fontFamily: 'var(--font-display)', fontStyle: 'italic', fontSize: 'clamp(1.5rem, 3vw, 2rem)', fontWeight: 800, letterSpacing: '-0.03em', color: 'var(--color-text-primary)', lineHeight: 1.1, margin: 0 }}>
            {offeringName}
          </h1>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.625rem', flexWrap: 'wrap' }}>
          <PrintButton />
        </div>
      </div>

      {/* ΓöÇΓöÇ Grid ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="ledger-panel" style={{ flex: 1, padding: '1.5rem', display: 'flex', flexDirection: 'column' }}>
        <TimetableGrid 
          events={events} 
          canEdit={canEdit} 
          courseUnits={courseUnits} 
        />
      </div>

      <CourseContactsClient 
        courseUnits={courseUnits} 
        canEdit={canEdit} 
      />
    </div>
  );
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import { cookies } from 'next/headers';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';

export async function POST(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    const { offeringId } = await request.json();

    if (!offeringId) {
      return NextResponse.json({ error: 'offeringId is required' }, { status: 400 });
    }

    // Verify the offering exists
    const offering = await db.courseOffering.findUnique({ where: { id: offeringId } });
    if (!offering) {
      return NextResponse.json({ error: 'Offering not found' }, { status: 404 });
    }

    const isPlatformAdmin = scope.roles.some((r: any) => r.role === 'PLATFORM_ADMIN');
    const repClassIds = scope.roles
      .filter((r: any) => r.role === 'CLASS_REPRESENTATIVE' && r.classId)
      .map((r: any) => r.classId);
    const isRep = repClassIds.length > 0;

    // Platform admins can switch to any offering
    if (!isPlatformAdmin) {
      if (isRep) {
        // Reps can only switch to offerings belonging to their assigned class
        if (!repClassIds.includes(offering.classId)) {
          return NextResponse.json(
            { error: 'You are not authorized to access this offering' },
            { status: 403 }
          );
        }
      } else {
        // Students can only activate an offering they are enrolled in
        const enrollment = await db.enrollment.findFirst({
          where: { studentId: scope.userId, offeringId },
        });
        if (!enrollment) {
          return NextResponse.json(
            { error: 'You are not enrolled in this offering' },
            { status: 403 }
          );
        }
      }
    }

    cookies().set('active_offering_id', offeringId, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 60 * 60 * 24 * 30, // 30 days
      path: '/',
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('Error setting active offering:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';

export const dynamic = 'force-dynamic';


export async function PATCH(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    const scope = JSON.parse(scopeHeader);
    const isRep = scope.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    if (!isRep) return NextResponse.json({ error: 'Forbidden' }, { status: 403 });

    const body = await req.json();
    const { title, content } = body;

    const announcement = await db.announcement.update({
      where: { id: params.id },
      data: { title, content }
    });

    return NextResponse.json({ data: announcement });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    const scope = JSON.parse(scopeHeader);
    const isRep = scope.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    if (!isRep) return NextResponse.json({ error: 'Forbidden' }, { status: 403 });

    await db.$transaction([
      db.notification.deleteMany({
        where: {
          referenceId: params.id,
          referenceType: 'ANNOUNCEMENT'
        }
      }),
      db.announcement.delete({
        where: { id: params.id }
      })
    ]);

    return NextResponse.json({ success: true });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';

export async function PATCH(request: Request, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;

    // Only reps or admins can edit assignments
    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    if (!isRep) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Not authorized to edit assignments' }, { status: 403 });
    }

    const assignmentId = params.id;
    const body = await request.json();
    const { title, description, dueDate, type } = body;

    const existingAssignment = await db.assignment.findUnique({
      where: { id: assignmentId }
    });

    if (!existingAssignment) {
      return NextResponse.json({ code: 'NOT_FOUND', message: 'Assignment not found' }, { status: 404 });
    }

    const updatedAssignment = await db.assignment.update({
      where: { id: assignmentId },
      data: {
        title: title !== undefined ? title : undefined,
        description: description !== undefined ? description : undefined,
        dueDate: dueDate ? new Date(dueDate) : undefined,
        type: type !== undefined ? type : undefined,
      }
    });

    return NextResponse.json({ data: updatedAssignment }, { status: 200 });
  } catch (error: any) {
    console.error('Error updating assignment:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR', message: error.message }, { status: 500 });
  }
}

export async function DELETE(request: Request, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;

    // Only reps or admins can delete assignments
    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    if (!isRep) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Not authorized to delete assignments' }, { status: 403 });
    }

    const assignmentId = params.id;

    const existingAssignment = await db.assignment.findUnique({
      where: { id: assignmentId }
    });

    if (!existingAssignment) {
      return NextResponse.json({ code: 'NOT_FOUND', message: 'Assignment not found' }, { status: 404 });
    }

    await db.assignment.delete({
      where: { id: assignmentId }
    });

    return NextResponse.json({ success: true }, { status: 200 });
  } catch (error: any) {
    console.error('Error deleting assignment:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR', message: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';

export const dynamic = 'force-dynamic';



export async function POST(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    const scope = JSON.parse(scopeHeader);

    // Verify user is a student in the offering that this assignment belongs to
    // For simplicity, we just assume they are if they have the assignment ID
    // A stricter check would fetch the assignment, get offeringId, and check enrollments
    const assignment = await db.assignment.findUnique({ where: { id: params.id } });
    if (!assignment) {
      return NextResponse.json({ error: 'Assignment not found' }, { status: 404 });
    }

    if (assignment.dueDate && new Date() > new Date(assignment.dueDate)) {
      return NextResponse.json({ error: 'Submissions are closed for this assignment.' }, { status: 403 });
    }

    const isStudent = scope.roles.some((r: any) => r.role === 'STUDENT' && r.offeringId === assignment.offeringId);
    if (!isStudent) {
      // Platform Admins/Reps might not need to submit, but if they do, we can allow it
      // For now, only restrict if no valid role
      const canSubmit = scope.roles.some((r: any) => r.role === 'STUDENT' || r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
      if (!canSubmit) return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const body = await req.json();
    const { fileUrl } = body;

    if (!fileUrl) {
      return NextResponse.json({ error: 'Submission URL is required' }, { status: 400 });
    }

    // Check for existing submission
    const existingSubmission = await db.submission.findFirst({
      where: {
        assignmentId: params.id,
        studentId: scope.userId
      }
    });

    if (existingSubmission) {
      // Update existing
      const updated = await db.submission.update({
        where: { id: existingSubmission.id },
        data: { fileUrl, submittedAt: new Date() }
      });
      return NextResponse.json({ data: updated });
    }

    // Create new submission
    const submission = await db.submission.create({
      data: {
        assignmentId: params.id,
        studentId: scope.userId,
        fileUrl
      }
    });

    return NextResponse.json({ data: submission }, { status: 201 });
  } catch (err: any) {
    console.error('Submission error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import { verifyPassword, hashPassword } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function PUT(req: NextRequest) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    
    const scope = JSON.parse(scopeHeader);
    const userId = scope.userId;

    const body = await req.json();
    const { currentPassword, newPassword } = body;

    if (!currentPassword || !newPassword) {
      return NextResponse.json({ error: 'Current password and new password are required' }, { status: 400 });
    }

    if (newPassword.length < 8) {
      return NextResponse.json({ error: 'New password must be at least 8 characters long' }, { status: 400 });
    }

    // Fetch the user from the database
    const user = await db.user.findUnique({
      where: { id: userId }
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    // Verify current password
    const isPasswordValid = await verifyPassword(currentPassword, user.passwordHash);
    
    if (!isPasswordValid) {
      return NextResponse.json({ error: 'Incorrect current password' }, { status: 400 });
    }

    // Hash the new password and update
    const newPasswordHash = await hashPassword(newPassword);

    await db.user.update({
      where: { id: userId },
      data: { passwordHash: newPasswordHash }
    });

    return NextResponse.json({ message: 'Password updated successfully' });
  } catch (err: any) {
    console.error('Password change error:', err);
    return NextResponse.json({ error: 'An unexpected error occurred' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import { hashPassword } from '@talora/auth';
import { sendEmail } from '@/lib/email';
import { rateLimit } from '@/lib/rateLimit';
import { verifyFirebaseToken } from '@/lib/firebase-admin';

export const dynamic = 'force-dynamic';


export async function POST(req: NextRequest) {
  try {
    const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1';
    const { success } = rateLimit(ip, 3, 60 * 1000); // 3 requests per minute
    
    if (!success) {
      return NextResponse.json(
        { error: 'Too many requests. Try again later.' },
        { status: 429 }
      );
    }

    const body = await req.json();
    let { fullName, email, studentNumber, registrationNumber, phoneNumber, password } = body;

    if (!fullName || !email || !studentNumber || !registrationNumber || !phoneNumber || !password) {
      return NextResponse.json({ error: 'All fields are required.' }, { status: 400 });
    }



    studentNumber = studentNumber.replace(/\s+/g, '');
    registrationNumber = registrationNumber.replace(/\s+/g, '').toUpperCase();
    email = email.trim();

    if (password.length < 8) {
      return NextResponse.json({ error: 'Password must be at least 8 characters long.' }, { status: 400 });
    }

    // Email domain restriction removed to allow any email

    const studentNumberRegex = /^[1-2][0-9]007\d{5}$/;
    if (!studentNumberRegex.test(studentNumber)) {
      return NextResponse.json({ error: 'Invalid Student Number format. It should look like 2400712345 or 1900712345.' }, { status: 400 });
    }

    const regNumberRegex = /^[1-2][0-9]\/[UXIE]\/\d{4,5}(?:\/(?:EVE|PS|PSA))?$/;
    if (!regNumberRegex.test(registrationNumber)) {
      return NextResponse.json({ error: 'Invalid Registration Number format. It should look like 24/U/12345 or 19/U/0349.' }, { status: 400 });
    }

    const snYear = studentNumber.substring(0, 2);
    const rnYear = registrationNumber.substring(0, 2);
    if (snYear !== rnYear) {
      return NextResponse.json({ error: 'The admission year in your Student Number and Registration Number must match.' }, { status: 400 });
    }

    const existingUser = await db.user.findUnique({ where: { email } });
    if (existingUser) {
      return NextResponse.json({ error: 'An account with this email already exists. Please log in.' }, { status: 400 });
    }

    // Get default institution
    const institution = await db.institution.findFirst();
    if (!institution) {
      return NextResponse.json({ error: 'Platform configuration error: No institution found.' }, { status: 500 });
    }

    const { firebaseIdToken } = body;
    if (!firebaseIdToken) {
      return NextResponse.json({ error: 'Phone verification is required. Please verify your phone number first.' }, { status: 400 });
    }

    // Verify Firebase token
    let decodedToken;
    try {
      decodedToken = await verifyFirebaseToken(firebaseIdToken);
    } catch (error) {
      return NextResponse.json({ error: 'Invalid or expired phone verification token.' }, { status: 401 });
    }

    // Optional: check if phone number matches
    // Note: Firebase numbers are in E.164 format (e.g. +256701234567)
    if (decodedToken.phone_number !== phoneNumber) {
      return NextResponse.json({ error: 'The verified phone number does not match the provided phone number.' }, { status: 400 });
    }

    const hashedPassword = await hashPassword(password);

    const newUser = await db.user.create({
      data: {
        fullName,
        email,
        studentNumber,
        registrationNumber,
        phoneNumber,
        acceptedTerms: true,
        passwordHash: hashedPassword,
        institutionId: institution.id,
        isEmailVerified: true, // Auto-verify since they verified phone
      }
    });

    // Assign generic STUDENT role (without a specific class for now, they will enroll in offerings manually)
    await db.userRole.create({
      data: {
        userId: newUser.id,
        role: 'STUDENT'
      }
    });

    return NextResponse.json({ success: true, userId: newUser.id, requiresVerification: false }, { status: 201 });
  } catch (err: any) {
    console.error('Registration Error:', err);
    if (err.code === 'P2002') {
      return NextResponse.json({ error: 'This Student Number or Registration Number is already registered.' }, { status: 400 });
    }
    return NextResponse.json({ error: 'Internal server error during registration.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import { sendEmail } from '@/lib/email';
import { rateLimit } from '@/lib/rateLimit';

export const dynamic = 'force-dynamic';

export async function POST(req: NextRequest) {
  try {
    const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1';
    const { success } = rateLimit(ip, 3, 60 * 60 * 1000); // Max 3 resend requests per hour

    if (!success) {
      return NextResponse.json(
        { error: 'Too many requests. Please wait a while before requesting a new code.' },
        { status: 429 }
      );
    }

    const body = await req.json();
    const { email } = body;

    if (!email) {
      return NextResponse.json({ error: 'Email is required.' }, { status: 400 });
    }

    const user = await db.user.findUnique({ where: { email } });

    if (!user) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    if (user.isEmailVerified) {
      return NextResponse.json({ error: 'Email is already verified. Please log in.' }, { status: 400 });
    }

    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes

    await db.user.update({
      where: { id: user.id },
      data: {
        verificationToken: otp,
        verificationTokenExpires: expiresAt,
      }
    });

    // Send the OTP via email
    const emailResult = await sendEmail({
      to: user.email,
      subject: 'Verify your Talora account',
      html: `
        <div style="font-family: Arial, sans-serif; padding: 20px;">
          <h2>Talora Verification Code</h2>
          <p>Hi ${user.fullName},</p>
          <p>Here is your new 6-digit code to verify your email address:</p>
          <h1 style="color: #4F46E5; letter-spacing: 2px;">${otp}</h1>
          <p>This code will expire in 15 minutes.</p>
          <p>If you didn't request this, please ignore this email.</p>
        </div>
      `
    });

    if (!emailResult.success) {
      return NextResponse.json({ error: 'Failed to resend verification email. Please check your email configuration or try again.' }, { status: 500 });
    }

    return NextResponse.json({ success: true, message: 'A new verification code has been sent.' }, { status: 200 });
  } catch (err: any) {
    console.error('Resend Verification Error:', err);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import { hashPassword } from '@talora/auth';
import { rateLimit } from '@/lib/rateLimit';

export const dynamic = 'force-dynamic';


export async function POST(req: NextRequest) {
  try {
    const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1';
    const { success } = rateLimit(ip, 5, 60 * 1000); // 5 requests per minute

    if (!success) {
      return NextResponse.json(
        { error: 'Too many requests. Try again later.' },
        { status: 429 }
      );
    }

    const body = await req.json();
    const { email, token, newPassword } = body;

    if (!email || !token || !newPassword) {
      return NextResponse.json({ error: 'Email, token, and new password are required.' }, { status: 400 });
    }

    if (newPassword.length < 8) {
      return NextResponse.json({ error: 'Password must be at least 8 characters long.' }, { status: 400 });
    }

    const user = await db.user.findUnique({ where: { email } });

    if (!user) {
      return NextResponse.json({ error: 'Invalid or expired token.' }, { status: 400 });
    }

    if (!user.resetToken || user.resetToken !== token) {
      return NextResponse.json({ error: 'Invalid or expired token.' }, { status: 400 });
    }

    if (!user.resetTokenExpires || user.resetTokenExpires < new Date()) {
      return NextResponse.json({ error: 'Token has expired. Please request a new password reset.' }, { status: 400 });
    }

    const hashedPassword = await hashPassword(newPassword);

    await db.user.update({
      where: { id: user.id },
      data: {
        passwordHash: hashedPassword,
        resetToken: null,
        resetTokenExpires: null
      }
    });

    return NextResponse.json({ success: true, message: 'Password reset successfully.' }, { status: 200 });
  } catch (err: any) {
    console.error('Reset Password Error:', err);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import { signJwt } from '@talora/auth';
import type { UserScope, Role } from '@talora/auth';
import { rateLimit } from '@/lib/rateLimit';
import { sendEmail } from '@/lib/email';

export const dynamic = 'force-dynamic';


export async function POST(req: NextRequest) {
  try {
    const ip = req.headers.get('x-forwarded-for') ?? '127.0.0.1';
    const { success } = rateLimit(ip, 5, 60 * 1000); // 5 requests per minute
    
    if (!success) {
      return NextResponse.json(
        { error: 'Too many requests. Try again later.' },
        { status: 429 }
      );
    }

    const body = await req.json();
    const { email, otp } = body;

    if (!email || !otp) {
      return NextResponse.json({ error: 'Email and verification code are required.' }, { status: 400 });
    }

    const user = await db.user.findUnique({
      where: { email },
      include: { roles: true }
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    if (user.isEmailVerified) {
      return NextResponse.json({ error: 'Email is already verified. Please log in.' }, { status: 400 });
    }

    if (user.verificationToken !== otp.trim()) {
      return NextResponse.json({ error: 'Invalid verification code.' }, { status: 400 });
    }

    if (user.verificationTokenExpires && user.verificationTokenExpires < new Date()) {
      return NextResponse.json({ error: 'Verification code has expired. Please request a new one.' }, { status: 400 });
    }

    // Mark as verified and clear token
    await db.user.update({
      where: { id: user.id },
      data: {
        isEmailVerified: true,
        verificationToken: null,
        verificationTokenExpires: null,
      }
    });

    // Generate JWT and log them in
    const payload: UserScope = {
      userId: user.id,
      roles: user.roles.map(r => ({
        role: r.role as Role,
        classId: r.classId || undefined,
      })),
    };

    const token = await signJwt(payload, '7d');

    // Send "Successfully Registered" Welcome Email asynchronously
    sendEmail({
      to: user.email,
      subject: 'Welcome to Talora!',
      html: `
        <div style="font-family: Arial, sans-serif; padding: 20px;">
          <h2>Registration Successful ≡ƒÄë</h2>
          <p>Hi ${user.fullName},</p>
          <p>Your email has been verified and your Talora account is fully active.</p>
          <p>You can now log in, enroll in course offerings, and join project groups.</p>
          <br/>
          <p>Best,<br/>The Talora Team</p>
        </div>
      `
    }).catch(err => console.error('Failed to send welcome email:', err));

    const response = NextResponse.json({
      success: true,
      message: 'Email verified successfully',
      user: { id: user.id, fullName: user.fullName }
    });

    response.cookies.set({
      name: 'talora_token',
      value: token,
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 60 * 60 * 24 * 7, // 7 days
    });

    return response;
  } catch (err: any) {
    console.error('Verification Error:', err);
    return NextResponse.json({ error: 'Internal server error during verification.' }, { status: 500 });
  }
}

