import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function PATCH(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    const body = await request.json();

    const changeRequest = await db.groupChangeRequest.findUnique({
      where: { id: params.id },
      include: {
        group: { include: { offering: true } }
      }
    });

    if (!changeRequest) return NextResponse.json({ code: 'NOT_FOUND', message: 'Request not found' }, { status: 404 });
    if (changeRequest.status !== 'PENDING') {
      return NextResponse.json({ code: 'CONFLICT', message: 'Request is already processed' }, { status: 409 });
    }

    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    let isLeader = changeRequest.group.leaderId === scope.userId;
    
    // For transfers, the target group leader must approve
    if (changeRequest.targetGroupId) {
      const targetGroup = await db.group.findUnique({ where: { id: changeRequest.targetGroupId } });
      if (targetGroup?.leaderId === scope.userId) {
        isLeader = true;
      } else {
        // Origin group leader cannot approve transfers, only the target can (and reps)
        isLeader = false;
      }
    }

    if (!isRep && !isLeader) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Only Class Reps or the Target Group Leader can process transfer requests' }, { status: 403 });
    }

    const { status } = body;
    if (!status || !['APPROVED', 'REJECTED'].includes(status)) {
      return NextResponse.json({ code: 'BAD_REQUEST', message: 'Invalid status' }, { status: 400 });
    }

    // Process transaction if approved
    if (status === 'APPROVED') {
      // Check if student has a current membership in this offering
      const existingMembership = await db.groupMembership.findUnique({
        where: {
          studentId_offeringId: {
            studentId: changeRequest.studentId,
            offeringId: changeRequest.group.offeringId
          }
        }
      });

      if (!existingMembership) {
        // This is a Join Request from an ungrouped student
        const otherRequests = await db.groupChangeRequest.findMany({
          where: {
            studentId: changeRequest.studentId,
            status: 'PENDING',
            id: { not: changeRequest.id },
            group: { offeringId: changeRequest.group.offeringId }
          }
        });

        const ops: any[] = [
          db.groupMembership.create({
            data: {
              groupId: changeRequest.groupId,
              studentId: changeRequest.studentId,
              offeringId: changeRequest.group.offeringId
            }
          }),
          db.groupChangeRequest.update({
            where: { id: changeRequest.id },
            data: { status: 'APPROVED' }
          })
        ];

        if (otherRequests.length > 0) {
          ops.push(
            db.groupChangeRequest.updateMany({
              where: { id: { in: otherRequests.map(r => r.id) } },
              data: { status: 'REJECTED' }
            })
          );
        }

        await db.$transaction(ops);
      } else {
        // This student is already in a group
        if (changeRequest.targetGroupId) {
          // Transfer request
          await db.$transaction([
            db.groupMembership.delete({
              where: {
                studentId_offeringId: {
                  studentId: changeRequest.studentId,
                  offeringId: changeRequest.group.offeringId
                }
              }
            }),
            db.groupMembership.create({
              data: {
                groupId: changeRequest.targetGroupId,
                studentId: changeRequest.studentId,
                offeringId: changeRequest.group.offeringId
              }
            }),
            db.groupChangeRequest.update({
              where: { id: changeRequest.id },
              data: { status: 'APPROVED' }
            })
          ]);
        } else {
          // Remove request
          await db.$transaction([
            db.groupMembership.delete({
              where: {
                studentId_offeringId: {
                  studentId: changeRequest.studentId,
                  offeringId: changeRequest.group.offeringId
                }
              }
            }),
            db.groupChangeRequest.update({
              where: { id: changeRequest.id },
              data: { status: 'APPROVED' }
            })
          ]);
        }
      }
    } else {
      // Reject
      await db.groupChangeRequest.update({
        where: { id: changeRequest.id },
        data: { status: 'REJECTED' }
      });
    }

    return NextResponse.json({ message: 'Request processed successfully' });
  } catch (error) {
    console.error('Error processing group change request:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function GET(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    
    // Determine context based on URL search params (e.g. ?offeringId=123)
    const url = new URL(request.url);
    const offeringId = url.searchParams.get('offeringId');

    if (!offeringId) {
      return NextResponse.json({ code: 'BAD_REQUEST', message: 'offeringId is required' }, { status: 400 });
    }

    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE');

    // A Rep sees all requests for the offering. A Student sees only their own requests.
    const whereClause: any = {
      group: { offeringId }
    };

    if (!isRep) {
      whereClause.studentId = scope.userId;
    }

    const requests = await db.groupChangeRequest.findMany({
      where: whereClause,
      include: {
        group: { select: { id: true, name: true, leaderId: true } },
      }
    });

    // Fetch target group names and student names manually to compose a nice response
    const targetGroupIds = requests.map(r => r.targetGroupId).filter(Boolean) as string[];
    const targetGroups = await db.group.findMany({ where: { id: { in: targetGroupIds } }, select: { id: true, name: true } });
    const targetGroupMap = new Map(targetGroups.map(g => [g.id, g.name]));

    const studentIds = requests.map(r => r.studentId);
    const students = await db.user.findMany({ where: { id: { in: studentIds } }, select: { id: true, fullName: true, studentNumber: true } });
    const studentMap = new Map(students.map(s => [s.id, s]));

    const mapped = requests.map(r => ({
      id: r.id,
      studentId: r.studentId,
      studentName: studentMap.get(r.studentId)?.fullName || 'Unknown',
      studentNumber: studentMap.get(r.studentId)?.studentNumber,
      fromGroupId: r.group.id,
      fromGroupName: r.group.name,
      targetGroupId: r.targetGroupId,
      targetGroupName: r.targetGroupId ? targetGroupMap.get(r.targetGroupId) : null,
      reason: r.reason,
      status: r.status,
      createdAt: r.createdAt
    }));

    return NextResponse.json({ data: mapped });
  } catch (error) {
    console.error('Error fetching group change requests:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    const body = await request.json();

    const { groupId, targetGroupId, reason } = body;
    if (!groupId || !reason) {
      return NextResponse.json({ code: 'BAD_REQUEST', message: 'groupId and reason are required' }, { status: 400 });
    }

    // Determine if it's a join or a transfer
    // If targetGroupId is provided, it's a transfer. The student MUST be in `groupId`.
    // If targetGroupId is not provided, it's a join request to `groupId`. The student MUST NOT be in `groupId` already.
    const group = await db.group.findUnique({ where: { id: groupId } });
    if (!group) return NextResponse.json({ code: 'NOT_FOUND', message: 'Group not found' }, { status: 404 });
    
    const existingMembership = await db.groupMembership.findFirst({
      where: {
        studentId: scope.userId,
        offeringId: group.offeringId
      }
    });

    if (targetGroupId) {
      if (!existingMembership || existingMembership.groupId !== groupId) {
        return NextResponse.json({ code: 'FORBIDDEN', message: 'You must be in the origin group to request a transfer' }, { status: 403 });
      }
    } else {
      if (existingMembership) {
        return NextResponse.json({ code: 'FORBIDDEN', message: 'You are already in a group. Use transfer instead.' }, { status: 403 });
      }
    }

    // We no longer prevent duplicate pending requests so a student can apply to multiple groups.

    const newRequest = await db.groupChangeRequest.create({
      data: {
        groupId,
        targetGroupId,
        studentId: scope.userId,
        reason,
        status: 'PENDING'
      }
    });

    return NextResponse.json({ data: newRequest }, { status: 201 });
  } catch (error) {
    console.error('Error creating group change request:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function POST(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    const studentId = scope.userId;
    const targetGroupId = params.id;

    // 1. Get the group
    const group = await db.group.findUnique({
      where: { id: targetGroupId },
      include: {
        _count: { select: { memberships: true } },
        offering: true
      }
    });

    if (!group) return NextResponse.json({ code: 'NOT_FOUND', message: 'Group not found' }, { status: 404 });

    // 2. Check if student is already in a group for this offering
    const existingMembership = await db.groupMembership.findFirst({
      where: {
        studentId,
        offeringId: group.offeringId
      }
    });

    if (existingMembership) {
      return NextResponse.json({ code: 'CONFLICT', message: 'You are already in a group for this course' }, { status: 409 });
    }

    // 3. Check group capacity
    if (group._count.memberships >= group.offering.maxGroupSize) {
      return NextResponse.json({ code: 'BAD_REQUEST', message: 'Group is full' }, { status: 400 });
    }

    if (group.isLocked) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Group is locked' }, { status: 403 });
    }

    // 4. If OPEN, join immediately
    if (group.isOpen) {
      const membership = await db.groupMembership.create({
        data: {
          groupId: group.id,
          studentId,
          offeringId: group.offeringId
        }
      });
      return NextResponse.json({ data: membership, message: 'Successfully joined group' });
    } else {
      // 5. If CLOSED (Invite Only), create a join request
      // Prevent duplicate pending requests to the same group
      const existingRequest = await db.groupChangeRequest.findFirst({
        where: {
          studentId,
          groupId: group.id,
          status: 'PENDING'
        }
      });

      if (existingRequest) {
        return NextResponse.json({ code: 'CONFLICT', message: 'You already have a pending request for this group' }, { status: 409 });
      }

      const request = await db.groupChangeRequest.create({
        data: {
          groupId: group.id,
          studentId,
          reason: 'Student requested to join'
        }
      });

      return NextResponse.json({ data: request, message: 'Request sent to group leader' });
    }
  } catch (error: any) {
    console.error('Error joining group:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR', message: error.message }, { status: 500 });
  }
}

