import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function POST(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    
    let studentId = scope.userId;
    const body = await request.json().catch(() => ({}));
    
    if (body.studentId) {
      studentId = body.studentId;
    } else if (body.studentNumber) {
      const student = await db.user.findFirst({ where: { studentNumber: body.studentNumber } });
      if (!student) return NextResponse.json({ code: 'NOT_FOUND', message: 'No student found with that student number' }, { status: 404 });
      studentId = student.id;
    }

    const group = await db.group.findUnique({
      where: { id: params.id },
      include: {
        offering: true,
        _count: { select: { memberships: true } }
      }
    });

    if (!group) return NextResponse.json({ code: 'NOT_FOUND', message: 'Group not found' }, { status: 404 });
    
    if (group.isLocked) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Group is locked' }, { status: 403 });
    }

    if (group._count.memberships >= group.offering.maxGroupSize) {
      return NextResponse.json({ code: 'CONFLICT', message: 'Group is full' }, { status: 409 });
    }

    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    const isLeader = group.leaderId === scope.userId;

    if (studentId !== scope.userId) {
      // Trying to add someone else
      if (!isRep && !isLeader) {
        return NextResponse.json({ code: 'FORBIDDEN', message: 'Only the Group Leader or a Class Rep can add members directly' }, { status: 403 });
      }
    } else {
      // Trying to join themselves
      if (!group.isOpen && !isRep) {
        return NextResponse.json({ code: 'FORBIDDEN', message: 'Group is invite-only' }, { status: 403 });
      }
    }

    const membership = await db.groupMembership.create({
      data: {
        groupId: group.id,
        studentId: studentId,
        offeringId: group.offeringId
      }
    });

    const pendingReqs = await db.groupChangeRequest.findMany({
      where: {
        studentId: studentId,
        status: 'PENDING',
        group: { offeringId: group.offeringId }
      }
    });
    if (pendingReqs.length > 0) {
      await db.groupChangeRequest.updateMany({
        where: { id: { in: pendingReqs.map(r => r.id) } },
        data: { status: 'REJECTED' }
      });
    }

    // Update status if it reached min size, and also handle leadership handoff if the group was empty or leader is a rep
    const groupUpdates: any = {};
    if (group._count.memberships + 1 >= group.offering.minGroupSize && group.status === 'FORMING') {
      const { GroupStatus } = await import('@talora/database');
      groupUpdates.status = GroupStatus.COMPLETE;
    }

    // Check if the current leader is actually in the group
    if (group._count.memberships === 0) {
      // If the group had 0 members, the first person to join becomes the leader
      groupUpdates.leaderId = studentId;
    } else {
      const isLeaderInGroup = await db.groupMembership.findFirst({
        where: { groupId: group.id, studentId: group.leaderId }
      });
      if (!isLeaderInGroup) {
        groupUpdates.leaderId = studentId;
      }
    }

    if (Object.keys(groupUpdates).length > 0) {
      await db.group.update({
        where: { id: group.id },
        data: groupUpdates
      });
    }

    return NextResponse.json({ data: membership }, { status: 201 });
  } catch (error: any) {
    if (error.code === 'P2002') {
      return NextResponse.json({ code: 'CONFLICT', message: 'Already a member of a group in this offering' }, { status: 409 });
    }
    console.error('Error joining group:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import { verifyJwt } from '@talora/auth';
import { cookies } from 'next/headers';

export const dynamic = 'force-dynamic';

export async function POST(request: Request, { params }: { params: { id: string } }) {
  try {
    const token = cookies().get('talora_token')?.value;
    if (!token) return NextResponse.json({ message: 'Unauthorized' }, { status: 401 });
    
    const payload = await verifyJwt(token);
    const groupId = params.id;
    
    // Verify user is leader or admin
    const group = await db.group.findUnique({
      where: { id: groupId },
      include: {
        offering: true,
        _count: { select: { memberships: true, placeholders: true } }
      }
    });
    
    if (!group) return NextResponse.json({ message: 'Group not found' }, { status: 404 });
    
    const isAdminOrRep = payload.roles.some((r: any) => r.role === 'PLATFORM_ADMIN' || r.role === 'CLASS_REPRESENTATIVE');
    if (group.leaderId !== payload.userId && !isAdminOrRep) {
      return NextResponse.json({ message: 'Forbidden: Only leaders can reserve spots' }, { status: 403 });
    }
    
    // Check capacity
    const totalMembers = group._count.memberships + group._count.placeholders;
    if (totalMembers >= group.offering.maxGroupSize) {
      return NextResponse.json({ message: 'Group is at maximum capacity' }, { status: 400 });
    }
    
    const body = await request.json();
    const { studentNumber } = body;
    
    if (!studentNumber || studentNumber.trim().length === 0) {
      return NextResponse.json({ message: 'Student Number is required' }, { status: 400 });
    }
    
    const placeholder = await db.groupPlaceholder.create({
      data: {
        groupId,
        studentNumber: studentNumber.trim(),
      }
    });
    
    return NextResponse.json({ message: 'Placeholder added', data: placeholder });
  } catch (err: any) {
    return NextResponse.json({ message: err.message }, { status: 500 });
  }
}

export async function DELETE(request: Request, { params }: { params: { id: string } }) {
  try {
    const token = cookies().get('talora_token')?.value;
    if (!token) return NextResponse.json({ message: 'Unauthorized' }, { status: 401 });
    
    const payload = await verifyJwt(token);
    const groupId = params.id;
    
    const url = new URL(request.url);
    const placeholderId = url.searchParams.get('placeholderId');
    if (!placeholderId) return NextResponse.json({ message: 'placeholderId required' }, { status: 400 });
    
    const group = await db.group.findUnique({ where: { id: groupId } });
    if (!group) return NextResponse.json({ message: 'Group not found' }, { status: 404 });
    
    const isAdminOrRep = payload.roles.some((r: any) => r.role === 'PLATFORM_ADMIN' || r.role === 'CLASS_REPRESENTATIVE');
    if (group.leaderId !== payload.userId && !isAdminOrRep) {
      return NextResponse.json({ message: 'Forbidden: Only leaders can modify placeholders' }, { status: 403 });
    }
    
    await db.groupPlaceholder.delete({
      where: { id: placeholderId }
    });
    
    return NextResponse.json({ message: 'Placeholder removed' });
  } catch (err: any) {
    return NextResponse.json({ message: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function PATCH(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    const body = await request.json();

    const group = await db.group.findUnique({
      where: { id: params.id }
    });

    if (!group) return NextResponse.json({ code: 'NOT_FOUND', message: 'Group not found' }, { status: 404 });

    // Only reps or the group leader can update the group
    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    const isLeader = group.leaderId === scope.userId;

    if (!isRep && !isLeader) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Not authorized to modify this group' }, { status: 403 });
    }

    // Prepare update data
    const data: any = {};
    if (body.name && (isLeader || isRep)) data.name = body.name; // Leader/Rep can rename
    if (body.status && isRep) data.status = body.status; // Only Rep can force status
    if (body.isLocked !== undefined && isRep) data.isLocked = body.isLocked; // Only Rep can lock
    if (body.isOpen !== undefined && (isRep || isLeader)) data.isOpen = body.isOpen; // Leader/Rep can toggle Open/Closed
    if (body.leaderId && (isRep || isLeader)) {
      // Transfer leadership
      // Verify new leader is in the group
      const newLeaderMembership = await db.groupMembership.findFirst({
        where: {
          groupId: group.id,
          studentId: body.leaderId
        }
      });
      if (!newLeaderMembership) {
        return NextResponse.json({ code: 'BAD_REQUEST', message: 'New leader must be a group member' }, { status: 400 });
      }
      data.leaderId = body.leaderId;
    }

    const updated = await db.group.update({
      where: { id: params.id },
      data
    });

    return NextResponse.json({ data: updated });
  } catch (error) {
    console.error('Error updating group:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: { id: string } }
) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;

    const group = await db.group.findUnique({
      where: { id: params.id }
    });

    if (!group) return NextResponse.json({ code: 'NOT_FOUND', message: 'Group not found' }, { status: 404 });

    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    const isLeader = group.leaderId === scope.userId;

    if (!isRep && !isLeader) {
      return NextResponse.json({ code: 'FORBIDDEN', message: 'Not authorized to delete this group' }, { status: 403 });
    }

    await db.group.delete({ where: { id: group.id } });

    // Renumber remaining standard "Group N" groups for this offering
    const allGroups = await db.group.findMany({
      where: { offeringId: group.offeringId },
      orderBy: { createdAt: 'asc' }
    });

    let number = 1;
    for (const g of allGroups) {
      if (/^Group \d+$/i.test(g.name)) {
         await db.group.update({
            where: { id: g.id },
            data: { name: `Group ${number}` }
         });
         number++;
      }
    }

    return NextResponse.json({ message: 'Group deleted successfully' });
  } catch (error) {
    console.error('Error deleting group:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function POST(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    const studentId = scope.userId;
    const body = await request.json();
    const { offeringId } = body;

    if (!offeringId) {
      return NextResponse.json({ code: 'BAD_REQUEST', message: 'offeringId is required' }, { status: 400 });
    }

    const offering = await db.courseOffering.findUnique({
      where: { id: offeringId }
    });

    if (!offering) return NextResponse.json({ code: 'NOT_FOUND', message: 'Offering not found' }, { status: 404 });

    // Check if already in a group
    const existingMembership = await db.groupMembership.findFirst({
      where: { studentId, offeringId }
    });

    if (existingMembership) {
      return NextResponse.json({ code: 'CONFLICT', message: 'You are already in a group' }, { status: 409 });
    }

    // Find all groups that are open, not locked, and have space
    const groups = await db.group.findMany({
      where: {
        offeringId,
        isOpen: true,
        isLocked: false
      },
      include: {
        _count: { select: { memberships: true } }
      }
    });

    const openGroupsWithSpace = groups.filter(g => g._count.memberships < offering.maxGroupSize);

    if (openGroupsWithSpace.length > 0) {
      // Pick a random open group
      const targetGroup = openGroupsWithSpace[Math.floor(Math.random() * openGroupsWithSpace.length)];
      
      const membership = await db.groupMembership.create({
        data: {
          groupId: targetGroup.id,
          studentId,
          offeringId
        }
      });
      return NextResponse.json({ data: membership, message: `Auto-assigned to group ${targetGroup.name}` });
    }

    // No open groups available, create a new one
    const student = await db.user.findUnique({ where: { id: studentId } });
    const studentName = student?.fullName || 'Student';
    
    // Auto-generate a name
    const existingGroups = await db.group.findMany({
      where: { offeringId },
      select: { name: true }
    });
    let maxNumber = 0;
    for (const g of existingGroups) {
      const match = g.name.match(/Group (\d+)/i);
      if (match) {
        const num = parseInt(match[1], 10);
        if (num > maxNumber) maxNumber = num;
      }
    }
    const groupName = `Group ${maxNumber + 1} (${studentName.split(' ')[0]})`;

    const newGroup = await db.group.create({
      data: {
        name: groupName,
        offeringId,
        leaderId: studentId,
        isOpen: true,
        memberships: {
          create: {
            studentId,
            offeringId
          }
        }
      }
    });

    // Also assign a GROUP_LEADER role
    await db.userRole.create({
      data: {
        userId: studentId,
        role: 'GROUP_LEADER',
        classId: offering.classId
      }
    });

    return NextResponse.json({ data: newGroup, message: 'Created a new group for you' });

  } catch (error: any) {
    console.error('Error auto-assigning group:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR', message: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function GET(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });

    const scope = JSON.parse(scopeHeader) as UserScope;
    
    const url = new URL(request.url);
    const offeringId = url.searchParams.get('offeringId');
    const status = url.searchParams.get('status'); // optional filter
    const page = Math.max(1, parseInt(url.searchParams.get('page') ?? '1', 10));
    const limit = Math.min(50, Math.max(1, parseInt(url.searchParams.get('limit') ?? '25', 10)));
    const skip = (page - 1) * limit;

    if (!offeringId) {
      return NextResponse.json({ code: 'BAD_REQUEST', message: 'offeringId is required' }, { status: 400 });
    }

    const isRep = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');

    // Reps see all issues for the offering. Students see only their own issues.
    const whereClause: any = { offeringId };
    if (!isRep) {
      whereClause.studentId = scope.userId;
    }
    if (status) {
      whereClause.status = status;
    }

    const [issues, total] = await Promise.all([
      db.issue.findMany({
        where: whereClause,
        orderBy: { createdAt: 'desc' },
        include: {
          student: { select: { id: true, fullName: true, email: true } },
        },
        skip,
        take: limit,
      }),
      db.issue.count({ where: whereClause }),
    ]);

    return NextResponse.json({
      data: issues,
      pagination: { page, limit, total, totalPages: Math.ceil(total / limit), hasMore: skip + limit < total },
    });
  } catch (error) {
    console.error('Error fetching issues:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

