import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import { verifyJwt } from '@talora/auth';
import { cookies } from 'next/headers';

export const dynamic = 'force-dynamic';

export async function POST(request: Request, { params }: { params: { id: string } }) {
  try {
    const token = cookies().get('talora_token')?.value;
    if (!token) return NextResponse.json({ message: 'Unauthorized' }, { status: 401 });

    const payload = await verifyJwt(token);
    const offeringId = params.id;

    // Verify user is rep or admin
    const isAdminOrRep = payload.roles.some((r: any) => 
      r.role === 'PLATFORM_ADMIN' || (r.role === 'CLASS_REPRESENTATIVE' && r.classId)
    );

    if (!isAdminOrRep) {
      return NextResponse.json({ message: 'Forbidden: Only Class Reps can bulk assign' }, { status: 403 });
    }

    const offering = await db.courseOffering.findUnique({
      where: { id: offeringId }
    });

    if (!offering) return NextResponse.json({ message: 'Offering not found' }, { status: 404 });

    // Find all enrolled students who are NOT in a group for this offering
    const enrollments = await db.enrollment.findMany({
      where: { offeringId },
      include: { student: true }
    });

    const memberships = await db.groupMembership.findMany({
      where: { offeringId }
    });

    const groupedStudentIds = new Set(memberships.map(m => m.studentId));

    const ungroupedStudents = enrollments
      .filter(e => !groupedStudentIds.has(e.studentId))
      .map(e => e.student);

    if (ungroupedStudents.length === 0) {
      return NextResponse.json({ message: 'No ungrouped students to assign' });
    }

    // Shuffle the students to ensure truly random allocation, especially when creating new groups
    for (let i = ungroupedStudents.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [ungroupedStudents[i], ungroupedStudents[j]] = [ungroupedStudents[j], ungroupedStudents[i]];
    }

    // Find all groups that are open, not locked, and have space
    const groups = await db.group.findMany({
      where: {
        offeringId,
        isOpen: true,
        isLocked: false
      },
      include: {
        _count: { select: { memberships: true, placeholders: true } }
      }
    });

    const openGroupsWithSpace = groups
      .map(g => ({
        ...g,
        totalMembers: g._count.memberships + g._count.placeholders
      }))
      .filter(g => g.totalMembers < offering.maxGroupSize);

    let assignedCount = 0;
    let newGroupsCreated = 0;

    for (const student of ungroupedStudents) {
      if (openGroupsWithSpace.length > 0) {
        // Pick a random open group
        const randomIndex = Math.floor(Math.random() * openGroupsWithSpace.length);
        const targetGroup = openGroupsWithSpace[randomIndex];

        await db.groupMembership.create({
          data: {
            groupId: targetGroup.id,
            studentId: student.id,
            offeringId
          }
        });
        assignedCount++;

        // Update local count
        targetGroup.totalMembers++;
        if (targetGroup.totalMembers >= offering.maxGroupSize) {
          // Remove from openGroupsWithSpace
          openGroupsWithSpace.splice(randomIndex, 1);
        }
      } else {
        // No open groups available, create a new one
        const existingGroups = await db.group.findMany({
          where: { offeringId },
          select: { name: true }
        });

        let maxNumber = 0;
        for (const g of existingGroups) {
          const match = g.name.match(/Group (\d+)/i);
          if (match) {
            const num = parseInt(match[1], 10);
            if (num > maxNumber) maxNumber = num;
          }
        }
        const groupName = `Group ${maxNumber + 1}`;

        const newGroup = await db.group.create({
          data: {
            name: groupName,
            offeringId,
            leaderId: student.id,
            isOpen: true,
            memberships: {
              create: {
                studentId: student.id,
                offeringId
              }
            }
          }
        });

        // Also assign a GROUP_LEADER role
        await db.userRole.create({
          data: {
            userId: student.id,
            role: 'GROUP_LEADER',
            classId: offering.classId
          }
        });

        assignedCount++;
        newGroupsCreated++;

        // Add to open groups pool if it has space
        if (offering.maxGroupSize > 1) {
          openGroupsWithSpace.push({
            ...newGroup,
            _count: { memberships: 1, placeholders: 0 },
            totalMembers: 1
          } as any);
        }
      }
    }

    return NextResponse.json({ 
      success: true, 
      message: `Successfully assigned ${assignedCount} students. Created ${newGroupsCreated} new groups.` 
    });

  } catch (error: any) {
    console.error('Error in bulk auto-assign:', error);
    return NextResponse.json({ message: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import * as ExcelJS from 'exceljs';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return new NextResponse('Unauthorized', { status: 401 });
    const scope = JSON.parse(scopeHeader);

    const isRep = scope.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    if (!isRep) return new NextResponse('Forbidden', { status: 403 });

    const offering = await db.courseOffering.findUnique({
      where: { id: params.id },
      include: { unit: true, class: true }
    });

    if (!offering) return new NextResponse('Offering not found', { status: 404 });

    const rosterUsers = await db.user.findMany({
      where: {
        OR: [
          { enrollments: { some: { offeringId: params.id } } },
          { memberships: { some: { offeringId: params.id } } }
        ]
      },
      include: {
        memberships: {
          where: { offeringId: params.id },
          include: { group: true }
        }
      }
    });

    const students = rosterUsers.map(user => ({
      fullName: user.fullName,
      studentNumber: user.studentNumber || '',
      registrationNumber: user.registrationNumber || '',
      group: user.memberships[0]?.group?.name || 'Unassigned'
    }));

    // Sort by group name (natural numeric sort), then by full name
    students.sort((a, b) => {
      const groupCompare = a.group.localeCompare(b.group, undefined, { numeric: true, sensitivity: 'base' });
      if (groupCompare !== 0) return groupCompare;
      return a.fullName.localeCompare(b.fullName);
    });

    // Group students for formatting
    const groupedStudents: Record<string, typeof students> = {};
    for (const student of students) {
      if (!groupedStudents[student.group]) {
        groupedStudents[student.group] = [];
      }
      groupedStudents[student.group].push(student);
    }

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('Groups Roster');

    // Define columns
    worksheet.columns = [
      { header: 'Group', key: 'group', width: 25 },
      { header: 'Full Name', key: 'fullName', width: 35 },
      { header: 'Student Number', key: 'studentNumber', width: 20 },
      { header: 'Registration Number', key: 'registrationNumber', width: 25 }
    ];

    worksheet.getRow(1).eachCell((cell) => {
      cell.font = { bold: true };
      cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
    });

    let currentRow = 2;
    const groupNames = Object.keys(groupedStudents);
    for (let i = 0; i < groupNames.length; i++) {
      const groupName = groupNames[i];
      const members = groupedStudents[groupName];
      const startRow = currentRow;

      for (const member of members) {
        const row = worksheet.getRow(currentRow);
        row.getCell(1).value = member.group;
        row.getCell(2).value = member.fullName;
        row.getCell(3).value = member.studentNumber;
        row.getCell(4).value = member.registrationNumber;

        [2, 3, 4].forEach(colIndex => {
          const cell = row.getCell(colIndex);
          cell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
        });

        currentRow++;
      }

      const endRow = currentRow - 1;
      if (startRow < endRow) worksheet.mergeCells(startRow, 1, endRow, 1);

      const groupCell = worksheet.getCell(startRow, 1);
      groupCell.alignment = { vertical: 'middle', horizontal: 'center' };
      groupCell.border = { top: { style: 'thin' }, left: { style: 'thin' }, bottom: { style: 'thin' }, right: { style: 'thin' } };
      groupCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF8EA9DB' } };

      if (i < groupNames.length - 1) currentRow++;
    }

    const buffer = await workbook.xlsx.writeBuffer();

    // Proper filename with unit code
    const unitCode = offering.unit.code.replace(/[^a-zA-Z0-9]/g, '_');
    const filename = `groups_roster_${unitCode}.xlsx`;

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="${filename}"`
      }
    });
  } catch (err: any) {
    console.error('Export Error:', err);
    return new NextResponse('Internal Server Error', { status: 500 });
  }
}

