    const updatedOffering = await db.courseOffering.update({
      where: { id: params.id },
      data: {
        minGroupSize,
        maxGroupSize
      }
    });

    return NextResponse.json({ data: updatedOffering });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

