    if (!offering) {
      return NextResponse.json({ error: 'Offering not found' }, { status: 404 });
    }

    // Attempt to extract year from cohort (e.g. "24/U" -> "24")
    // Fallback to the explicit year field on the ClassCohort model
    const cohortYearPrefix = offering.class.year.toString().slice(-2);

    const buffer = Buffer.from(await file.arrayBuffer());
    let extractedData: any[] = [];

    // --- PARSING PHASE ---
    if (structureType === 'FLAT') {
      if (!mappingStr) return NextResponse.json({ error: 'Missing column mapping' }, { status: 400 });
      const mapping = JSON.parse(mappingStr);
      
      const workbook = new ExcelJS.Workbook();
      if (file.name.endsWith('.csv')) {
        const { Readable } = require('stream');
        const stream = Readable.from(buffer);
        await workbook.csv.read(stream);
      } else {
        await workbook.xlsx.load(buffer as any);
      }
      
      const worksheet = workbook.worksheets[0];
      const allRows: any[][] = [];
      worksheet.eachRow({ includeEmpty: false }, (row) => {
        const values = Array.isArray(row.values) ? row.values.slice(1).map(v => v ? String(v).trim() : '') : [];
        if (values.some(v => v !== '')) allRows.push(values);
      });

      // Skip header row
      const dataRows = allRows.slice(1);
      
      extractedData = dataRows.map(row => {
        const getMapped = (field: string) => {
          const colIndex = Object.keys(mapping).find(key => mapping[key] === field);
          return colIndex !== undefined ? row[parseInt(colIndex)] : undefined;
        };
        
        return {
          fullName: getMapped('fullName'),
          studentNumber: getMapped('studentNumber'),
          email: getMapped('email'),
          registrationNumber: getMapped('registrationNumber'),
          groupName: getMapped('groupName'),
        };
      });

    } else {
      // SECTION_BASED AI Reparsing (full file this time)
      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey) return NextResponse.json({ error: 'AI not configured' }, { status: 500 });
      
      const workbook = new ExcelJS.Workbook();
      if (file.name.endsWith('.csv')) {
        const { Readable } = require('stream');
        const stream = Readable.from(buffer);
        await workbook.csv.read(stream);
      } else {
        await workbook.xlsx.load(buffer as any);
      }
      const worksheet = workbook.worksheets[0];
      const allRows: any[][] = [];
      worksheet.eachRow({ includeEmpty: false }, (row) => {
        const values = Array.isArray(row.values) ? row.values.slice(1).map(v => v ? String(v).trim() : '') : [];
        if (values.some(v => v !== '')) allRows.push(values);
      });

      const genAI = new GoogleGenerativeAI(apiKey);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      
      // For large files, we should ideally chunk this, but for this prototype we'll send it all
      const prompt = `
        Analyze this university class list data extracted from a spreadsheet.
        It appears to be section-based (e.g. group names appearing as rows separating blocks of students).
        Extract ALL students and their assigned groups from this entire dataset.
        Return ONLY a JSON object with this exact structure:
        {"extractedRows": [{"fullName": "...", "studentNumber": "...", "email": "...", "groupName": "..."}]}
        Data: ${JSON.stringify(allRows)}
      `;

      try {
        const result = await model.generateContent(prompt);
        const text = result.response.text().replace(/```json/gi, '').replace(/```/gi, '').trim();
        const aiParsed = JSON.parse(text);
        extractedData = aiParsed.extractedRows;
      } catch (e) {
        return NextResponse.json({ error: 'AI parsing failed on full dataset' }, { status: 500 });
      }
    }

    // --- EXECUTION PHASE ---
    const results = {
      enrolled: 0,
      updated: 0,
      unchanged: 0,
      skipped: 0,
      errors: 0,
      retakers: 0,
      details: [] as any[]
    };

    // Use a transaction for safety? We'll do sequential awaits for easier error handling per-row
    for (const data of extractedData) {
      if (!data.studentNumber || !data.fullName) {
        results.errors++;
        results.details.push({ row: data, error: 'Missing required fields (Name or Student Number)' });
        continue;
      }

      let isNewEnrollment = false;
      let isGroupUpdated = false;

      const studentNumber = data.studentNumber.trim();
      const email = data.email?.trim() || null;
      
      // 1. Check Retaker Status
      // E.g. "23/U/1234" vs cohort year "24"
      const match = studentNumber.match(/^(\d{2})/);
      const rowYearPrefix = match ? match[1] : null;
      const isRetaker = rowYearPrefix && rowYearPrefix !== cohortYearPrefix;

      if (isRetaker) {
        results.retakers++;
        if (importType === 'CLASS_ROSTER') {
          results.errors++;
          results.details.push({ row: data, error: 'Retaker found in a Class Roster import. Use Course Enrollment mode instead.' });
          continue;
        }
      }

      try {
        // 2. Find or Create User
        let user = await db.user.findUnique({ where: { studentNumber } });
        
        if (!user) {
          if (!email) {
            // Partial Data - we can't create an account without an email right now.
            // In a full implementation, we'd create a "PreEnrollment" record here.
            // For now, we must skip them.
            results.skipped++;
            results.details.push({ row: data, warning: 'No email provided. Account cannot be created.' });
            continue;
          }

          if (!dryRun) {
            user = await db.user.create({
              data: {
                institutionId: offering.term.institutionId,
                fullName: data.fullName,
                studentNumber,
                email: email,
                passwordHash: generateTempPassword(), // Temp password
                registrationNumber: data.registrationNumber,
                isActive: true,
                isEmailVerified: false,
              }
            });
          } else {
            user = { id: `temp-user-${studentNumber}` } as any;
          }
        }

        // 3. Add to ClassCohort if it's a CLASS_ROSTER import and they aren't a retaker
        if (importType === 'CLASS_ROSTER' && !isRetaker) {
          const roleExists = await db.userRole.findFirst({
            where: { userId: user!.id, role: 'STUDENT', classId: offering.classId }
          });
          
          if (!roleExists && !dryRun) {
            await db.userRole.create({
              data: {
                userId: user!.id,
                role: 'STUDENT',
                classId: offering.classId
              }
            });
          }
        }

        // 4. Enroll in CourseOffering
        const enrollmentExists = await db.enrollment.findUnique({
          where: { studentId_offeringId: { studentId: user!.id, offeringId: offering.id } }
        });

        if (!enrollmentExists) {
          if (!dryRun) {
            await db.enrollment.create({
              data: { studentId: user!.id, offeringId: offering.id }
            });
          }
          isNewEnrollment = true;
        }

        // 5. Handle Group Assignment
        if (data.groupName) {
          let group = await db.group.findFirst({
            where: { offeringId: offering.id, name: data.groupName }
          });

          // Create group if it doesn't exist
          if (!group) {
            if (!dryRun) {
              group = await db.group.create({
                data: {
                  offeringId: offering.id,
                  name: data.groupName,
                  leaderId: user!.id, // Set the first imported student as the leader
                  status: 'INCOMPLETE',
                  isOpen: true,
                }
              });
            } else {
              group = { id: `temp-group-${data.groupName}` } as any;
            }
          }

          // Assign membership
          const membershipExists = await db.groupMembership.findUnique({
            where: { studentId_offeringId: { studentId: user!.id, offeringId: offering.id } }
          });

          if (!membershipExists) {
             // Basic capacity check
             const memberCount = await db.groupMembership.count({ where: { groupId: group!.id } });
             if (memberCount < offering.maxGroupSize || dryRun) {
               if (!dryRun) {
                 await db.groupMembership.create({
                   data: { studentId: user!.id, groupId: group!.id, offeringId: offering.id }
                 });
               }
               isGroupUpdated = true;
             } else {
               results.details.push({ row: data, warning: `Group '${data.groupName}' is full. Enrolled as ungrouped.` });
             }
          } else if (membershipExists.groupId !== group!.id) {
             // User is in a different group, update their group
             const memberCount = await db.groupMembership.count({ where: { groupId: group!.id } });
             if (memberCount < offering.maxGroupSize || dryRun) {
               if (!dryRun) {
                 await db.groupMembership.update({
                   where: { studentId_offeringId: { studentId: user!.id, offeringId: offering.id } },
                   data: { groupId: group!.id }
                 });
               }
               isGroupUpdated = true;
               results.details.push({ row: data, warning: `Moved from previous group to '${data.groupName}'.` });
             } else {
               results.details.push({ row: data, warning: `Group '${data.groupName}' is full. Kept in previous group.` });
             }
          }
        }

        if (isNewEnrollment) {
          results.enrolled++;
        } else if (isGroupUpdated) {
          results.updated++;
        } else {
          results.unchanged++;
        }

      } catch (err: any) {
        console.error('Error importing row:', err);
        results.errors++;
        results.details.push({ row: data, error: err.message });
      }
    }

    return NextResponse.json({ data: results });

  } catch (error) {
    console.error('Error executing import:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';
import ExcelJS from 'exceljs';
import Fuse from 'fuse.js';
import { GoogleGenerativeAI } from '@google/generative-ai';

export const dynamic = 'force-dynamic';

const FIELD_SYNONYMS = {
  fullName:           ['name', 'full name', 'student name', 'surname', 'fullname', 'first name', 'last name'],
  studentNumber:      ['std no', 'student no', 'student number', 'stdno', 'student id', 'registration', 'reg no', 'reg number'], // Grouped for initial fuzzy matching
  email:              ['email', 'e-mail', 'email address', 'mail'],
  registrationNumber: ['reg no', 'reg. no.', 'registration', 'reg number', 'regno'],
  groupName:          ['group', 'grp', 'group name', 'tutorial', 'tut group'],
};

// Create a flat list of synonyms mapped to their target field for Fuse
const synonymList = Object.entries(FIELD_SYNONYMS).flatMap(([field, synonyms]) => 
  synonyms.map(synonym => ({ synonym, field }))
);

const fuse = new Fuse(synonymList, {
  keys: ['synonym'],
  threshold: 0.3 // Require fairly good matches
});

export async function POST(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    const scope = JSON.parse(scopeHeader) as UserScope;

    // Authorization check
    if (!scope.roles.some((r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN')) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const formData = await request.formData();
    const file = formData.get('file') as File | null;

    if (!file) {
      return NextResponse.json({ error: 'No file provided' }, { status: 400 });
    }

    // 1. Read file into a 2D array
    const buffer = Buffer.from(await file.arrayBuffer());
    const workbook = new ExcelJS.Workbook();

    if (file.name.endsWith('.csv')) {
      // Create a stream from the buffer to make csv.read happy
      const { Readable } = require('stream');
      const stream = Readable.from(buffer);
      await workbook.csv.read(stream);
    } else {
      await workbook.xlsx.load(buffer as any);
    }

    const worksheet = workbook.worksheets[0];
    if (!worksheet) {
      return NextResponse.json({ error: 'Spreadsheet is empty' }, { status: 400 });
    }

    const allRows: any[][] = [];
    worksheet.eachRow({ includeEmpty: false }, (row, rowNumber) => {
      // row.values is 1-indexed in exceljs
      const values = Array.isArray(row.values) 
        ? row.values.slice(1).map(v => v ? String(v).trim() : '')
        : [];
      // Filter out empty rows
      if (values.some(v => v !== '')) {
         allRows.push(values);
      }
    });

    if (allRows.length === 0) {
      return NextResponse.json({ error: 'No data found in file' }, { status: 400 });
    }

    // 2. Detect Structure Type
    let structureType: 'FLAT' | 'SECTION_BASED' = 'FLAT';

    // Count rows that only have 1 non-empty cell (potential section headers)
    const singleCellRows = allRows.filter(row => row.filter(cell => cell !== '').length === 1);

    // If we have multiple such rows, and they contain words like "group" or just short strings, it's likely section-based
    const likelySectionHeaders = singleCellRows.filter(row => {
      const val = row.find(cell => cell !== '') || '';
      const vLower = val.toLowerCase();
      return vLower.includes('group') || vLower.includes('grp') || vLower.includes('tut') || (val.length < 20 && val.length > 2);
    });

    if (likelySectionHeaders.length >= 2) {
      structureType = 'SECTION_BASED';
    }

    // 3. Process based on structure
    if (structureType === 'FLAT') {
      // Find the header row - assume it's the first non-empty row for now
      const headerRow = allRows[0];
      const dataRows = allRows.slice(1, 6); // Take up to 5 rows for sample

      // Auto-map columns using Fuse
      const mappingSuggestions: Record<string, string> = {};

      headerRow.forEach((header, index) => {
        if (!header) return;
        const result = fuse.search(header);
        if (result.length > 0) {
          mappingSuggestions[index.toString()] = result[0].item.field;
        }
      });

      return NextResponse.json({
        data: {
          structureType,
          columns: headerRow,
          sampleRows: dataRows,
          suggestedMapping: mappingSuggestions,
          totalRowsDetected: allRows.length - 1
        }
      });

    } else {
      // SECTION_BASED - Attempt AI Extraction if API key is present
      const apiKey = process.env.GEMINI_API_KEY;

      if (!apiKey) {
        // Fallback if no AI key: return raw structure and warn
        return NextResponse.json({
          data: {
            structureType,
            warning: 'Section-based structure detected, but AI parsing is not configured. Please use a flat table.',
            rawRows: allRows.slice(0, 15) // Give them a peek at what we saw
          }
        });
      }

      try {
        const genAI = new GoogleGenerativeAI(apiKey);
        const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });

        // We only send a sample to save tokens and time
        const sampleToAnalyze = allRows.slice(0, 30);

        const prompt = `
          Analyze this university class list data extracted from a spreadsheet.
          It appears to be section-based (e.g. group names appearing as rows separating blocks of students).

          Extract the students and their assigned groups from this data.

          Return ONLY a JSON object with this exact structure:
          {
            "extractedRows": [
              {
                "fullName": "Student's name",
                "studentNumber": "Student number if found",
                "email": "Email if found",
                "groupName": "The group name this student belongs to, based on the section header above them"
              }
            ]
          }

          Do not include markdown backticks or any other text. Just the raw JSON.

          Data:
          ${JSON.stringify(sampleToAnalyze)}
        `;

        const result = await model.generateContent(prompt);
        let text = result.response.text();

        // Clean up markdown if Gemini ignored the instruction
        text = text.replace(/```json/gi, '').replace(/```/gi, '').trim();

        let aiParsed;
        try {
          aiParsed = JSON.parse(text);
        } catch (e) {
          console.error("Failed to parse Gemini response:", text);
          throw new Error("AI returned invalid JSON");
        }

        return NextResponse.json({
          data: {
            structureType,
            extractedSample: aiParsed.extractedRows,
            totalRowsAnalyzed: sampleToAnalyze.length,
            message: 'AI successfully analyzed the structure. You can proceed to import.'
          }
        });

      } catch (aiError) {
        console.error("AI Analysis failed:", aiError);
        return NextResponse.json({ error: 'AI structure analysis failed' }, { status: 500 });
      }
    }

  } catch (error) {
    console.error('Error previewing import:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';


export async function GET(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });
    const scope = JSON.parse(scopeHeader) as UserScope;

    const url = new URL(request.url);
    const offeringId = url.searchParams.get('offeringId');

    const whereClause: any = {};
    if (offeringId) {
      whereClause.offeringId = offeringId;
    } else {
      // Fetch for all enrolled offerings
      const enrollments = await db.enrollment.findMany({ where: { studentId: scope.userId }, select: { offeringId: true } });
      const offeringIds = enrollments.map(e => e.offeringId);
      whereClause.offeringId = { in: offeringIds };
    }

    const events = await db.timetableEvent.findMany({
      where: whereClause,
      orderBy: [
        { dayOfWeek: 'asc' },
        { startTime: 'asc' }
      ]
    });

    return NextResponse.json({ data: events });
  } catch (error) {
    console.error('Error fetching timetable events:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  try {
    const scopeHeader = request.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ code: 'UNAUTHORIZED' }, { status: 401 });
    
    const scope = JSON.parse(scopeHeader) as UserScope;
    const canEdit = scope.roles.some(r => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN');
    if (!canEdit) return NextResponse.json({ code: 'FORBIDDEN' }, { status: 403 });

    const body = await request.json();
    const { offeringId, title, location, dayOfWeek, startTime, endTime } = body;

    const newEvent = await db.timetableEvent.create({
      data: {
        offeringId,
        title,
        location,
        dayOfWeek: Number(dayOfWeek),
        startTime,
        endTime,
      }
    });

    return NextResponse.json({ data: newEvent }, { status: 201 });
  } catch (error) {
    console.error('Error creating timetable event:', error);
    return NextResponse.json({ code: 'INTERNAL_ERROR' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';

export async function PUT(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const scope = JSON.parse(scopeHeader) as UserScope;

    const caller = await db.user.findUnique({
      where: { id: scope.userId },
      include: { roles: true }
    });

    if (!caller) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    const isPlatformAdmin = caller.roles.some(r => r.role === 'PLATFORM_ADMIN');
    if (!isPlatformAdmin) {
      return NextResponse.json({ error: 'Forbidden. Requires PLATFORM_ADMIN role.' }, { status: 403 });
    }

    const targetUserId = params.id;
    const body = await req.json();
    // roles is now an array of { role, classId? } objects
    const { roles } = body;

    if (!Array.isArray(roles)) {
      return NextResponse.json({ error: 'Roles must be an array' }, { status: 400 });
    }

    // Enforce: CLASS_REPRESENTATIVE must always have a classId
    const repWithoutClass = roles.find(
      (r: any) => r.role === 'CLASS_REPRESENTATIVE' && !r.classId
    );
    if (repWithoutClass) {
      return NextResponse.json(
        { error: 'A class must be selected when assigning the CLASS_REPRESENTATIVE role.' },
        { status: 400 }
      );
    }

    const targetUser = await db.user.findUnique({ where: { id: targetUserId } });
    if (!targetUser) {
      return NextResponse.json({ error: 'Target user not found' }, { status: 404 });
    }

    if (targetUser.institutionId !== caller.institutionId) {
      return NextResponse.json({ error: 'Cannot modify users outside your institution' }, { status: 403 });
    }

    // Prevent removing your own PLATFORM_ADMIN role to avoid locking yourself out
    if (caller.id === targetUserId && !roles.some((r: any) => r.role === 'PLATFORM_ADMIN')) {
      return NextResponse.json({ error: 'You cannot remove your own PLATFORM_ADMIN role' }, { status: 400 });
    }

    await db.$transaction(async (tx) => {
      await tx.userRole.deleteMany({ where: { userId: targetUserId } });

      if (roles.length > 0) {
        await tx.userRole.createMany({
          data: roles.map((r: any) => ({
            userId: targetUserId,
            role: r.role,
            classId: r.classId || null,
          }))
        });
      }
    });

    const updatedUser = await db.user.findUnique({
      where: { id: targetUserId },
      include: { roles: { include: { class: true } } }
    });

    return NextResponse.json({ success: true, data: updatedUser }, { status: 200 });

  } catch (error) {
    console.error('Update User Roles Error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import { sendEmail } from '@/lib/email';
import { cookies } from 'next/headers';
import { verifyFirebaseToken } from '@/lib/firebase-admin';

export const dynamic = 'force-dynamic';


export async function PATCH(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    
    // We don't check for specific roles here, because any user should be able to edit their own profile
    // But we should verify the user is editing their own ID
    const scope = JSON.parse(scopeHeader);
    
    // Check if caller is platform admin
    const caller = await db.user.findUnique({
      where: { id: scope.userId },
      include: { roles: true }
    });
    const isPlatformAdmin = caller?.roles.some(r => r.role === 'PLATFORM_ADMIN');

    if (scope.userId !== params.id && !isPlatformAdmin) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const body = await req.json();
    const { fullName, email, studentNumber, registrationNumber, phoneNumber, acceptedTerms, isActive, firebaseIdToken } = body;

    const currentUser = await db.user.findUnique({ where: { id: params.id } });
    
    if (!currentUser) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    if (phoneNumber && phoneNumber !== currentUser.phoneNumber) {
      if (!firebaseIdToken) {
        return NextResponse.json({ error: 'Phone verification is required to update phone number.' }, { status: 400 });
      }
      try {
        const decodedToken = await verifyFirebaseToken(firebaseIdToken);
        if (decodedToken.phone_number !== phoneNumber) {
          return NextResponse.json({ error: 'The verified phone number does not match.' }, { status: 400 });
        }
      } catch (error) {
        return NextResponse.json({ error: 'Invalid or expired phone verification token.' }, { status: 401 });
      }
    }

    // Check permissions for isActive
    let finalIsActive = undefined;
    if (isActive !== undefined) {
      if (!isPlatformAdmin) {
        return NextResponse.json({ error: 'Forbidden. Only admins can toggle account status.' }, { status: 403 });
      }
      finalIsActive = isActive;
    }

    let emailChanged = false;

    if (email && email !== currentUser.email) {
      emailChanged = true;
    }

    const updateData: any = {
      fullName, 
      email, 
      studentNumber, 
      registrationNumber,
      phoneNumber,
      ...(finalIsActive !== undefined ? { isActive: finalIsActive } : {})
    };

    if (acceptedTerms !== undefined) {
      updateData.acceptedTerms = acceptedTerms;
    }

    const user = await db.user.update({
      where: { id: params.id },
      data: updateData
    });

    return NextResponse.json({ data: user, emailChanged });
  } catch (err: any) {
    if (err.code === 'P2002') {
      return NextResponse.json({ error: 'Email, student number, or registration number already in use' }, { status: 400 });
    }
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

export async function DELETE(req: NextRequest, { params }: { params: { id: string } }) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    
    const scope = JSON.parse(scopeHeader);
    
    const caller = await db.user.findUnique({
      where: { id: scope.userId },
      include: { roles: true }
    });
    const isPlatformAdmin = caller?.roles.some(r => r.role === 'PLATFORM_ADMIN');

    if (scope.userId !== params.id && !isPlatformAdmin) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    // Delete user (Prisma cascade will handle the rest)
    await db.user.delete({
      where: { id: params.id }
    });

    // Clear auth cookie if deleting self
    if (scope.userId === params.id) {
      cookies().delete('talora_token');
    }

    return NextResponse.json({ message: 'Account deleted successfully' });
  } catch (err: any) {
    console.error('Delete user error:', err);
    return NextResponse.json({ error: 'Failed to delete account' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { db } from '@talora/database';
import type { UserScope } from '@talora/auth';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest) {
  try {
    const scopeHeader = req.headers.get('x-user-scope');
    if (!scopeHeader) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const scope = JSON.parse(scopeHeader) as UserScope;

    // Fetch the caller to check roles and institution
    const caller = await db.user.findUnique({
      where: { id: scope.userId },
      include: { roles: true }
    });

    if (!caller) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    const isPlatformAdmin = scope.roles.some(r => r.role === 'PLATFORM_ADMIN');
    if (!isPlatformAdmin) {
      return NextResponse.json({ error: 'Forbidden. Requires PLATFORM_ADMIN role.' }, { status: 403 });
    }

    // Get search param
    const searchParams = req.nextUrl.searchParams;
    const query = searchParams.get('q') || '';
    const roleFilter = searchParams.get('role') || '';

    // Build filter
    const whereClause: any = {
      institutionId: caller.institutionId,
    };

    if (query) {
      whereClause.OR = [
        { fullName: { contains: query, mode: 'insensitive' } },
        { email: { contains: query, mode: 'insensitive' } },
        { studentNumber: { contains: query, mode: 'insensitive' } },
      ];
    }

    if (roleFilter && roleFilter !== 'ALL') {
      whereClause.roles = {
        some: {
          role: roleFilter
        }
      };
    }

    const users = await db.user.findMany({
      where: whereClause,
      include: {
        roles: true,
      },
      orderBy: {
        createdAt: 'desc'
      },
      take: 100 // limit to 100 for MVP
    });

    // Strip out passwordHash and return
    const safeUsers = users.map(u => {
      const { passwordHash, resetToken, resetTokenExpires, verificationToken, verificationTokenExpires, ...safe } = u;
      return safe;
    });

    return NextResponse.json({ data: safeUsers }, { status: 200 });

  } catch (error: any) {
    console.error('Fetch Users API Error:', error);
    return NextResponse.json({ error: String(error) + ' ' + (error.stack || '') }, { status: 500 });
  }
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';

export default function CourseSwitcher({ 
  availableOfferings, 
  activeOfferingId 
}: { 
  availableOfferings: any[], 
  activeOfferingId: string | null 
}) {
  const router = useRouter();
  const [isUpdating, setIsUpdating] = useState(false);
  
  // If no offering is active (or if it's stale/invalid), set the first available one as active
  useEffect(() => {
    const isStale = activeOfferingId && !availableOfferings.some(o => o.id === activeOfferingId);
    if ((!activeOfferingId || isStale) && availableOfferings.length > 0) {
      handleChange(availableOfferings[0].id);
    }
  }, [activeOfferingId, availableOfferings]);

  const handleChange = async (newOfferingId: string) => {
    if (newOfferingId === activeOfferingId) return;
    
    setIsUpdating(true);
    try {
      await fetch('/api/v1/active-offering', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ offeringId: newOfferingId }),
      });
      router.refresh();
    } catch (e) {
      console.error('Failed to switch course', e);
    } finally {
      setIsUpdating(false);
    }
  };

  if (!availableOfferings || availableOfferings.length === 0) return null;

  return (
    <div style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
      <div 
        style={{
          display: 'flex', alignItems: 'center', gap: '0.5rem',
          padding: '0.375rem 0.5rem',
          background: 'var(--color-bg-surface)',
          border: '1px solid var(--border-subtle)',
          borderRadius: '6px',
          transition: 'opacity 0.2s',
          opacity: isUpdating ? 0.7 : 1,
          pointerEvents: isUpdating ? 'none' : 'auto',
          position: 'relative'
        }}
      >
        <select 
          value={activeOfferingId || availableOfferings[0]?.id || ''}
          onChange={(e) => handleChange(e.target.value)}
          style={{
            background: 'transparent',
            border: 'none',
            color: 'var(--color-text-primary)',
            fontSize: '0.75rem',
            fontWeight: 600,
            outline: 'none',
            cursor: 'pointer',
            appearance: 'none',
            paddingRight: '1rem',
            maxWidth: '120px',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            overflow: 'hidden'
          }}
        >
          {availableOfferings.map(o => (
            <option key={o.id} value={o.id} style={{ color: 'var(--color-text-primary)' }}>
              {o.unit?.title} ┬╖ {o.class?.name}
            </option>
          ))}
        </select>
        <div style={{ position: 'absolute', right: '0.375rem', pointerEvents: 'none', display: 'flex', color: 'var(--color-text-secondary)' }}>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="6 9 12 15 18 9"></polyline></svg>
        </div>
      </div>
    </div>
  );
}

