import { unstable_cache } from 'next/cache';
import { db } from '@talora/database';

/**
 * Cached Queries ΓÇö Performance Layer
 *
 * These functions cache shared, class-wide data using Next.js unstable_cache.
 * Cache tags allow targeted invalidation when a Class Rep makes a change.
 *
 * Strategy:
 * - Timetable events, announcements: cached 5 minutes (changes rarely)
 * - KPI stats (group counts, submission counts): cached 60 seconds (changes more often)
 * - User-specific data (notifications, my group): NOT cached (personal data, must be fresh)
 */

/** Fetch timetable events for a set of offering IDs (shared by all students in that class) */
export const getCachedTimetableEvents = (offeringIds: string[]) =>
  unstable_cache(
    () =>
      db.timetableEvent.findMany({
        where: { offeringId: { in: offeringIds } },
        orderBy: [{ dayOfWeek: 'asc' }, { startTime: 'asc' }],
      }),
    ['timetable-events', ...offeringIds],
    {
      tags: offeringIds.map((id) => `timetable-${id}`),
      revalidate: 300, // 5 minutes
    }
  )();

/** Fetch latest announcements for an offering (shared by all students) */
export const getCachedAnnouncements = (offeringId: string) =>
  unstable_cache(
    () =>
      db.announcement.findMany({
        where: { offeringId },
        orderBy: { createdAt: 'desc' },
        take: 10,
        include: { author: { select: { fullName: true } } },
      }),
    ['announcements', offeringId],
    {
      tags: [`announcements-${offeringId}`],
      revalidate: 60, // 1 minute
    }
  )();

/** Fetch KPI counts for an offering. Cached 60s ΓÇö stale is acceptable for aggregate stats. */
export const getCachedOfferingKPIs = (offeringId: string, classId: string, termId: string) =>
  unstable_cache(
    async () => {
      const [
        totalEnrolled,
        studentsInGroups,
        groups,
        requests,
        issues,
        deadlines,
        totalSubmissions,
        latestAssignment,
        dbDeadlines,
        offeringSettings,
      ] = await Promise.all([
        db.enrollment.count({ where: { offeringId } }),
        db.groupMembership.count({ where: { offeringId } }),
        db.group.findMany({
          where: { offeringId },
          include: { _count: { select: { memberships: true } } },
        }),
        db.groupChangeRequest.count({ where: { status: 'PENDING', group: { offeringId } } }),
        db.issue.count({ where: { offeringId, status: 'OPEN' } }),
        db.assignment.count({ where: { offeringId, dueDate: { gte: new Date() } } }),
        db.submission.count({ where: { assignment: { offeringId } } }),
        db.assignment.findFirst({
          where: { offeringId, dueDate: { gte: new Date() } },
          orderBy: { dueDate: 'asc' },
        }),
        db.assignment.findMany({
          where: { offeringId, dueDate: { gte: new Date() } },
          orderBy: { dueDate: 'asc' },
          take: 3,
        }),
        db.courseOffering.findUnique({ where: { id: offeringId }, select: { minGroupSize: true } })
      ]);

      const minSize = offeringSettings?.minGroupSize || 4;

      return {
        totalEnrolled,
        ungrouped: totalEnrolled - studentsInGroups,
        incomplete: groups.filter((g) => g._count.memberships < minSize).length,
        requests,
        issues,
        deadlines,
        totalSubmissions,
        latestAssignment,
        dbDeadlines,
      };
    },
    ['offering-kpis', offeringId],
    {
      tags: [`kpis-${offeringId}`],
      revalidate: 60, // 1 minute
    }
  )();

/** Fetch all offerings for a class + term (used by timetable, course switcher) */
export const getCachedClassOfferings = (classId: string, termId: string) =>
  unstable_cache(
    () =>
      db.courseOffering.findMany({
        where: { classId, termId },
        include: { unit: true },
      }),
    ['class-offerings', classId, termId],
    {
      tags: [`class-offerings-${classId}-${termId}`],
      revalidate: 300, // 5 minutes
    }
  )();

import { db } from '@talora/database';
import { cookies } from 'next/headers';
import type { UserScope } from '@talora/auth';

export function getActiveOfferingId(): string | null {
  const cookieStore = cookies();
  const offeringId = cookieStore.get('active_offering_id');
  return offeringId?.value || null;
}

/**
 * Resolves the "active" course offering for a given user, safely scoped to
 * only offerings the user is authorized to access.
 *
 * Resolution order:
 *  1. The `active_offering_id` cookie ΓÇö validated against the user's access
 *  2. The user's first enrollment (for students)
 *  3. The first offering belonging to the user's assigned class (for reps)
 *  4. null ΓÇö if none of the above match
 *
 * A Class Representative is only ever shown an offering for their specific
 * classId, preventing cross-class data leakage.
 */
export async function resolveAuthorizedOffering(scope: UserScope): Promise<any | null> {
  const includeRelations = { unit: true, term: true, class: true };

  const isRep = scope.roles.some(
    (r: any) => r.role === 'CLASS_REPRESENTATIVE' || r.role === 'PLATFORM_ADMIN'
  );

  // Determine which classIds this user is authorized to access as a rep
  const repClassIds = scope.roles
    .filter((r: any) => r.role === 'CLASS_REPRESENTATIVE' && r.classId)
    .map((r: any) => r.classId);
  const isPlatformAdmin = scope.roles.some((r: any) => r.role === 'PLATFORM_ADMIN');

  // Step 1: Try the cookie value, but validate it
  const cookieOfferingId = getActiveOfferingId();
  if (cookieOfferingId) {
    const offering = await db.courseOffering.findUnique({
      where: { id: cookieOfferingId },
      include: includeRelations,
    });

    if (offering) {
      // Platform admins can see any offering
      if (isPlatformAdmin) return offering;

      // Reps can only see offerings for their assigned class
      if (repClassIds.length > 0 && repClassIds.includes(offering.classId)) return offering;

      // Students can only see offerings they are enrolled in
      if (!isRep) {
        const enrollment = await db.enrollment.findFirst({
          where: { studentId: scope.userId, offeringId: offering.id },
        });
        if (enrollment) return offering;
      }
    }
    // Cookie pointed to an unauthorized or deleted offering ΓÇö fall through
  }

  // Step 2: For students ΓÇö try to find an offering where they have an active group membership first
  if (!isRep) {
    const latestMembership = await db.groupMembership.findFirst({
      where: { studentId: scope.userId },
      orderBy: { joinedAt: 'desc' },
      include: { group: { include: { offering: { include: includeRelations } } } }
    });

    if (latestMembership?.group?.offering) {
      return latestMembership.group.offering;
    }

    // Fallback to the most recent enrollment if they have no groups
    const firstEnrollment = await db.enrollment.findFirst({
      where: { studentId: scope.userId },
      orderBy: { createdAt: 'desc' },
      include: { offering: { include: includeRelations } },
    });
    if (firstEnrollment) return firstEnrollment.offering;
  }

  // Step 3: For reps ΓÇö use first offering belonging to their class
  if (repClassIds.length > 0) {
    const repOffering = await db.courseOffering.findFirst({
      where: { classId: { in: repClassIds } },
      orderBy: { createdAt: 'desc' },
      include: includeRelations,
    });
    if (repOffering) return repOffering;
  }

  // Step 4: Platform admins fall back to the globally most-recent offering
  if (isPlatformAdmin) {
    return db.courseOffering.findFirst({
      orderBy: { createdAt: 'desc' },
      include: includeRelations,
    });
  }

  return null;
}

import { logInfo, logError } from '@talora/observability';
import { db } from '@talora/database';
import { hashPassword } from '@talora/auth';
import { Worker } from 'bullmq';
import { parse } from 'csv-parse';

import IORedis from 'ioredis';

const connection = new IORedis(process.env.REDIS_URL || 'redis://localhost:6379', {
  maxRetriesPerRequest: null
});

logInfo('Talora Background Worker starting...', { module: 'Worker', action: 'INIT' });

const worker = new Worker('import-jobs', async (job) => {
  logInfo(`Processing import job ${job.id}`, { module: 'Worker', action: 'PROCESS_IMPORT', jobId: job.id });
  
  const { csvString, offeringId } = job.data;
  
  if (!csvString || !offeringId) {
    throw new Error('Missing csvString or offeringId in job data');
  }

  // Parse CSV
  const rows: any[] = await new Promise((resolve, reject) => {
    parse(csvString, {
      columns: true,
      skip_empty_lines: true,
      trim: true
    }, (err, records) => {
      if (err) reject(err);
      else resolve(records);
    });
  });

  const offering = await db.courseOffering.findUnique({
    where: { id: offeringId },
    include: { term: true }
  });
  if (!offering) throw new Error('Offering not found');

  // Example expected headers: FullName, Email, StudentNumber
  let importedCount = 0;
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const email = row.Email;
    
    // Formula injection protection
    const safeStudentNum = row.StudentNumber?.startsWith('=') || row.StudentNumber?.startsWith('+') || row.StudentNumber?.startsWith('-') || row.StudentNumber?.startsWith('@') ? `'${row.StudentNumber}` : row.StudentNumber;
    const fullName = row.FullName || 'Unknown Student';
    const studentNumber = safeStudentNum || `SN-${Math.floor(Math.random() * 1000000)}`;

    if (!email) continue;

    // Report progress
    await job.updateProgress(Math.floor((i / rows.length) * 100));

    // Create or find user
    let user = await db.user.findUnique({ where: { email } });
    if (!user) {
      const passwordHash = await hashPassword('temporary-password-123');

      user = await db.user.create({
        data: {
          email,
          fullName,
          studentNumber,
          passwordHash,
          institutionId: offering.term.institutionId
        }
      });
      
      // Also give them student role
      await db.userRole.create({
        data: {
          userId: user.id,
          role: 'STUDENT',
          classId: offering.classId
        }
      });
    }

    // Create enrollment if not exists
    const existingEnrollment = await db.enrollment.findUnique({
      where: {
        studentId_offeringId: {
          studentId: user.id,
          offeringId: offeringId
        }
      }
    });

    if (!existingEnrollment) {
      await db.enrollment.create({
        data: {
          studentId: user.id,
          offeringId: offeringId
        }
      });
      
      // Send notification
      await db.notification.create({
        data: {
          userId: user.id,
          title: 'You have been enrolled!',
          message: `You were enrolled in a new class via bulk import. Welcome!`
        }
      });

      importedCount++;
    }
  }

  await job.updateProgress(100);
  logInfo(`Import job ${job.id} completed. Enrolled ${importedCount} students.`, { module: 'Worker', action: 'COMPLETE_IMPORT', jobId: job.id });
  return { success: true, importedCount, totalRows: rows.length };
}, { connection });

worker.on('failed', (job, err) => {
  logError(`Job ${job?.id} failed`, err, { module: 'Worker', action: 'JOB_FAILED' });
});

logInfo('Worker ready and listening on import-jobs queue.', { module: 'Worker', action: 'READY' });
